pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A gap is "dead" if no future item (min size 1) can plausibly use it well;
    // gaps below ~15 are almost always waste.
    let gap = post_residual as f64;
    if post_residual < 15 {
        score += 120.0 + (15.0 - gap) * 8.0; // dead-space penalty
    } else if post_residual < 30 {
        score += 25.0 + (30.0 - gap) * 2.0; // semi-dead gap penalty
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = post_residual - next_item_size;
        if next_fit < 15 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    }
    // Penalize leaving a gap that blocks the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // New-bin candidate: only attractive when existing bins are mostly full
    // or the item fits nothing well.
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score = 60.0 + mean_fullness * 40.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if post_residual == 0 {
            score = 0.0; // unreachable, keep safe
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Harmonic class of the leftover space: leftovers divisible by common
    // size classes (10/20/25/50) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill is ideal
    } else {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 20 == 0 { bonus += 4.0; }
        if pr % 25 == 0 { bonus += 4.0; }
        if pr % 50 == 0 { bonus += 6.0; }
        score -= bonus;

        // Dead zone: tiny unusable leftovers are bad.
        if pr < 10 {
            score += 50.0;
        }
    }

    // Lookahead coupling: does post_residual harmonically match next item?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // next item fills bin exactly
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap < 10 {
                score += 25.0; // leaves dead space for next item
            } else if gap % 10 == 0 {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // competition: mild penalty to spread load
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate: only attractive when existing residuals are poor.
    if bin_residual == bin_capacity {
        let bad_existing = mean_residual / bin_capacity as f64;
        score = 45.0 + 30.0 * bad_existing - 10.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0;
        }
        if step_index + 1 >= total_items {
            score += 100.0; // never open a bin for the last item
        }
    }

    // Late-stream consolidation: prefer filling existing bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead gap nothing can ever fill
    } else if post_residual < 20 {
        score += 25.0; // near-dead gap (items >=10, so only tiny items fit)
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward
    }

    // Reward tight fits relative to bin capacity (fill fraction).
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits exactly in the post-residual, reward; if it
    // would leave a dead gap, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            score += 8.0; // next item can't use this bin's leftover
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing residuals are fragmented (high mean residual spread) or the
    // current fit is poor.
    if bin_residual == bin_capacity {
        // Baseline cost of a new bin; offset by potential of full capacity.
        score = 55.0 - 0.3 * (mean_residual - post_residual as f64).abs();
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space avoidance: small non-zero gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Favor bins whose residual is well above the next item's need,
    // so the lookahead item can still fit here later.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += (next_item_size - post_residual as u32) as f64 * 0.3;
        }
    }

    // Open-bin pressure: penalize creating new bins when many are open,
    // but reward using the last-chance bin before opening a new one.
    score += open_bins_count as f64 * 0.5;
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Early in the stream, allow opening fresh bins more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score = 40.0 + progress * 20.0 - open_bins_count as f64 * 0.2;
        if fitting_bins_count == 1 {
            score += 100.0; // never open a new bin when a last-chance bin exists
        }
    }

    // Slight nudge toward tighter bins overall (best-fit flavor).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain fit: post_residual consumed by next item
        } else if post_residual >= next_item_size {
            // next item fits but leaves further slack; mild reward scaled by tightness
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack_after_next * 2.0;
        } else {
            // next item cannot fit here: penalize small dead space more when it is close to fitting
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 3.0;
        }
    }

    // Penalize post_residual in the awkward zone (1..=9): nearly unusable dead space.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when no good chaining exists.
    if bin_residual == bin_capacity {
        // Base penalty so full bins are preferred, unless open bins are crowded.
        score += 150.0;
        // Early in stream or many open bins: opening new bins is cheap/fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 100.0;
        // If mean residual across open bins is low (bins nearly full), new bin is good.
        if mean_residual < item_size as f64 {
            score -= 120.0;
        }
        // If the next item is large, starting a fresh bin preserves flexibility.
        if next_item_size >= 60 {
            score -= 80.0;
        }
    }

    // Mild preference for filling fuller bins relative to the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Prefer bins among many fitting candidates by tightness of fit.
    if fitting_bins_count > 1 {
        score += (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1..10)
    // are pure waste; penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Medium gaps can still be filled by small items; mild penalty.
        score += 0.5 * (post_residual as f64 - 10.0);
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Penalize a gap that just barely fails to fit the next item (dead space for k=2).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score += 12.0;
    }

    // Open-bins pressure: prefer bins already open over spawning new ones.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize bins whose residual deviates wildly from the mean (fragmentation).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: make it attractive only when the current fit is bad
    // (large post_residual) or when many bins are already open.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score -= 25.0 - 30.0 * fit_quality + 0.5 * open_bins_count as f64;
    }

    // Early in the stream, allow slightly more freedom to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    // Mild preference for tighter fits overall.
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

