pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits but leaves a gap; penalize proportional to gap
            let gap = (post_residual - next_item_size) as f64;
            score -= 200.0 - 0.5 * gap;
        } else {
            // next item cannot fit here; penalize tight residuals
            score += 0.3 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize bins far below mean residual (wasteful dead space)
    score += 0.8 * (mean_residual - post_residual as f64).max(0.0);

    // Slight preference for tighter fits relative to bin residual
    score += 0.2 * (bin_residual as f64 - item_size as f64 - post_residual as f64);

    // New-bin candidate: mild penalty so it's chosen only when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small for any plausible item (1..100).
        if post_residual < 10 {
            score += 50.0; // unusable sliver
        } else if post_residual <= 20 {
            score += 10.0;
        }

        // 2-step lookahead: reward when the next item fits exactly in post_residual.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 800.0;
            } else if next_item_size <= post_residual {
                // Reward proportionally to how well next item uses remaining space.
                let usage = next_item_size as f64 / post_residual as f64;
                score -= 200.0 * usage;
                // Extra bonus if next item leaves another clean fit.
                let post2 = post_residual as i64 - next_item_size as i64;
                if post2 == 0 {
                    score -= 300.0;
                } else if post2 < 10 {
                    score += 20.0; // next placement would create sliver
                }
            } else {
                // Next item won't fit here; penalize wasting space that could have been planned.
                score += 30.0;
            }
        }

        // Compare against mean residual: prefer bins tighter than average.
        score -= 0.5 * (mean_residual - post_residual as f64);

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 150.0;
        }
    }

    // New-bin candidate handling: mildly discourage opening a new bin unless
    // the item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // New bins are fine for big items late in the stream, penalized otherwise.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 60.0 * large_item - 20.0 * progress;
        // If many bins are open, discourage adding more.
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // "Unusable small gap" band: quadratic dead-space penalty.
        score += (20.0 - post_residual as f64) * 2.5;
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= (bin_capacity as f64 - post_residual as f64 / 2.0) * 0.15;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening yet another.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += open_bins_count as f64 * 1.2;
        // New bin is only attractive if the current bin leaves a bad gap
        // or cannot host the lookahead item.
        if post_residual >= 10 && (next_item_size == 0 || post_residual >= next_item_size) {
            score += 15.0;
        }
    }

    // Lookahead coupling: reward bins whose post_residual can host next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += post_residual as f64 * 0.3; // stranded space relative to lookahead
    }

    // Mean residual coupling: prefer bins deviating below mean residual
    // (compact the emptiest bins first, keep tight bins tight).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Slight late-stream tightening: as stream progresses, favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = x * x * (1.0 - x) * (1.0 - x); // peaks at x=0.5, penalizes extremes
    let mut score = pr * (1.0 + 0.9 * poly) - 12.0 * progress * poly * cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - x) * (1.0 - x) * (20.0 + 30.0 * progress);

    // Penalize dead space that cannot fit a typical next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (1.5 + 2.0 * progress);
        } else {
            score -= 0.5 * ((pr - nx) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild penalty for proliferating open bins early on.
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    // Smooth coupling with mean residual: prefer bins near the mean.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless current bin would be wasted.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        + 12.0 * (pr / cap) * (pr / cap) * (0.5 + progress)
        - 20.0 * (pr / cap) * (1.0 - progress) * (1.0 - progress);

    // Penalize dead space that cannot fit the lookahead item (smooth quadratic)
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 25.0 * gap * gap * cap;
    }

    // Reward placements that leave room for the next item (smooth coupling)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = pr - next_item_size as f64;
        score -= 10.0 * (slack / cap) * (1.0 - slack / cap);
    }

    // Last-chance bonus: smooth sigmoid-like reward when few fitting bins
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 15.0 * scarcity * (pr / cap) * (1.0 - pr / cap);

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.5 * (open_bins_count as f64).sqrt() * progress * (pr / cap);

    // Tie-break toward bins tighter than the mean residual (smooth quadratic)
    score += 3.0 * ((pr - mean_residual) / cap) * ((pr - mean_residual) / cap);

    // New-bin candidate: prefer it only when residuals are highly fragmented
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress) - 4.0 * (mean_residual / cap);
    }

    score
}

