    // it's a good "garbage collector" bin for this item.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward keeping this pairing alive.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 / (1.0 + slack);
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
            // next item cannot use this gap: mild penalty for stranding space
            score += 5.0;
        }
    }

    // New-bin candidate: opening a new bin is only attractive when it can
    // host future items (large residual). Penalize default new-bin choice
    // unless existing bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 30.0 - 20.0 * fragmentation;
        if fitting_bins_count > 0 {
            score += 15.0; // don't open new bins when a fit exists
        }
    }

    // Stream progression: late in the stream, avoid leaving any slack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - waste);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
