    // very small post_residual is great, but exact-zero waste is best.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits into the resulting residual, reward it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            // next item fits exactly or near-exactly after this placement
            let gap = post - nxt;
            score -= 10.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
