        score += 1.5 * (open_bins_count as f64).ln().max(0.0) * 10.0;

        // If the current item is large relative to capacity, a fresh bin gives
        // maximum flexibility for it and the lookahead item.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.5 {
            score -= 8.0 * (frac - 0.5);
        }

        // If next item is large too, fresh bin pairs them well.
        if next_item_size as f64 / bin_capacity as f64 > 0.5 {
            score -= 5.0;
        }
