        // Existing bin: penalize when its residual is far from mean (fragmentation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.03 * dev;

        // Mild penalty per open bin for using existing stock when it's abundant —
        // encourages balancing load across bins, reducing extreme fragmentation.
        score += 0.02 * open_bins_count as f64;

        // Reward consuming bins with large residuals when item is large
        // (drain oversized holes with big items).
        let big_item = item_size as f64 / bin_capacity as f64;
        let big_hole = bin_residual as f64 / bin_capacity as f64;
        if big_item > 0.6 && big_hole > 0.6 {
