    // Global pressure: when mean residual across bins is low (bins nearly full),
    // opening a new bin is more acceptable; using a nearly-full bin is precious.
    let mean_frac = mean_residual / bin_capacity as f64;
    if mean_frac < 0.15 && bin_residual != bin_capacity {
        score += 5.0 * (0.15 - mean_frac);
