pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = pr;

    // Quadratic/cubic dead-space penalty, amplified as the stream progresses.
    let dead = pr_norm * pr_norm;
    score += 40.0 * dead * (0.3 + 0.7 * progress);

    // Cubic interaction: large residuals late in the stream are strongly penalized.
    score += 60.0 * pr_norm * pr_norm * pr_norm * progress;

    // Tight fits (small post_residual) are rewarded, more so early on.
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - 0.5 * progress);

    // Last-chance bin: reward it smoothly, stronger late in the stream.
    if fitting_bins_count == 1 {
        score -= 30.0 * (0.5 + 0.5 * progress);
    }

    // Penalize bins that deviate from the mean residual (keeps residual spread tight).
    score += (pr - mean_residual).abs() * (0.2 + 0.4 * progress);

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        if diff >= 0.0 {
            score -= 20.0 * (-8.0 * diff * diff).exp() * (1.0 - 0.4 * progress);
        } else {
            score += 15.0 * (-4.0 * diff * diff).exp();
        }
    }

    // Slight preference for consolidating into fewer bins as stream ends.
    score -= 2.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by which item
    // classes (mod-based size buckets) it can still accommodate.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class 1: post_residual < smallest plausible item (<= 10) -> dead space, penalize.
    // Class 2: post_residual can host a "medium" item (11..40) -> mild reward.
    // Class 3: post_residual >= 40 -> flexible, reward but not excessively (large residual
    //          means we underfilled the bin).

    if post_residual == 0 {
        score -= 50.0; // perfect closure
    } else if post_residual <= 10 {
        // dead space: nothing in [1,100] range reliably fits small gaps;
        // penalize proportionally to how much capacity was wasted.
        score += (11.0 - post_residual as f64) * 6.0;
    } else {
        // Integer-division thresholds on post_residual: which harmonic size
        // classes still fit? Sizes bucketed by modulo-20 classes.
        let fits_small = (post_residual >= 20) as f64;
        let fits_medium = (post_residual >= 40) as f64;
        let fits_large = (post_residual >= 60) as f64;
        score -= 4.0 * fits_small + 6.0 * fits_medium + 4.0 * fits_large;
    }

    // Coupling with next_item_size: reward if this bin's post_residual can
    // host the lookahead item (k=2 lookahead chain preservation).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact modulo-style match bonus: residual close to next item
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 30.0; // next item would perfectly close this bin
            } else {
                score -= 10.0;
                // penalize leaving a dead gap for the next item
                if slack <= 10 {
                    score += (11.0 - slack as f64) * 2.0;
                }
            }
        } else {
            // this bin cannot host the next item: mild penalty scaled by
            // how far off, using integer division on next_item_size class
            let class_gap = (next_item_size - post_residual) as f64;
            score += class_gap * 0.3;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has high residual; make it
    // attractive only when open bins are nearly saturated or the fit is bad.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 15.0;
        // more attractive early in the stream or when few bins are open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        score -= (open_bins_count.min(20) as f64) * 0.5;
        // if current fit is terrible (huge dead space), new bin wins
        if item_size < bin_residual {
            let waste = bin_residual - item_size;
            if waste <= 10 {
                score += 20.0; // opening new bin avoids creating dead space
            }
        }
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual
    // (tighter bins) to keep many medium residuals available.
    let res = post_residual as f64;
    if res > mean_residual {
        score += (res - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - res) * 0.05;
    }

    // Fraction-of-capacity harmonic penalty: post_residuals just under
    // common item sizes (mod 10 classes) are trap states.
    let mod10 = post_residual % 10;
    if mod10 != 0 && post_residual > 0 {
        score += mod10 as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit anything
    // (smallest item is 1, but practically gaps < ~15 are hard to reuse)
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 * (1.0 - post_residual as f64 / 15.0);
    }
    if post_residual == 0 {
        // Perfect fit is maximally rewarded
        score -= 100.0;
    } else {
        // Reward tight fits relative to item size
        score -= 2.0 * item_size as f64 / post_residual as f64;
    }

    // Penalize bins whose residual is far above the mean (fragmenting)
    score += 0.5 * ((bin_residual as f64 - mean_residual).abs());

    // Open-bin pressure: encourage closing out bins when many are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward leaving that gap; otherwise penalize blocking it.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 30.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

