    // no open bin offers a decent home, or many bins are open.
    if bin_residual == bin_capacity {
        score += 40.0;
        if item_size >= 70 && (fitting_bins_count == 0 || open_bins_count > 8) {
            score -= 55.0;
        }
        if open_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (low dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: reward when the leftover space matches the next item well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 400.0; // perfect chain: next item exactly fills the remainder
        } else if (post_residual as f64 - next).abs() <= 3.0 {
            score -= 150.0; // near-perfect chain
        } else if post_residual as f64 > next {
            score -= 30.0; // next item still fits here afterwards
        } else {
            // next item won't fit; penalize proportionally to wasted potential
            score += (next - post_residual as f64).min(40.0) * 0.8;
        }
    }

    // Compare against mean residual: bins tighter than average are good targets.
    let res = post_residual as f64;
    if res < mean_residual - 10.0 {
        score -= 40.0;
    } else if res > mean_residual + 20.0 {
        score += 30.0;
    }

    // Last-chance bin before opening a new bin: strong bonus to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 300.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 100.0; // big item followed by big item: fresh bin is fine
        }
    }

    // Late in the stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Exact-fill jackpot.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        // Dead space smaller than the minimum item is nearly worthless.
        score -= 8.0;
    } else if post_residual > 60 {
        // Leaving a large hole wastes the bin's potential.
        score += (post_residual as f64 - 60.0) * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, use it
    // to avoid opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
            if post_residual == next_item_size {
                score -= 10.0; // perfect chain
            }
        } else {
            // leftover too small for the known next item: mild penalty
            score += 2.0;
        }
    }

    // New-bin candidate logic: only attractive when no open bin is a good home,
    // i.e. when mean residual is small relative to the item or many bins are open.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / (item_size as f64);
        if pressure < 1.0 {
            // open bins are collectively tight; opening a new bin is fine
            score -= 4.0 + (1.0 - pressure) * 6.0;
        } else {
            // plenty of slack elsewhere; discourage new bins
            score += 10.0 + pressure * 3.0;
        }
        // late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
        // many open bins already: discourage spreading further
        score += open_bins_count as f64 * 0.8;
    }

    // Mild preference for fuller bins overall (best-fit flavor).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping over stream progress
    let mut score = pr;

    // Smooth polynomial coupling: dead-space penalty grows with progress
    let dead = norm_pr * norm_pr; // quadratic waste term
    score += 40.0 * dead * (0.5 + progress);

    // Cubic interaction: small residuals late in stream are costly
    score += 15.0 * norm_pr.powi(3) * progress;

    // Reward tight fits (near-zero post residual) more strongly as stream advances
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Lookahead coupling: if next item fits in the post-residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 8.0 * (nxt - pr) / cap * (1.0 + progress);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr * norm_pr);
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Mean-residual deviation: prefer bins near mean residual (keeps balance)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: keep it attractive early, discourage late
    if bin_residual == bin_capacity {
        score = pr + 30.0 * (1.0 - progress) - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "reusable"
    // classes (multiples of common item sizes / large enough for future items)
    // are more valuable than bins with tiny dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Class 1: post_residual >= 50 (half-bin or more) -> very reusable.
    if post_residual >= bin_capacity / 2 {
        score -= 8.0 * frac;
    }
    // Class 2: post_residual in [20, 50) -> moderately reusable.
    else if post_residual >= 20 {
        score -= 3.0;
    }
    // Class 3: post_residual in (0, 20) -> near-dead space, penalize.
    else if post_residual > 0 {
        score += 6.0;
    }
    // Class 4: perfect fit (post_residual == 0) -> best possible.
    else {
        score -= 15.0;
    }

    // Integer-division harmonic classes: leftover divisible by 10 aligns with
    // typical item granularities, making it more likely to be filled exactly.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: does this bin still serve the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bin remains usable for the lookahead item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 + slack / cap;
        } else {
            // Bin becomes dead after this placement; penalize proportionally
            // to how much of the remaining space is wasted.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 + (bin_residual - item_size) as f64 * 0.05;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // bins have poor fits. Give the empty bin a baseline that competes with
    // moderately bad placements but loses to good ones.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: slightly worse than a decent fit.
        score += 10.0;
        // Late in the stream, opening new bins is riskier (fewer future items
        // to fill them), so make fresh bins progressively less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
        // If many bins are open, prefer consolidating into them.
        score += (open_bins_count as f64).min(20.0) * 0.3;
    }

    // Mild pull toward bins whose residual is below the mean residual
    // (tighter bins get filled first, keeping loose bins flexible).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any
    // future item (min size 1..100, but typical small items >= ~10)
    // are the worst waste. Penalize unusable gaps extra hard.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits (post_residual close to 0) more than
    // linear score already does.
    if post_residual <= 3 {
        score -= 15.0;
    } else if post_residual <= 8 {
        score -= 6.0;
    }

    // Penalize mid-range residuals that are likely dead space for
    // common item sizes: gaps in [11..30] often can't be filled well.
    if post_residual >= 11 && post_residual <= 30 {
        score += (30 - post_residual) as f64 * 0.8;
    }

    // Last-chance bin pressure: if this is the only bin that fits,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins
    // are already open; encourage consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins are crowded
        // with small residuals (little usable space overall).
        let crowded = mean_residual / bin_capacity as f64;
        score += 20.0 + open_bins_count as f64 * 3.0 - crowded * 40.0;
    } else {
        score += open_bins_count as f64 * 0.05;
    }

    // Lookahead: if the next item fits exactly in this bin's post
    // residual, reward strongly (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_left = post_residual - next_item_size;
            if next_left <= 3 {
                score -= 12.0;
            }
        } else {
            // next item cannot use this residual: mild penalty for
            // leaving residual that blocks the known next item.
            score += 3.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins to
    // build flexibility; late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    } else {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 100.0; // near-perfect fit, dead space unusable
    }

    // 2-step lookahead: does the next item fit into the leftover space?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain placement possible: reward proportional to tightness of the chain.
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 60.0 * chain_tightness;
        } else {
            // Leftover cannot host next item: penalize dead space, worse for large leftovers.
            let waste = post_residual as f64;
            score += 0.5 * waste;
            // If next item is large, leftover is even less likely useful later.
            if next_item_size > bin_capacity / 2 {
                score += 20.0;
            }
        }
    }

    // Compare residual against mean residual: prefer bins that stay near/below average fill.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter fits: relative ranking already via post_residual.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New empty bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 150.0;
        // If the item barely fits an open bin context, discourage new bin more.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 30.0; // big items: fresh bin sometimes justified
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 40.0; // pairing impossible anyway; new bin can host the pair
        }
    }

    // Late-stream pressure: consolidate into fewer bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 25.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit gets a huge bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 25.0 * next_fit_quality;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post-residual too small for next item: penalize dead space proportionally
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate penalty: discourage opening new bins unless residuals are scarce
    if bin_residual == bin_capacity {
        let scarcity = if mean_residual > 0.0 { (item_size as f64 / mean_residual).min(1.5) } else { 1.5 };
        let time_frac = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 + 20.0 * scarcity + 15.0 * (1.0 - time_frac);
        // Allow new bin late in stream when many bins are open and fragmented
        if open_bins_count > 4 && mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier space usage)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Penalize leaving residuals in the awkward 1..10 dead zone
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Quadratic penalty on wasted space, amplified as stream progresses
    let waste = norm_pr * norm_pr;
    score += 40.0 * waste * (0.5 + progress);

    // Cubic coupling: late in the stream, dead space is increasingly costly
    score += 25.0 * waste * norm_pr * progress * progress;

    // Reward last-chance bins (avoid opening a new bin when only one fits)
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Slight penalty for spreading across many open bins
    score += (open_bins_count as f64) * 0.05 * norm_pr;

    // Lookahead: bonus if next item fits the resulting residual well
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 6.0 * fit_quality * (1.0 - progress);
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty for very small residuals
        score += 4.0 * waste;
    }

    // Nudge toward bins below mean residual (consolidating space)
    score += 0.3 * (mean_residual - pr).max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavy reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover: capacity fractions.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Dead-space class: leftover in (0, 10) is nearly unusable (items >= 1 though,
    // so grade by how well next_item_size can reuse it).
    if next_item_size > 0 && next_item_size <= post_residual {
        // Lookahead fits: reward proportional to how snugly it fills.
        let snug = (post_residual - next_item_size) as f64;
        score -= 50.0 + snug * 0.5;
    } else if next_item_size > 0 {
        // Lookahead cannot use this leftover: penalize small unusable slivers hard.
        let sliver = post_residual as f64;
        score += (10.0 - sliver.min(10.0)) * 3.0;
    }

    // Integer-division thresholds on post_residual: classify leftover utility.
    let cls = post_residual / 10; // 0..10 harmonic class
    match cls {
        0 => score += 40.0,           // 1..9: nearly dead space
        1 => score += 10.0,           // 10..19: only tiny items fit
        2 | 3 => score -= 5.0,        // 20..39: mid-range usable
        4 | 5 => score -= 12.0,       // 40..59: good leftover
        _ => score -= 20.0,           // 60+: very reusable
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when current leftovers are poor and
    // the item is large (would leave a fragmented residual elsewhere).
    if bin_residual == bin_capacity {
        let poor_fits = (mean_residual - post_frac * cap).abs(); // dummy coupling
        let _ = poor_fits;
        let new_bin_base = 55.0 + post_frac * 0.0;
        // Penalize new bin mildly; escalate when item is big and mean residual is small.
        let item_frac = item_size as f64 / cap;
        let pressure = if mean_residual < item_frac * cap { 1.0 } else { 0.0 };
        return new_bin_base + 30.0 * pressure - (next_item_size as f64) * 0.1;
    }

    // Prefer tighter bins overall: closeness of fit reward.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 15.0;

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
