    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual > item_size as f64 * 1.2;
        if decent_fit_exists {
            score += 250.0; // keep using open bins
        } else {
            score -= 20.0; // opening fresh is fine
        }
    }

    // Lookahead: if next item fits the post-residual well, reward this placement
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap <= 10.0 {
