    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize new-bin candidate unless current residual is unusably small.
    if bin_residual == bin_capacity {
        if bin_residual < item_size + 10 {
            score -= 50.0;
        } else {
            score += 25.0;
        }
    }

    // Late in stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Small residual dead-space penalty (nonlinear).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small to fit typical future items.
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 25.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for blocking.
        score += 5.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Mild opening cost, scaled by how many bins already fit the item.
        score += 15.0 + 10.0 * fitting_bins_count as f64;
        // Early in stream, prefer reusing (exploration later).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is attractive.
        if next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.05 * consolidation;
        score += 0.5 * open_bins_count as f64;
    }

    // Time horizon: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Stream progress coupling: late in the stream, tolerate residual less (pack tighter).
    let late = progress * progress;
    score += late * post * 0.5;

    // Dead-space penalty: residuals too small for typical items are worthless.
    let dead = ((norm_post - 0.1).max(0.0)) * ((0.35 - norm_post).max(0.0));
    score -= dead * cap * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward residual that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 5.0;
        }
    }

    // Crowding: with many open bins, slightly prefer consolidating into fuller bins.
    score += (open_bins_count as f64).ln().max(0.0) * norm_post * 2.0;

    // Deviation from mean residual: prefer bins near the mean to balance.
    score += ((post - mean_residual) / cap).abs() * 10.0;

    // New-bin candidate: penalize opening a fresh bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * (1.0 - progress) + 0.5 * post;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: capacity fractions ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    // Class boundaries: dead space (< 10 is unusable for min item size 1, but small
    // residuals below ~1/4 capacity are "harmonic dead zones").
    let quarter = cap * 0.25;
    let half = cap * 0.5;

    // Exact fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: post_residual too small to be useful later.
    if post_residual > 0 && post_residual < quarter as u32 {
        // Harmonic class A: near-dead residual. Penalize proportionally to how dead.
        score += (quarter - post) * 2.0;
    }

    // Sweet spot: residual in [quarter, half] is a good harmonic class (fits many
    // mid-size items). Reward it.
    if post_residual >= quarter as u32 && post_residual <= half as u32 {
        score -= 15.0;
    }

    // Integer-division thresholds on post_residual: residual mod 10 measures
    // alignment with typical item granularity.
    let post_mod = post_residual % 10;
    if post_mod == 0 && post_residual > 0 {
        score -= 8.0; // aligned residual is more reusable
    } else {
        score += post_mod as f64 * 0.5; // misalignment penalty
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // next item cannot use this residual: penalize by wasted amount
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when placing here would create severe dead space or
    // the item is huge relative to residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; relax late in the stream or when
        // many bins are open (spreading load can help future items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 60.0 - 20.0 * progress;
        if post_residual == 0 {
            new_bin_cost = 5.0; // item exactly fills a fresh bin: cheap
        }
        // If current bin would leave a tiny dead residual, new bin becomes attractive.
        if post_residual > 0 && post_residual < quarter as u32 {
            new_bin_cost -= (quarter - post) * 1.5;
        }
        score += new_bin_cost.max(0.0);
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (balanced packing); penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight preference for tighter bins overall.
    score += (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space avoidance: small non-zero gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Favor bins whose residual is well above the next item's need,
    // so the lookahead item can still fit here later.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += (next_item_size - post_residual as u32) as f64 * 0.3;
        }
    }

    // Open-bin pressure: penalize creating new bins when many are open,
    // but reward using the last-chance bin before opening a new one.
    score += open_bins_count as f64 * 0.5;
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Early in the stream, allow opening fresh bins more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score = 40.0 + progress * 20.0 - open_bins_count as f64 * 0.2;
        if fitting_bins_count == 1 {
            score += 100.0; // never open a new bin when a last-chance bin exists
        }
    }

    // Slight nudge toward tighter bins overall (best-fit flavor).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: if the next item exactly fills the post-residual,
    // this placement is ideal -- reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let slack = post - nxt;
            // Penalty grows quadratically with leftover after the next item fits.
            score += 0.35 * slack;
            score += 0.004 * slack * slack;
        } else {
            // Next item cannot use the leftover: dead space penalty.
            let dead = nxt - post;
            score += 0.25 * dead;
        }
        // Mild reward when post_residual stays close to mean residual (balance).
        score += 0.05 * (post - mean_residual).abs();
    }

    // Perfect fit bonus (bin fully consumed now).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, especially when other bins fit
    // or the item is small relative to the fresh capacity.
    if bin_residual == bin_capacity {
        score += 30.0 + (item_size as f64) * 0.2;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Early in the stream, prefer compacting into few bins to build useful residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; slight penalty for wasting residual
        score += 8.0;
    }

    // New-bin candidate logic: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_item = item_size as f64;
        // If mean residual is small (bins nearly full), opening a new bin is fine
        let pressure = mean_residual / bin_capacity as f64;
        score += 60.0 * pressure;
        score -= 15.0 * (1.0 - progress);
        // If many bins fit the item, discourage opening a new one
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // large items prefer fresh bins
        score -= (item_size as f64 / 80.0) * 10.0;
        let _ = avg_item;
    }

    // Mild bonus for placing into bins with residual close to mean (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling fuller bins (smaller residual) as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64) * 0.1;

    // Slight preference for keeping few open bins
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer small post residual (tight fit), scaled by capacity.
    let mut score = post / cap;

    // Quadratic dead-space penalty: tiny leftovers are hard to reuse.
    let post_frac = post / cap;
    score += 1.4 * post_frac * post_frac;

    // Cubic term: strongly punish near-full bins only when residual is truly dead.
    score += 0.8 * post_frac * post_frac * post_frac;

    // Smooth stream-progress coupling: as the stream advances, tighten packing
    // (favor tight fits more), while early on keep residual flexibility.
    let tightness_gain = (item_size as f64 / cap) * (0.5 + 1.5 * progress * progress);
    score -= tightness_gain * (1.0 - post_frac);

    // Lookahead: if the next item fits the post residual, reward this bin;
    // smooth sigmoid-like coupling rather than hard thresholds.
    if next_item_size > 0 {
        let fits = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        let gap = ((post_residual as f64) - (next_item_size as f64)).abs() / cap;
        score -= 0.9 * fits * (1.0 - gap).max(0.0) * (0.4 + 0.6 * progress);
        score += 0.3 * (1.0 - fits) * (next_item_size as f64 / cap);
    }

    // Last-chance bin: if this is the only bin that fits, heavily reward using it
    // to avoid opening a new bin, modulated by how much space is consumed.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.0 + (item_size as f64 / cap);
    }

    // Mean-residual awareness: placing into a bin far from the mean residual
    // balances the pool; smooth quadratic divergence penalty.
    let dev = ((bin_residual as f64) - mean_residual) / cap;
    score += 0.25 * dev * dev;

    // Mild penalty for accumulating many open bins early (encourage consolidation).
    score += 0.02 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate: make opening a new bin attractive only when the item
    // is large and few good fits exist; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        score = cap * 2.0 - (item_size as f64) * (fitting_bins_count as f64) * 0.35;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "dead zones" (small unusable slivers) are penalized.
    let pr = post_residual;
    if pr > 0 {
        let class = pr / 10; // capacity-fraction class (0..10)
        match class {
            0 => score += 15.0,          // 1..9: dead space sliver
            1 => score += 6.0,           // 10..19: awkward
            2 | 3 => score -= 2.0,       // 20..39: decent for mid items
            4 | 5 => score -= 5.0,       // 40..59: sweet spot
            6 | 7 => score -= 3.0,       // 60..79
            _ => score -= 1.0,           // 80+: near-empty bin
        }
    } else {
        score -= 20.0; // perfect fill — reward strongly
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // reward closeness of next fit
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
            // modulo harmony: next item leaves a multiple-of-10 residual
            if (pr - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize leftovers
            // that are too small for typical items
            if pr < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it
    // on a loose fit; prefer it when fit is tight.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - fit_ratio);
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // have poor fits. Penalize opening a new bin unless stream is early
    // or mean residual is large (fragmented bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize new bins generally; discount penalty when existing bins
        // are fragmented (high mean residual) or few bins open.
        score += 30.0 - 20.0 * fragmentation - 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 40.0; // must open first bin
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins),
    // pushing consolidation toward fuller bins.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 3.0 * (mean_residual - res_f) / bin_capacity as f64;
    } else {
        score += 3.0 * (res_f - mean_residual) / bin_capacity as f64;
    }

    // Small nudge toward using existing bins over new ones early in stream.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Treat gaps below a "usefulness threshold" (smallest plausible item zone)
    // as wasted space and multiply their cost.
    let dead_zone = 10.0; // below this, gap is nearly unusable
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Mild convex penalty on leftover: prefer filling bins densely.
        let pr = post_residual as f64;
        score += (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * 8.0;
    }

    // Reward leaving room for the lookahead item if it can fit in the gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Penalize if the next item would be blocked by this placement's gap.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.35;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first),
    // keeping large-residual bins available for large future items.
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: neutral baseline, slightly penalized so we only open
    // a new bin when open bins would create significant dead space.
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that is too small for any plausible item (1..100).
        if post_residual < 10 {
            score += 50.0; // unusable sliver
        } else if post_residual <= 20 {
            score += 10.0;
        }

        // 2-step lookahead: reward when the next item fits exactly in post_residual.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 800.0;
            } else if next_item_size <= post_residual {
                // Reward proportionally to how well next item uses remaining space.
                let usage = next_item_size as f64 / post_residual as f64;
                score -= 200.0 * usage;
                // Extra bonus if next item leaves another clean fit.
                let post2 = post_residual as i64 - next_item_size as i64;
                if post2 == 0 {
                    score -= 300.0;
                } else if post2 < 10 {
                    score += 20.0; // next placement would create sliver
                }
            } else {
                // Next item won't fit here; penalize wasting space that could have been planned.
                score += 30.0;
            }
        }

        // Compare against mean residual: prefer bins tighter than average.
        score -= 0.5 * (mean_residual - post_residual as f64);

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 150.0;
        }
    }

    // New-bin candidate handling: mildly discourage opening a new bin unless
    // the item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // New bins are fine for big items late in the stream, penalized otherwise.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 60.0 * large_item - 20.0 * progress;
        // If many bins are open, discourage adding more.
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the leftover relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: reward bins whose post-residual can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward when the next item fits snugly too.
        let chain_waste = post_residual - next_item_size;
        score -= 8.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that blocks the next item only slightly.
        if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin, more so early in the stream when
        // consolidation is cheap, less so near the end.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * (1.0 - 0.5 * progress);
        // If nothing else fits (or mean residual is tiny), allow opening.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    } else {
        // Mild preference for bins with residual close to the mean (balance load),
        // so we don't drain one bin while others stay fat.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Penalize creating tiny unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: prefer small post-residual, scaled by a smooth polynomial in progress.
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Non-linear dead-space penalty: quadratic blowup for tiny residuals.
    score += 40.0 * norm_pr * norm_pr * (1.0 - norm_pr).max(0.0);

    // Reward tight fits (post_residual small relative to item size) with smooth coupling.
    score -= 25.0 * fit * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Penalize bins whose residual deviates far from the mean (fragmentation control),
    // with a smooth cubic coupling to progress.
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * (1.0 + progress * progress * progress);

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 12.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets (dead-space classes).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Perfect fit: strongly reward zero or tiny post_residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Harmonic dead-space penalty: leftover space that no future item
    // (sizes 1..=100) can ever fill exactly is wasted. Penalize leftovers
    // in the "awkward" class (1..10) less than mid-range leftovers that
    // fragment the bin (11..50), since tiny leftovers are near-useless anyway.
    if post_residual >= 1 && post_residual <= 10 {
        score += 40.0; // nearly dead space
    } else if post_residual <= 30 {
        score += 15.0; // fragmenting
    }

    // Modulo arithmetic on post_residual: leftover that is a multiple of
    // common item sizes (10s) is reusable — reward divisibility classes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward proportionally to how snugly.
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 60.0 + 80.0 * snug;
        } else {
            // Next item cannot follow here: penalize, worse for big gaps.
            score += 30.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: opening a fresh bin wastes the residual
    // of this stream. Penalize the empty-bin candidate, but relax the
    // penalty late in the stream or when many bins are open and fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = bin_residual as f64 - item_size as f64;
        let mut new_bin_penalty = 120.0 + 0.8 * waste;
        // If mean residual across open bins is small (bins nearly full),
        // opening a new bin is more attractive.
        new_bin_penalty -= 0.5 * mean_residual;
        // Early stream: keep new-bin penalty high to consolidate.
        new_bin_penalty += 100.0 * (1.0 - progress);
        // Many open bins already: consolidation pressure weakens.
        new_bin_penalty -= 2.0 * open_bins_count as f64;
        score += new_bin_penalty.max(0.0);
    }

    // Prefer filling bins whose residual is already small relative to mean
    // (best-fit style tilt with harmonic scaling).
    score -= 10.0 * (1.0 - frac) * (item_size as f64 / cap);

    // Mild tie-break: older/earlier bins close sooner, reducing spread.
    score += 0.01 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        // Small gaps are unlikely to be usable later.
        score += 12.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Reward very tight fits (post_residual small but still usable).
    if post_residual > 0 && post_residual <= 5 {
        score -= 15.0;
    }

    // Prefer bins whose residual is close to the item (efficient packing).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 4.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 8.0; // next item can't use this gap -> dead space
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few bins, encourage using existing capacity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 30.0 * (1.0 - scarcity); // penalize new bin when alternatives exist
        if scarcity > 0.0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as u32 >= next_item_size {
            // Next item fits perfectly after this one -> strong reward.
            let match_quality = 1.0 - ((post_residual as f64 - next) / bin_capacity as f64);
            score -= 12.0 * match_quality;
        } else {
            // Dead space relative to the next item -> penalty.
            score += 3.0 * (next - post_residual as f64).min(next) / 10.0;
        }
    }

    // Prefer tight fits overall.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Penalize bins far from the mean residual (fragmentation risk).
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild preference for consolidating into fewer bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        score += 10.0 - 12.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Dead space for next item: penalize proportionally to waste
        score += 0.10 * (post_residual as f64);
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize relative to mean residual of open bins
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 10.0 * progress;
        // opening a bin is more attractive if open bins are nearly full on average
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 14.0;
        // with many open bins, prefer consolidating rather than opening
        score += 0.4 * (open_bins_count as f64).sqrt();
    }

    // Prefer filling bins with larger residual (larger item into larger gap)
    score -= 0.03 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: squared residual scaled by stream progress.
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Dead-space penalty grows quadratically with progress.
    let dead = (norm_pr / (cap / 20.0)).min(1.0);
    score += 25.0 * dead * dead * progress;

    // Perfect-fit reward (smooth, not piecewise).
    let fit_quality = 1.0 - (pr / cap);
    score -= 15.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Lookahead: penalize blocking the next item, reward leaving room for it.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 8.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 6.0 * (n - pr) / cap;
        }
    }

    // Prefer bins tighter than the mean residual (smooth interaction).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev - 4.0 * dev;

    // Mild bias against opening new bins when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let q = post_residual / 10; // 0..10 classes
    // Penalize residuals that are too small to host typical future items (1..100 range).
    // Small-but-nonzero residuals are the worst dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        score -= 45.0; // perfect fill: strongly reward
    } else {
        // Non-linear penalty: dead space weighted by how far below half-capacity it is.
        let frac = post_residual as f64 / cap;
        if frac < 0.25 {
            score += (0.25 - frac) * 80.0;
        } else if frac > 0.5 {
            score -= (frac - 0.5) * 30.0; // roomy leftovers are reusable
        }
        // Harmonic bonus: residual divisible into useful chunks (mod classes)
        if post_residual % 25 == 0 {
            score -= 12.0;
        } else if post_residual % 10 == 0 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly into post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            let nr = post_residual - next_item_size;
            // penalize double-fragmentation
            if nr > 0 && nr < 10 {
                score += 25.0;
            } else if nr % 10 == 0 {
                score -= 15.0;
            }
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    } else {
        // last item: prefer tightest fill
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit
    // (i.e., current bin is empty) or when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            // how bad are existing options? compare item to mean residual
            let gap = (mean_residual - item_size as f64).max(0.0);
            gap
        };
        score = cap * 0.45 + desperation * 0.6
            - (post_residual as f64) * 0.1
            + if fitting_bins_count == 1 { 55.0 } else { 0.0 };
        // Late in the stream, slightly discourage spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // If many bins are open, prefer reusing one.
        score += open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (min size 10)
    // can use are pure waste — penalize them quadratically.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 8.0 + 20.0;
    }

    // Near-perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward placements that leave a gap still usable by typical items,
    // especially when it can hold the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap is dead relative to lookahead: extra penalty scaled by tightness
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, favor consolidating into
    // bins that already have low residual (reduce bin count long-term).
    score += (open_bins_count as f64) * 0.15 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for emptier bins early, tighter bins late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (bin_residual as f64 - mean_residual) * 0.05;

    // New-bin candidate: keep it neutral-ish, but discourage opening a new
    // bin unless the fit into existing bins is genuinely bad (large dead space).
    if bin_residual == bin_capacity {
        score += 25.0;
        // If current item is large, a fresh bin is more attractive.
        score -= (item_size as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: only attractive if no decent fit exists.
    if bin_residual == bin_capacity {
        let penalty = 60.0
            - 25.0 * (fitting_bins_count as f64).min(3.0)
            - 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        score += penalty.max(0.0);
        return score;
    }

    // Exact 2-step lookahead match: post_residual equals next item size -> perfect packing.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff < 1.0 {
            score -= 45.0; // perfect follow-up fit
        } else if post < nxt {
            // dead space relative to lookahead item: penalize proportionally
            score += 8.0 + 0.6 * (nxt - post).min(40.0);
        } else {
            // room left but not exact: mild reward scaled by closeness
            score -= (12.0 - diff.min(12.0)) * 0.5;
        }
    } else {
        // last item: prefer minimal leftover
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // Prefer bins tighter than the mean residual (well-utilized bins).
    score += 0.15 * (post_residual as f64 - mean_residual).clamp(-30.0, 30.0);

    // Early in stream: be more selective (favor tight fits), later: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed post-residual penalty.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Dead space that can't host the next item is penalized more.
        score += 8.0;
    }

    // Last-chance bin: penalize heavily if we'd waste the only fitting bin on a bad fit.
    if fitting_bins_count == 1 && post_residual > 0 {
        score += 12.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer using bins with small residuals relative to mean (reduce fragmentation).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Late in the stream, consolidate: penalize opening new bins.
    let progress = step_index as f64 / (total_items.max(2) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty for many open bins to encourage packing into existing ones.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: post residual, with polynomial shaping (dead space penalized super-linearly)
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth coupling of residual quality with stream progress:
    // early on, tolerate larger residuals; late, pack tight (amplify residual penalty)
    let progress_coupling = 1.0 + 2.0 * progress * (1.0 - progress) * 0.5 + 1.2 * progress;
    score *= progress_coupling;

    // Reward tight fits: subtract a smooth function of item/capacity
    let fit_quality = (item / cap) * (1.0 - norm_pr);
    score -= 10.0 * fit_quality * (1.0 + progress);

    // Lookahead: reward if next item fits into post_residual (smooth bell)
    if next > 0.0 {
        let gap = (norm_pr * cap - next).abs();
        let bell = (-((gap / cap).powi(2) * 8.0)).exp();
        score -= 6.0 * bell * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when bin residual deviates from mean residual (keeps bin profile balanced)
    score += 0.15 * (pr - mean_residual).abs();

    // Discard new-bin candidate unless item is large relative to capacity or stream is early
    if bin_residual == bin_capacity {
        let new_bin_bonus = -18.0 * (1.0 - progress) - 8.0 * (item / cap);
        score += 20.0 + new_bin_bonus; // net: ~ +2..+14 baseline for new bin
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful"
    // for future items (multiples of 10 and small residuals).
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Class bonus: residuals near multiples of 10 are harmonically useful.
    let rem10 = post_residual % 10;
    let harmonic_bonus = if rem10 == 0 {
        -4.0
    } else if rem10 <= 2 || rem10 >= 8 {
        -2.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize large wasted residual quadratically (dead space).
    score += 0.02 * frac * frac * cap;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: base it slightly above a good fit so we only open
    // a new bin when existing fits are poor (large post_residual).
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, opening fresh bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is attractive.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * cap {
            score -= 10.0;
        }
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0;
    }
    // Penalize if next item cannot fit the post residual (wasted pairing).
    if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space below minimum item size
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // narrow window: only tiny items can use it
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening a new bin (large post_residual) is penalized
    // implicitly, but add explicit pressure when bins are plentiful.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * progress);
    score += pressure * 2.0;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size < 10 {
        score += 5.0; // lookahead would create dead space
    }

    // New-bin candidate: make empty bins unattractive unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild tie-break: prefer bins with below-average residual (more filled).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward a post_residual that exactly matches
    // the next item (perfect chain fill), penalize near-miss waste.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // Exact 2-step match: strong reward (subtract heavily).
        score -= 60.0 * (1.0 - gap / (post_residual as f64 + 1.0));
        // Small extra bonus for a perfect zero-gap chain.
        if gap == 0.0 {
            score -= 25.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow in this bin: penalize unusable dead space,
        // scaled by how much space is wasted relative to capacity.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Relative-to-mean coupling: bins with residual well below mean are
    // already "tight"; prefer filling those (their post_residual is naturally
    // small, but add a mild tiebreaker toward tighter-than-average bins).
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a good 2-step chain or last-chance use. Make the empty bin mildly
    // attractive for very large items (poor fits elsewhere) but not so
    // attractive that it beats a tight existing fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // If the item is large relative to capacity, a fresh bin is more
        // acceptable (less chance of fragmenting an existing bin).
        score -= 30.0 * (item_size as f64 / bin_capacity as f64);
        // If the next item also fits into a fresh bin alongside, opening is
        // more attractive.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Stream progression: later in the stream, be slightly more conservative
    // about opening bins (amortized cost matters more at the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: penalize small unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.1 * (next_item_size as f64);
        } else {
            score += 4.0;
        }
        // Strong reward: this bin fits both current and next item snugly.
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Progress-scaled exploration: early on, prefer tighter fills;
    // later, be more tolerant of spreading load across bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: penalize bins much tighter than the mean (avoid fragmenting
    // already-full bins) when many bins are open.
    let residual_gap = mean_residual - bin_residual as f64;
    if open_bins_count > 3 && residual_gap < -20.0 {
        score += 6.0;
    }

    // Mild preference for filling emptier bins when many are open.
    if open_bins_count > 5 {
        score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: discourage opening a new bin unless the item is large
    // or fits would be poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size >= 60 || (fitting_bins_count <= 1 && next_item_size == 0) {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let _ = item_size;
    let _ = bin_residual;
    let _ = bin_capacity;
    let _ = step_index;
    let _ = total_items;
    let _ = open_bins_count;
    let _ = mean_residual;
    let _ = next_item_size;
    let _ = fitting_bins_count;
    post_residual as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (post_residual * 4) / bin_capacity; // 0..3 harmonic tier

    // Reward tight fits, especially in low harmonic classes (small dead space)
    score -= (4 - class as f64) * 8.0;

    // Penalize post-residuals that are "dead zones": below smallest item (1) never,
    // but awkward small remainders (1..10) waste capacity
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Modulo-10 harmonic coupling: residual divisible by 10 pairs well with
    // typical item sizes drawn from wide distributions
    if post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves another awkward remainder
        let next_post = post_residual - next_item_size;
        if next_post < 10 && next_post > 0 {
            score += 5.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize proportionally
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual is large
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * mean_residual;
        // but if the item is large relative to capacity, new bin is fine
        if item_size * 2 >= bin_capacity {
            score -= 25.0;
        }
    }

    // Progress-based mild pressure to consolidate as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score += 0.05 * (mean_residual - frac * 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium gaps (10..30) are partially usable; mild penalty scaled by gap smallness.
    if post_residual >= 10 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.5;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: fewer open bins is better, but only mildly so.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    }
    // Penalize if next item would be stranded in a tiny leftover.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate: only attractive when current bins are badly fragmented
    // (mean residual low relative to remaining stream) or few fitting options.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / bin_capacity as f64).max(0.0);
        // High mean residual -> open bins are usable -> penalize new bin.
        score += 20.0 + fragmentation * 30.0;
        // Late in the stream, opening new bins is cheap; early, avoid it.
        score -= progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced
        }
    }

    // Slight preference for tighter fits among normal bins (item_size relative fill).
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward leaving exactly the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match for next item is highly desirable.
        if diff == 0.0 {
            score -= 60.0;
        } else {
            // Penalize mismatch relative to next item size.
            score += diff * 0.5;
            // If next item can still fit in the leftover, mild reward.
            if post_residual >= next_item_size {
                score -= 10.0;
            }
        }
    } else {
        // Last item: minimize wasted space aggressively.
        score += (post_residual as f64 / bin_capacity as f64) * 40.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average residual is good (tight packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Penalize unusable dead space: residuals below smallest plausible item are waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // rather than opening a new bin, unless fit is very poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: opening a new bin is only attractive when the item
    // is large or fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let tight_elsewhere = fitting_bins_count == 0 || item_size > 60;
        if tight_elsewhere {
            score -= 20.0;
        } else {
            // Discourage needless new bins when existing bins fit reasonably.
            score += 30.0;
        }
    }

    // Slight preference early in the stream to keep bins balanced/open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize bins with small post-residual less.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tight * tight;

    // Waste penalty for unusable dead space (post_residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't chain here; mildly penalize leaving awkward gaps.
        score += 0.15 * (post_residual as f64).min(next_item_size as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Crowding pressure: with many open bins, prefer filling existing ones over new bins.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins with residual close to item_size (perfect fill).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score -= 15.0 * (1.0 - diff / bin_capacity as f64);

    // Time horizon: early in stream, be pickier about wasted space; late, just fill.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - t) * 0.1 * post_residual as f64;
    score -= t * 10.0;

    // Mean residual alignment: bins far below mean residual are "laggards"; fill them.
    let gap = mean_residual - bin_residual as f64;
    if gap > 0.0 {
        score -= 0.2 * gap;
    }

    // New-bin candidate: default mild bias so it only wins when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * item_size as f64;
        if next_item_size > 0 && post_residual >= next_item_size + item_size.min(next_item_size) {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with quadratic shaping
    let mut score = norm_post * norm_post * 40.0 + norm_post * 10.0;

    // Smooth coupling: as stream progresses, penalize leftover dead space more strongly
    score += 30.0 * norm_post * (0.5 + progress);

    // Perfect fit reward (smooth exponential-like decay of penalty)
    score -= 8.0 * (1.0 - norm_post).powi(3);

    // Last-chance bonus: strongly favor this bin if it's the only one that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild penalty when many bins compete (encourage consolidation)
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: reward if next item fits in post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            score += 4.0 * ((nxt - post) / cap);
        }
    }

    // Mean-residual deviation: prefer bins whose residual deviates from mean (diversify bin states)
    let dev = (post - mean_residual) / cap;
    score += 3.0 * dev * dev - 2.0 * dev;

    // Slight preference for opening new bins early vs late (smooth in progress and open bins)
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 3.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    // Class items into capacity-fraction buckets: post_residual / capacity
    let frac = post_residual as f64 / bin_capacity as f64;

    // Dead-space penalty: residual too small to ever be useful (below smallest item class)
    if post_residual < 10u32.min(bin_capacity) {
        score += 25.0;
    }

    // Harmonic tier penalty: post_residual in "awkward" classes
    // (just above half capacity => hard to fill; just below half => decent)
    if post_residual > bin_capacity / 2 {
        // Large residual is fine for open bins (room for future items),
        // but we want tight fits, so mild penalty grows with residual.
        score += 0.15 * (post_residual as f64 - bin_capacity as f64 / 2.0);
    } else {
        // Small residual: reward tight packing, especially harmonic-friendly classes
        // (residual that is a divisor-like fraction: 0, ~C/4, ~C/3, ~C/2)
        let c = bin_capacity as f64;
        let mut harmonicity = f64::INFINITY;
        for k in 1..=4 {
            let target = c / k as f64;
            let d = (post_residual as f64 - target).abs();
            if d < harmonicity { harmonicity = d; }
        }
        score -= 12.0 * (1.0 - harmonicity / (c / 4.0)).max(0.0);
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: strong reward, scaled by how snugly
            let snug = (post_residual - next_item_size) as f64;
            score -= 18.0 - 0.1 * snug;
        } else {
            // Post-residual cannot fit next item: penalize proportionally to wasted space
            let waste = post_residual as f64;
            score += 0.2 * waste;
            // Extra penalty if residual falls into a "useless" modulo band
            if post_residual % 10 < next_item_size.min(10) && post_residual < 30 {
                score += 8.0;
            }
        }
    } else {
        // Last item in stream: pure tightness, no future concern
        score -= 20.0;
    }

    // --- Last-chance bonus: only one open bin fits this item ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early (many future items to fill it)
        // and when current bins have poor residual structure.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut newbin_score = 45.0 + 40.0 * progress;
        // If mean residual across open bins is large, prefer reusing open bins
        newbin_score += 0.3 * mean_residual;
        // If no bin fits except this new one (fitting_bins_count counts open bins),
        // opening is forced-ish: make it cheap.
        if fitting_bins_count == 0 {
            newbin_score -= 100.0;
        }
        // Lookahead: a fresh bin trivially fits the next item
        if next_item_size > 0 {
            newbin_score -= 5.0;
        }
        score = newbin_score;
    }

    // Mild global pressure: prefer reusing existing bins when many are open
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize unusable small gaps.
    // Gaps below the minimum item size (1) are pure waste; treat anything
    // in a "hard to reuse" band (1..=10) as dead space and punish it hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Exact fit is a jackpot.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, favor consolidating into
    // existing bins and discourage opening new ones.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        score += 30.0 * pressure;
    } else {
        score -= 6.0 * pressure;
    }

    // Last chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits the post residual, this placement is great.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Slight preference for filling fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_residual as f64 / bin_capacity as f64) * 8.0 * (0.5 + progress);

    // Nudge toward bins tighter than the mean residual (better fits).
    score += (mean_residual - bin_residual as f64).clamp(-30.0, 30.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain fit: post_residual consumed by next item
        } else if post_residual >= next_item_size {
            // next item fits but leaves further slack; mild reward scaled by tightness
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 200.0 - slack_after_next * 2.0;
        } else {
            // next item cannot fit here: penalize small dead space more when it is close to fitting
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 3.0;
        }
    }

    // Penalize post_residual in the awkward zone (1..=9): nearly unusable dead space.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when no good chaining exists.
    if bin_residual == bin_capacity {
        // Base penalty so full bins are preferred, unless open bins are crowded.
        score += 150.0;
        // Early in stream or many open bins: opening new bins is cheap/fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 100.0;
        // If mean residual across open bins is low (bins nearly full), new bin is good.
        if mean_residual < item_size as f64 {
            score -= 120.0;
        }
        // If the next item is large, starting a fresh bin preserves flexibility.
        if next_item_size >= 60 {
            score -= 80.0;
        }
    }

    // Mild preference for filling fuller bins relative to the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Prefer bins among many fitting candidates by tightness of fit.
    if fitting_bins_count > 1 {
        score += (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * progress * (1.0 - progress);
    score += 25.0 * poly;

    // Penalize dead space more strongly as the stream progresses
    score += progress * 8.0 * (pr / (1.0 + pr)) * (pr / (1.0 + pr));

    // Reward tight fits, scaled non-linearly by progress
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Lookahead coupling: favor bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * fit_ratio * (1.0 - fit_ratio) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 6.0 * progress;
    }

    // Last-chance bin bonus, smooth in fitting_bins_count
    if fitting_bins_count <= 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // Mean residual interaction: prefer bins deviating from mean non-linearly
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * dev * dev - 5.0 * dev * progress;

    // Mild pressure to consolidate into fewer bins as stream matures
    score += progress * 3.0 * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space.
    // Residuals divisible by common item sizes (or leaving nice fractions) are valuable.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fill reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: leftover too small for the smallest plausible item (1..100 range, min item 1)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Harmonic classes on post_residual: modulo arithmetic on capacity fractions
    // Residuals in classes that commonly pair with item sizes get a discount.
    let r = post_residual % 10; // decimal harmonic class
    score -= match r {
        0 => 12.0, // multiple of 10: very compatible
        5 => 8.0,  // half-class
        2 | 4 | 6 | 8 => 5.0, // even classes
        _ => 0.0,
    };

    // Lookahead harmony: does post_residual fit next_item_size exactly or in same class?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 40.0; // next item perfectly consumes leftover
        } else if next_item_size <= post_residual {
            score -= 15.0 + 10.0 * (n / cap_f); // next item fits, prefer tighter fills
            // harmonic match: same modulo-10 class
            if (next_item_size % 10) == r {
                score -= 6.0;
            }
        } else {
            score += 10.0 + 8.0 * (n / cap_f); // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad dead space
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = cap_f * 0.55;
        // Attractive if the item would leave awkward residue in existing bins
        if post_residual > 0 && post_residual < 15 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
            score -= 15.0;
        }
        // Early in stream, prefer consolidating; late, more bins fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // Many open bins with high mean residual: don't open more
        if mean_residual > 40.0 {
            score += 15.0;
        }
    }

    // Mild pressure to fill fuller bins first (smaller post_residual already favored)
    score += 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible future item (<= 10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Gaps too small for the lookahead item are also likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }
    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }
    // Reward placements that still accommodate the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins when many
    // are open; make opening a new bin progressively less attractive.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // Late in the stream, avoid leaving many partially filled bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        // Slight preference for filling bins that are already mostly full
        // (keeps large residuals available for large future items).
        let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 10.0 * fill_ratio;
        // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
    }

    // Mild alignment with mean residual: prefer bins below the mean residual
    // (denser bins) to keep a pool of larger gaps open.
    if !is_new_bin && mean_residual > 0.0 {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        // Perfect match: huge reward (subtract).
        if diff < 0.5 {
            score -= 60.0;
        } else if nxt < post {
            // Next item fits exactly-ish: reward proportionally to closeness.
            score -= 25.0 * (1.0 - diff / post.max(1.0));
        } else {
            // Next item won't fit in the leftover: penalize dead space slightly.
            score += 10.0 + diff * 0.15;
        }
    }

    // Penalize tiny unusable residuals (dead space) with a non-linear bump.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin (only fitting bin): strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins with residuals below the mean residual (tight packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: keep it neutral-ish but slightly penalized so it is
    // only chosen when no open bin offers a good (lookahead-matched) fit.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Early in the stream, opening bins is cheap; late, avoid proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If the next item exactly fills a fresh bin's leftover after this item,
        // opening a new bin can be great: reward that case.
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64 - next_item_size as f64).abs() < 0.5 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically, normalized by capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += (pr * pr) / cap;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // good: next item can follow in same bin
            score -= 6.0 * (nxt / cap);
            if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
                score -= 8.0; // near-perfect chain
            }
        } else if post_residual as f64 > 0.0 && nxt > post_residual as f64 {
            // next item won't fit here; slight penalty if we leave awkward gap
            if post_residual > 0 && post_residual < 10 {
                score += 5.0; // tiny unusable gap
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // relative to mean residual (poor fits everywhere) or no real alternative.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let mean_frac = mean_residual / cap;
        // opening a new bin is attractive when item is big and mean residual is small
        let openness = (item_frac - mean_frac * 0.5) * 20.0;
        // early stream: more willing to open bins; late stream: consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        let time_bias = 10.0 * (1.0 - progress);
        // base new-bin score keeps it competitive but not dominant
        score = cap - item_frac * 10.0 - openness - time_bias + open_bins_count as f64 * 0.5;
    }

    // Mild penalty for spreading across many open bins when mean residual is low.
    if mean_residual < 20.0 && bin_residual != bin_capacity {
        score += 2.0;
    }

    // Slight preference for fuller bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on post-residual (wasted space grows super-linearly)
    let mut score = pr * (1.0 + 1.5 * norm_pr);

    // Smooth coupling: waste matters more as stream progresses
    score += 30.0 * norm_pr * norm_pr * progress;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = norm_item / (norm_item + norm_pr + 1e-6);
    score -= 20.0 * tightness * (1.0 - progress);

    // Penalize bins far from mean residual (avoid leaving outliers)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 12.0 * (nx / cap) * (pr - nx) / cap;
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for proliferating many open bins with large residuals
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: keep it slightly unattractive unless post_residual is huge
    if bin_residual == bin_capacity {
        score += 10.0 - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // usable windows where common small items (1..=20) can still land.
    let class = post_residual / 10; // integer division threshold classes
    match class {
        0 => score -= 30.0,                    // near-perfect fit, tiny dead space
        1 => score -= 12.0,                    // leftover 10..19: fits small items
        2 => score -= 6.0,                     // leftover 20..29: decent
        3 => score += 4.0,                     // leftover 30..39: mild waste risk
        4 => score += 10.0,                    // leftover 40..49
        _ => score += 18.0,                    // huge leftover: item was small, poor use
    }

    // Modulo coupling: post_residual mod 10 == 0 means perfectly divisible
    // leftover, easy to fill with 10-multiples later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this bin's leftover anyway
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition exists: prefer tight fits among many candidates
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Mean-residual coupling: placing into a bin far below mean residual
    // balances the pool; placing into an already-large-residual bin is bad.
    score += ((post_residual as f64) - mean_residual) * 0.25;

    // Progress-based tightening: late in the stream, keep leftovers small.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    // Penalize new-bin opening unless current item is large relative to capacity
    // and no good fit exists (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // new bin starts with full residual; make it competitive only when
        // existing bins would leave big dead space
        let best_possible_dead = if post_residual < bin_capacity {
            post_residual
        } else {
            0
        };
        score = cap * 0.35 + best_possible_dead as f64 * 0.5;
        if item_size as f64 > cap * 0.7 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..9)
    // are pure waste; penalize them hard, but reward an exact fit.
    if post_residual == 0 {
        score -= 50.0; // perfect fit, ideal
    } else if post_residual < 10 {
        score += 40.0; // unusable dead space
    }

    // Reward tight fits relative to item size.
    score -= (item_size as f64) * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate: make it unattractive unless existing bins are all bad.
    if bin_residual == bin_capacity {
        score += 60.0 + (open_bins_count as f64) * 0.2;
        // If next item is large, a fresh bin is somewhat more tolerable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit: post_residual likely becomes dead space.
        score += 8.0;
    }

    // Slight preference for bins below the mean residual (fill emptier bins first
    // keeps tighter bins available).
    score -= (mean_residual - post_residual as f64) * 0.1;

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits: post_residual small is already good via base score.
    // Strong 2-step lookahead: if next item fits exactly into post_residual,
    // heavily reward this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin becomes exactly full
        } else if next_item_size < post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            // reward proportional to how well next item chains
            score -= 25.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // next item cannot chain into this bin: mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64).min(1.0);
        }
    }

    // Penalize leaving dead space that is hard to reuse (small post_residual
    // that doesn't match the next item is wasted).
    if post_residual > 0 && next_item_size > post_residual {
        score += 10.0;
    }

    // Compare against mean residual: placing into a bin far below mean residual
    // concentrates waste; prefer bins with residuals near/above mean.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Slight preference for filling fuller bins when many bins are open
    // (keeps the pool of partially-filled bins small).
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fill_frac;

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a good fit. Give it a moderate penalty that tight fits can beat.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Late in the stream, opening new bins is less attractive (leftover waste).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= bin_capacity / 2 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    if post_residual == 0 {
        score -= 40.0; // perfect closure is ideal
    } else if post_residual <= 10 {
        score -= 20.0;
    } else {
        // dead-space penalty grows quadratically for large leftover gaps
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    }

    // Lookahead: reward if next item can fit into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // penalize leaving a gap that the next item just barely misses
            let miss = (next_item_size as f64) - (post_residual as f64);
            if miss <= 10.0 {
                score += miss * 1.5;
            }
        }
    }

    // Last chance: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early on, opening bins is fine; late in the stream, prefer using open bins.
        let new_bin_penalty = 30.0 * (1.0 - 0.5 * progress);
        // If the item is large relative to capacity, a fresh bin is attractive.
        let size_relief = (item_size as f64 / bin_capacity as f64) * 15.0;
        score += new_bin_penalty - size_relief;
        // Many open bins with low mean residual => reuse is likely; discourage new bin.
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            score += 10.0;
        }
    } else {
        // Favor bins whose residual is close to the item (best-fit flavor),
        // scaled by how fragmented the open-bin pool is.
        let gap = (bin_residual as f64) - (item_size as f64);
        score += gap * 0.2;
        // Prefer reusing bins when mean residual is high (pool is fragmented).
        score -= mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let is_new = (bin_residual as u64 == bin_capacity as u64) as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;

    let mut score = pr + 40.0 * poly;

    // Penalize new bins more as stream progresses (prefer filling existing bins)
    score += is_new * (60.0 + 120.0 * progress);

    // Reward near-perfect fits with smooth quadratic bonus
    let tight = 1.0 - norm_pr;
    score -= (1.0 - is_new) * item_size as f64 * tight * tight * 0.5;

    // Lookahead: penalize leaving residual close to next item size (wasted pairing)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score += (1.0 - is_new) * 15.0 * (1.0 - 4.0 * diff * diff).max(0.0);
    }

    // Last-chance bin gets strong preference
    if fitting_bins_count == 1 && is_new < 0.5 {
        score -= 25.0;
    }

    // Mild pressure toward bins below mean residual (balance open bins)
    score += 0.1 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (hard to reuse) are penalized.
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -6.0,          // perfect fill
        1 | 2 => 4.0,       // nearly dead space
        3 | 4 | 5 | 6 | 7 => 1.5, // awkward middle slivers
        _ => 0.0,           // 8..9 reusable by small items
    };
    score += class_penalty;

    // Integer-division threshold on post_residual: residues below 10 are waste.
    if post_residual < 10 {
        score -= 5.0;
    } else if post_residual < 20 {
        score += 2.0;
    }

    // Reward tight fits (item occupies most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            let pair_waste = post_residual - next_item_size;
            score -= 6.0 * (1.0 - pair_waste as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residue: mild penalty proportional to leftover
            score += 0.05 * post_residual as f64;
        }
    } else {
        // last item: prefer fullest packing
        score -= 10.0 * fill_ratio;
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only open a new bin when current bins are
    // nearly full or the item is huge and nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64;
        if crowded || fill_ratio > 0.8 {
            score -= 9.0 + 3.0 * progress;
        } else {
            score += 14.0; // discourage opening bins when reuse is possible
        }
    }

    // Prefer consolidating into fewer bins when many are open.
    score += 0.15 * open_bins_count as f64;

    // Slight preference for bins with residual below the mean (tighter bins).
    score += 0.5 * (mean_residual - bin_residual as f64).signum();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable
    // (items are >= 1, but small gaps rarely match future demand).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin completely.
        score -= 40.0;
    } else if post_residual <= 15 {
        score += 8.0; // semi-dead zone
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.3 + 0.5 * progress);

    // Mean residual coupling: if mean residual is large, prefer bins below mean
    // (drain the largest gaps first).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if next item is larger than post residual, penalize wasted compatibility.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 10.0;
        }
    }

    // New-bin candidate: only attractive when no good fit exists
    // (empty bin has huge post_residual = capacity, so it naturally loses
    // unless dead-space penalties dominate; add mild bias against opening).
    if bin_residual == bin_capacity {
        score += 5.0 + (open_bins_count as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (chains the placement perfectly).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mildly favorable.
            score -= 30.0 + (next_item_size as f64 / bin_capacity as f64) * 40.0;
        } else {
            // Next item cannot use this bin afterwards: penalize dead space
            // proportional to how much is left unusable for the next item.
            score += 20.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
        // Exact two-item packing: item + next fill the bin completely.
        if item_size + next_item_size == bin_residual {
            score -= 350.0;
        }
    } else {
        // Last item: only a perfect fit matters.
        if post_residual == 0 {
            score -= 500.0;
        }
    }

    // Reward tight fits relative to item size (small post_residual is good).
    score -= (item_size as f64 / bin_capacity as f64) * 50.0;

    // Penalize deviating from the mean residual: prefer bins that are either
    // very full (small residual) or keep the residual distribution compact.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly so we only open a new bin when it
    // beats a genuinely bad fit (e.g. huge dead space on an open bin).
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if the next item would perfectly pair with this item in a fresh
        // bin, opening is attractive.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 300.0;
        }
    }

    // Late in the stream, be more conservative: keep open bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 10.0; // marginal space
    }

    // Lookahead: reward bins whose post_residual can host the next item (chain packing)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 8.0; // breaks the chain
        }
        // If next item fits exactly after this placement, extra reward
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Global state coupling: many open bins with high mean residual -> consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > (item_size as f64) * 1.5 && open_bins_count > 2 {
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    }
    // Late in the stream, prefer filling existing bins over opening new ones
    if progress > 0.7 {
        score -= 10.0 * progress;
    }

    // New-bin candidate handling: usually penalize, unless current fit is terrible
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is attractive only for large items that would leave
        // awkward residue elsewhere, or when no bin fits well
        let poor_fit = (bin_residual - item_size).min(bin_residual) as f64;
        let _ = poor_fit;
        let best_case_post = bin_residual as f64 - item_size as f64;
        let would_waste = if best_case_post < 10.0 { 1.0 } else { 0.0 };
        let penalty = 35.0
            - 30.0 * fit_ratio
            - 20.0 * would_waste
            - 15.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        score += penalty.max(-10.0);
        // Never let the new bin win when an existing bin achieves a perfect fit
        if post_residual == 0 && !is_new_bin {
            score -= 100.0;
        }
    } else if post_residual == 0 {
        // Perfect closure of an existing bin
        score -= 100.0;
    }

    // Mild preference for bins with residual close to item (minimize fragmentation)
    let frag = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * frag;

    // Small tie-breaker favoring fewer open bins
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling: post_residual penalized more heavily as stream progresses
    let mut score = pr * (1.0 + 0.9 * progress * progress);

    // Non-linear interaction: quadratic dead-space penalty, amplified by progress
    score += 4.0 * norm_pr * norm_pr * (0.3 + progress);

    // Reward tight fits: cubic smoothness in (1 - normalized post residual)
    let tightness = 1.0 - norm_pr;
    score -= 3.0 * tightness * tightness * tightness * (1.0 + progress);

    // Last-chance bonus: smooth sigmoid-like term instead of hard branch
    let last_chance = 1.0 / (1.0 + (fitting_bins_count.saturating_sub(1)) as f64);
    score -= 6.0 * last_chance * (0.5 + 0.5 * progress);

    // Lookahead: reward leaving room for next item (smooth bell around next item size)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = pr - n;
        let bell = (-0.0008 * diff * diff).exp();
        score -= 5.0 * bell * (0.4 + 0.6 * progress);
    }

    // Deviation from mean residual: prefer bins whose post residual keeps diversity low
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Mild penalty for many open bins to discourage bin proliferation
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate: smooth acceptance, penalize opening new bins unless residual is large
    if bin_residual == bin_capacity {
        score = pr * (1.3 - 0.5 * progress) + 8.0 * (1.0 - last_chance);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: classify leftover space ---
    // Classes: [0..=5] perfect-ish fit, (5..=15] small dead space, (15..=30] mid,
    // (30..=50] large, >50 huge (should probably have opened a new bin instead).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect packing, always reward strongly
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 15 {
        score -= 12.0;
        score += ((pr - 5) as f64) * 0.8; // dead space penalty inside class
    } else if pr <= 30 {
        score -= 4.0;
        score += ((pr - 15) as f64) * 0.6;
    } else if pr <= 50 {
        score += ((pr - 30) as f64) * 0.9;
    } else {
        score += ((pr - 50) as f64) * 1.3; // wasteful large leftover
    }

    // --- Modulo arithmetic on post_residual w.r.t. capacity quarters ---
    // Residuals congruent to small values mod 25 are "harmonic" with common item sizes.
    let m = pr % 25;
    if m <= 5 {
        score -= 10.0; // residual harmonizes with 25-multiple item classes
    } else if m >= 20 {
        score -= 6.0;
    } else {
        score += (12 - m as i32).unsigned_abs() as f64 * 0.4;
    }

    // --- Lookahead coupling: does the next item fit the post residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item can chain into this bin: reward proportional to tightness
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 35.0; // perfect 2-chain
            } else if slack <= 10 {
                score -= 20.0;
            } else {
                score -= 8.0;
                score += slack as f64 * 0.15;
            }
        } else {
            // Next item cannot fit here; leftover risks becoming dead space
            let gap = next_item_size - pr;
            score += gap as f64 * 0.5;
            // But if leftover is tiny, it's still fine
            if pr <= 8 {
                score -= 15.0;
            }
        }
    } else {
        // Last item: any residual is pure waste; prefer tightest fit
        score += 0.0;
        score -= 5.0; // slight bias toward finishing tight
    }

    // --- Last-chance bonus: if this is the only fitting bin, avoid new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new bin: base cost of consuming fresh capacity.
        score = 100.0 + item_size as f64 * 0.3;
        // Prefer opening a new bin when existing residuals are fragmented / large
        if mean_residual > 40.0 {
            score -= 15.0; // existing bins are roomy; a new bin is competitive
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big item coming, fresh bin useful
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open new bin
        }
    } else {
        // Prefer reusing bins with smaller residual (best-fit flavor) already in score;
        // add mild pressure against bins much larger than the item.
        let waste = bin_residual.saturating_sub(item_size);
        if waste > 60 {
            score += 8.0;
        }
    }

    // --- Stream progression: early on, be liberal with new bins (build structure);
    // late in the stream, squeeze existing bins harder. ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0 * (post_residual.min(30) as f64) / 30.0;
    score += progress * (post_residual.min(50) as f64) * 0.2;

    // --- Mild load-balancing: penalize bins below mean residual (over-tight bins) ---
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        // Dead space severity: small gaps that no plausible item can use.
        // Items are 1..=100, but small residuals (< ~10) are nearly unusable.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 8.0; // steep cliff for tiny gaps
        } else if post_residual < 25 {
            score += (25 - post_residual) as f64 * 2.0; // moderate penalty
        }
        // Perfect fit is heavily rewarded.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open bins pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening/keeping many bins alive with dead space).
    let obp = open_bins_count as f64;
    score += obp * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits into the post residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64 / post_residual as f64) * 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the gap: penalize leaving dead space.
        score += (post_residual as f64) * 0.8;
    }

    // New-bin candidate handling: an empty bin has large residual; make it less
    // attractive than a decent existing fit, but attractive when existing bins
    // would leave very small dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with stream progression.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * (1.0 - progress);
        // But if open bins are congested (high mean residual spread / many bins),
        // opening fresh is less penalized.
        score -= obp * 0.5;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: if this bin's post residual deviates far below the
    // mean, it's a tighter-than-average fit; reward it.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect fit now.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 800.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits, but leaves further dead space; partial reward.
        score -= 200.0 - 1.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here; penalize small dead space more than large.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 60.0 - dead; // tiny slivers are nearly unusable
        } else {
            score += dead * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when current bins have poor fit potential.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // If no open bins fit (or very few), opening is more acceptable.
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else if fitting_bins_count == 1 {
            score -= 60.0;
        }
        // Early in the stream, be more willing to open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 50.0 * (1.0 - progress);
        // If mean residual across open bins is small, new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 40.0;
        }
    }

    // Prefer bins tighter than the mean (best-fit flavor).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual relative to capacity (good fill).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Exact or near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits in the leftover space, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // Leftover space too small for next item: penalize proportional dead space.
            let waste = post_residual as f64 / next_item_size.max(1) as f64;
            score += 8.0 * waste.min(4.0);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let item_heavy = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for large items with no alternatives,
        // bad when many bins could take the item.
        score -= 40.0 * pressure * item_heavy;
        score += 55.0 * (1.0 - pressure);
        if fitting_bins_count > 0 {
            // Deter new bins more when existing fits are decent (small post_residual elsewhere unknown,
            // so use mean_residual as proxy for how much room open bins have).
            let mean_tight = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
            score += 30.0 * (1.0 - mean_tight);
        }
        // Early in the stream, a fresh bin is cheap insurance.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress) * pressure;
    } else {
        // Mild penalty for very full bins is already handled; small bonus for using
        // bins that would otherwise strand capacity relative to mean residual.
        if (bin_residual as f64) > mean_residual {
            score -= 6.0;
        }
    }

    // Slight preference to spread across fewer bins late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + 0.5 * progress);

    let mut score = pr + 20.0 * poly;

    // Penalize creating dead space that next item cannot use
    if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        score += (next_item_size as f64 - pr) * (0.5 + progress);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - progress);
    }

    // Reward tight fits
    score -= (item_size as f64 / cap) * 10.0 * (1.0 - norm_pr);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for opening a new bin when open bins are plentiful
    if bin_residual == bin_capacity {
        score += 5.0 * (open_bins_count as f64 / (1.0 + mean_residual)) + 10.0 * progress;
    }

    // Coupling with mean residual dispersion
    score += 0.3 * (pr - mean_residual).abs() * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect closure, reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by divisibility.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Residuals that are multiples of common small item sizes are "reusable".
        let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0)
            || (post_residual % 25 == 0) || (post_residual % 50 == 0);
        if reusable {
            score -= 8.0;
        }
        // Tiny unfillable slivers (1..10) are dead space: penalize.
        if post_residual < 10 {
            score += 60.0;
        }
        // Mid residuals divisible by 5 are moderately reusable.
        else if post_residual % 5 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: big reward, stronger the tighter the fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 + 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's remainder: penalize proportionally.
            score += 10.0 + 0.2 * (next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless post_residual would be a dead sliver).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 {
            score -= 25.0;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a good (small) post_residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress
        // and how fragmented current bins are.
        let progress = if total_items > 0 {
            step_index as f64 / total_items as f64
        } else {
            0.0
        };
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).abs()
        } else {
            0.0
        };
        score += 45.0 + 30.0 * fragmentation + 20.0 * progress;
        // But if next item is large, a fresh bin is valuable.
        if next_item_size >= bin_capacity / 2 {
            score -= 35.0;
        }
    }

    // Prefer bins with residual below mean (tighter bins first) mildly.
    score += 0.1 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral baseline, slightly discouraged so real bins win on tight fits.
    if bin_residual == bin_capacity {
        return 55.0 + (open_bins_count as f64) * 0.35;
    }

    // Strict dead-space avoidance: small nonzero residuals are future waste.
    // If the leftover gap is smaller than the next item (or typical min size), it is dead space.
    let threshold = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < threshold {
        score += 40.0 + (threshold - post_residual) as f64 * 2.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Penalize leaving a gap just barely above the next item's size (awkward fit).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 8 {
        score -= 6.0;
    }

    // Open-bin pressure: prefer denser packing when many bins are open.
    score += (open_bins_count as f64) * 0.4;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Alignment with mean residual: bins below mean residual are already tight; keep them tight.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Slight stream-position tilt: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: exact match between post_residual and next item size is ideal.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect lookahead fit: strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits in the gap: reward proportional to tightness of fit.
            let tightness = 1.0 - (post - nxt) / bin_capacity as f64;
            score -= 25.0 * tightness;
        } else {
            // Next item cannot use the gap: penalize dead space relative to gap size.
            score += 10.0 * (nxt - post) / 100.0;
        }

        // Coupling with mean residual: bins whose post-residual is far below the mean
        // are being "consolidated" — reward closing the gap toward the mean.
        let dev = (post - mean_residual).abs();
        score -= 5.0 / (1.0 + dev);
        // Penalize leaving post-residual well above mean (fragmenting space).
        if post > mean_residual {
            score += 0.4 * (post - mean_residual);
        }
    } else {
        // Last item: just minimize post residual.
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless residual waste is huge.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; overcome only if item is large relative to capacity.
        score += 55.0;
        // Very large items near capacity are fine to start fresh.
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 70.0;
        }
    }

    // Slight stream-progression pressure: as the stream advances, avoid leaving big gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (size 1..100, mostly >=10).
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves more waste: mild penalty proportional to leftover
            score += 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot use this bin's remainder: mild reward for dumping large leftovers here
            score -= 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the item
    // leaves little waste in the best open bin, or when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        // Penalize opening new bins generally; scale with how many bins are already open.
        score += 8.0 + 1.2 * open_bins_count as f64;
        // But if the current item would leave a large unusable gap in typical open bins
        // (mean residual much larger than item), opening a bin is less bad.
        if mean_residual > 1.6 * item_size as f64 {
            score -= 6.0;
        }
        // Late in the stream, avoid proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    } else {
        // Prefer using bins whose residual is close to the item (best-fit sharpening).
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.08 * gap;
        // Slight preference for bins with residual below mean (consolidate fragmented space).
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        }
    }

    // Mild time-horizon modulation: early on, be more conservative with tight fits
    // (keep flexibility); late, exploit tight fits harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= tightness * 6.0 * progress;

    // Small entropy term to break ties deterministically via bin state.
    score += 0.01 * (bin_residual as f64).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;
    let fit_norm = post / (item_size as f64 + 1.0);

    // Core: penalize leftover space, with non-linear polynomial shaping
    let mut score = post_norm * (1.0 + 0.8 * post_norm * post_norm);

    // Smooth interaction: as stream progresses, prefer tighter fits more strongly
    score *= 1.0 + 1.5 * progress * (1.0 - fit_norm).abs();

    // Penalize dead space relative to mean residual across open bins
    score += 0.3 * (post - mean_residual) / cap * (1.0 + progress);

    // Lookahead coupling: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let room = post / nxt;
        let kernel = (-((room - 1.0) * (room - 1.0))).exp();
        score -= 0.6 * kernel * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 + progress);
    }

    // Mild new-bin penalty so open bins are preferred unless fit is poor
    if bin_residual as u64 == bin_capacity as u64 {
        score += 1.2 + 0.5 * (1.0 - progress) + 0.4 * post_norm;
    }

    // Slight congestion shaping
    score += 0.05 * (open_bins_count as f64).sqrt() * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets.
    // Residuals that are multiples of 10 are "harmonically clean" (many small
    // items of size 10..=80 divide into them); odd/prime-ish residues waste space.
    let pr = post_residual;
    let harmonic_class = pr % 10;
    match harmonic_class {
        0 => score -= 6.0,                       // perfectly divisible residue
        5 => score -= 2.5,                       // half-class
        2 | 4 | 6 | 8 => score -= 1.0,           // even class
        _ => score += 3.0,                       // odd residue: dead-space risk
    }

    // Integer-division thresholds: how many "typical" items (size ~ cap/4)
    // still fit after placement.
    let quarter = bin_capacity / 4;
    let fits_quarter = pr / quarter.max(1);
    score -= fits_quarter as f64 * 2.0;

    // Penalize residuals in the awkward band (1..=9): too small for the
    // minimum item, guaranteed waste.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly or
    // harmonically (next % 10 == 0 and next <= pr), reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0; // perfect two-item chain
        } else if next_item_size <= pr {
            if next_item_size % 10 == 0 && pr % 10 == 0 {
                score -= 8.0;
            } else {
                score -= 3.0;
            }
        } else {
            // next item won't fit here: slight penalty unless post_residual is tiny
            score += 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has pristine harmonic residual.
    // Prefer it when the item leaves a bad residue in an open bin but a clean
    // one in a fresh bin, or late in the stream when consolidation matters less.
    if bin_residual == bin_capacity {
        let fresh_class = (bin_capacity - item_size) % 10;
        let fresh_bonus = if fresh_class == 0 { 14.0 } else if fresh_class == 5 { 9.0 } else if fresh_class % 2 == 0 { 5.0 } else { 0.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= fresh_bonus * (0.4 + 0.6 * progress);
        // If no open bin fits at all, opening is mandatory-ish; big reward.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Slight preference for bins below mean residual (filling emptier bins
    // keeps tight bins available for small items).
    if (post_residual as f64) > mean_residual {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the minimum item size (1) — but
    // practically, gaps below a usable threshold waste capacity.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        // Dead space in the tiny-gap regime: penalize quadratically.
        score += (10.0 - gap) * (10.0 - gap) * 2.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual == 1 {
        score -= 55.0; // effectively perfect (min item size 1)
    }

    // Reward gaps that can still host the next item (lookahead k=2).
    if next_item_size > 0 {
        if gap >= next_item_size as f64 {
            score -= 8.0;
        } else if gap > 0.0 {
            // gap cannot host next item: it is likely dead space going forward
            score += (next_item_size as f64 - gap).min(20.0);
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // fit exists; encourage using scarce fitting bins.
    if fitting_bins_count == 1 {
        score -= 25.0; // last chance bin: use it before opening a new one
    }
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: an empty bin has huge post_residual, which
    // already scores high (bad). Add extra penalty so it is only chosen when
    // no reasonable fit exists; relax the penalty late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 40.0 - 20.0 * progress;
        // If the next item would perfectly fill the remainder, opening is ok.
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 45.0;
        }
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (item fills the hole the next item needs).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect lookahead fit: big reward.
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual as f64 >= nxt {
            // Next item could still fit here: reward proportionally to closeness.
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot fit: penalize wasted dead space, worse when
            // post_residual is small and unusable.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 25.0 * (1.0 - waste);
        }
    }

    // Penalize very tight residual that likely becomes dead space
    // (small post_residual with no lookahead match).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Compare against mean residual: bins with residual below mean are
    // "tighter" — placing there consolidates space.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score += 4.0 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    // (many bins but poor fitting options), otherwise discourage fragmentation.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 || (fitting_bins_count > 0 && post_residual as f64 > 50.0 && open_bins_count > 0 && next_item_size > item_size) {
            score -= 12.0;
        } else {
            score += 35.0;
        }
    }

    // Early in stream: keep bins flexible; late: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_ratio = (bin_residual as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fill_ratio * (1.0 + open_bins_count as f64 / 20.0);

    // Global state coupling: if mean residual is high, prefer using existing bins more
    score -= 0.05 * mean_residual;

    // Time horizon: early in the stream, be more conservative (slight preference for new bins
    // to preserve flexibility); late in the stream, squeeze existing bins harder
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (1.0 - fill_ratio);

    // Prefer placing large items into bins with just-enough residual
    let waste = (bin_residual - item_size) as f64;
    score += 0.02 * waste * waste / (bin_capacity as f64);

    // Mild preference against opening new bins when many are already open
    if bin_residual == bin_capacity {
        score += 4.0 + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = x * x * (1.0 - x) * (1.0 - x); // peaks at x=0.5, penalizes extremes
    let mut score = pr * (1.0 + 0.9 * poly) - 12.0 * progress * poly * cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - x) * (1.0 - x) * (20.0 + 30.0 * progress);

    // Penalize dead space that cannot fit a typical next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (1.5 + 2.0 * progress);
        } else {
            score -= 0.5 * ((pr - nx) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild penalty for proliferating open bins early on.
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    // Smooth coupling with mean residual: prefer bins near the mean.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless current bin would be wasted.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo capacity/4 quarters
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..3 harmonic class
    // Penalize dead space by class: small leftovers (class 0..1) are hard to fill
    score += match class {
        0 => 6.0,   // very small leftover, likely dead space
        1 => 3.0,   // small leftover
        2 => -1.0,  // medium leftover is useful
        _ => -2.0,  // large leftover stays flexible
    };

    // Perfect fit reward (harmonic alignment with capacity)
    if post_residual == 0 { score -= 25.0; }
    else if post_residual % 10 == 0 { score -= 4.0; }

    // Next-item lookahead: reward if next item fits the post residual exactly or well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= (1.0 + slack as f64 / bin_capacity as f64) * 5.0;
            if slack == 0 { score -= 10.0; }
        } else {
            // next item cannot use this bin's remainder: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - fragmentation * 0.4 - progress * 6.0;
        if open_bins_count == 0 { score -= 30.0; }
    }

    // Mild preference to keep bins balanced with mean residual
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold any plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fill is highly desirable.
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.5 * (open_bins_count as f64).ln().max(0.0);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer a fresh bin only when residuals are tight everywhere.
    if bin_residual == bin_capacity {
        let mean_tight = mean_residual < 25.0;
        if mean_tight && open_bins_count > 0 {
            score -= 10.0;
        } else {
            score += 30.0;
        }
    }

    // Lookahead: penalize leaving a gap that exactly wastes the next item's fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0; // next item will nearly fill this bin: good
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // next item cannot use this bin's remainder
        }
    }

    // Mild stream-progression scaling: tighten behavior late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a super-linear penalty curve.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: this bin becomes exactly full after the next item.
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Partial chain fit: reward proportionally to how well it matches.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize leftover dead space.
            let dead = post_residual as f64;
            let nxt = next_item_size as f64;
            if dead < nxt {
                score += 0.5 * (nxt - dead).min(40.0);
            }
        }
    }

    // Compare against mean residual: prefer bins whose residual is below average
    // (consume the "tightest" bins first), penalize dipping into already-loose bins.
    if bin_residual as f64 > mean_residual {
        score += 8.0;
    } else {
        score -= 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation of the bin pool).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // item is large relative to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Large items benefit from a fresh bin (avoids stranding big items).
        if item_size > bin_capacity / 2 {
            score -= 35.0;
        }
        // Late in the stream, prefer closing out open bins instead of new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins: discourage adding more.
        score += 2.0 * open_bins_count as f64;
        // If next item is huge, a fresh bin is valuable for it.
        if next_item_size > bin_capacity * 3 / 4 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic discount for small post-residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: residual too small to ever fit the smallest plausible item (<= 1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size > post_residual {
            // next item won't fit here anyway; mild penalty proportional to stranded residual
            score += 0.25 * (post_residual as f64).sqrt();
        } else {
            // next item still fits: residual remains usable
            score -= 0.15 * (next_item_size as f64);
        }
    }

    // Last-chance logic: if this is the only fitting bin, prefer using it over opening a new bin
    // unless the fit is very poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual > 0 && post_residual < 10 {
            score += 10.0; // but not if it creates near-dead space
        }
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 55.0; // base cost of opening a new bin
        if fitting_bins_count == 0 {
            score -= 80.0; // nothing fits elsewhere, must open
        } else if post_residual >= 50 {
            // item is small relative to capacity; a fresh bin keeps large contiguous space
            score -= 20.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> encourage consolidation
    // into existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (mean_residual - post_residual as f64).abs();
    score += 0.10 * open_bins_count as f64 * (1.0 - progress);
    score += 0.05 * consolidation * (1.0 - progress);

    // Prefer bins whose residual is close to item size (waste minimization).
    score += 0.20 * (bin_residual as f64 - item_size as f64).abs().sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress) - 0.35 * norm_pr * norm_pr * cap * (1.0 - progress);

    // Reward tight fits with smooth quadratic term
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    // Penalize dead space relative to mean residual smoothly
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev * cap * (0.5 + progress);

    // Lookahead coupling: reward bins whose post residual fits next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 18.0 * snug * (1.0 - progress);
    }

    // Last-chance bonus with smooth ramp
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins late in the stream
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * progress;

    // Favor opening new bins early when post residual is large
    if bin_residual == bin_capacity {
        score += 5.0 * norm_pr * (1.0 - progress) - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins grouped by capacity fraction.
    let class = post_residual / 10; // 0..10 harmonic classes
    // Prefer leaving residuals that form "complete" harmonic slots (multiples of 10/20).
    let harmonic_bonus = if post_residual == 0 {
        -60.0 // perfect closure
    } else if post_residual % 20 == 0 {
        -25.0
    } else if post_residual % 10 == 0 {
        -12.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Small dead space (<10) is nearly unusable: penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual (integer division match).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 20.0; // exact harmonic pairing
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space the next item cannot use
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly unless current fit is bad (large post_residual waste).
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item followed by big item: fresh bin helps
        }
    }

    // Progress-scaled tie-break toward tighter fits late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / cap) * (1.0 + progress) * 5.0;

    // Prefer bins below mean residual (consolidate emptier bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * -0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot fit even the smallest
    // future item (min size 1..10) are pure waste -> heavy penalty.
    let min_item = 10u32;
    if post_residual > 0 && post_residual < min_item {
        score += 200.0;
    } else if post_residual < min_item * 2 {
        // Small but potentially usable gap: moderate penalty scaled by
        // how close it is to being dead space.
        score += (min_item * 2 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits (low post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit is strongly preferred.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize wasting a nearly-empty bin's potential when the item fits
    // elsewhere with better tightness — handled via post_residual already.

    // Open-bins pressure: with many open bins, favor consolidating into
    // existing bins; opening a new bin (bin_residual == bin_capacity)
    // gets penalized more when open_bins_count is already high.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.5 * open_bins_count as f64;
    } else {
        score -= 1.0 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, reward heavily (chained perfect fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < min_item {
            score -= 45.0;
        } else if gap < min_item * 2 {
            score -= 15.0;
        }
    }
    // If next item would NOT fit in post residual, mild penalty for
    // creating a gap that strands the lookahead item.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (keeps bin profile balanced), avoid outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Stream progression: late in the stream, be more aggressive about
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 25.0 * progress;
    } else {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, but penalize near-full bins
    // that leave nothing usable unless the fit is exact.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward when next_item_size fits into post_residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Strong reward for chains: post_residual ≈ next_item_size
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // Extra bonus for perfect chain (post_residual == next_item_size)
            if gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to the overshoot
            let overshoot = (next_item_size - post_residual) as f64;
            score += 8.0 * (overshoot / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize post_residual, slight bonus for exact fill
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Relative-to-mean coupling: bins with residual near the mean are "typical";
    // prefer filling bins whose residual is small relative to mean (compact them),
    // penalize filling large-residual bins unless the fit is tight.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin (unless post_residual would be huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Give it a mild penalty so tight fits in open bins win,
    // but allow it to win when all fits are poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early in the stream, opening bins is cheaper; late, avoid proliferation.
        score += 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Dead-space penalty: residual that no plausible item (min size ~1, typical mid)
    // can use. Penalize very small nonzero post_residual less than moderate waste.
    if post_residual > 0 && post_residual < 5 {
        score += 10.0; // awkward tiny sliver
    }

    // Slight preference to keep fewer bins open when residuals are high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize large dead space, especially if nothing in typical range could use it.
    if post_residual > 20 {
        score += 0.15 * (post_residual as f64 - 20.0);
    }

    // Last chance: strongly prefer using the only bin that fits to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 0.3 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize leaving awkward residue.
            score += 0.2 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Prefer filling bins that are already relatively full (small residual).
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    // When many bins are open, encourage consolidation into existing bins.
    if open_bins_count > 3 {
        score -= 2.0;
    }

    // New-bin candidate: make empty bin less attractive unless residual after
    // placing would be large (item is small relative to capacity).
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 60 {
            score -= 10.0; // big items start fresh bins happily
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Time horizon: later in the stream, be more conservative (favor existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let nx = next_item_size as f64;

    // Base: prefer small post-residual (tight fit), normalized.
    let mut score = pr / cap;

    // Smooth non-linear coupling: quadratic waste penalty grows with stream progress.
    let waste = pr / cap;
    score += waste * waste * (0.5 + 1.5 * progress);

    // Reward tight fits more strongly later in the stream (cubic interaction).
    score -= (1.0 - waste) * (1.0 - waste) * (1.0 - waste) * (0.3 + 0.7 * progress);

    // Penalize bins whose residual deviates from mean residual (smooth dispersion term).
    let dev = (r - mean_residual) / cap;
    score += 0.2 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 2.0 + progress;
    }

    // Lookahead coupling: reward if next item fits smoothly in post-residual.
    if nx > 0.0 {
        let gap = (pr - nx) / cap;
        if gap >= 0.0 {
            score -= 0.5 * gap * (1.0 - gap);
        } else {
            score += 0.3 * (-gap);
        }
    }

    // Mild penalty for opening a new bin early; relax as stream progresses.
    if bin_residual == bin_capacity {
        score += 0.6 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction slot it lands in.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Class boundaries: perfect fits (0), tiny scraps (<=10), small (<=25),
    // medium (<=50), large (<=75), half-empty (<=100).
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual <= 10 {
        score -= 45.0; // near-perfect: dead space negligible
    } else if post_residual <= 25 {
        score -= 20.0;
    } else if post_residual <= 50 {
        score += 5.0;
    } else {
        score += 15.0; // wasteful, more than half empty
    }

    // Integer-division harmonic class: post_residual mod 10 measures
    // how "granular" the leftover is relative to the smallest item size class.
    let scrap_class = post_residual % 10;
    if scrap_class == 0 {
        score -= 8.0; // residue divisible by 10 matches common item sizes
    } else if scrap_class >= 7 {
        score += 4.0; // awkward non-round leftover
    }

    // Coupling with the lookahead item: if the next item fits exactly into
    // the post-residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            let follow_frac = nxt / post.max(1.0);
            // Reward when the follow-up fills a large share of the leftover.
            if follow_frac > 0.8 {
                score -= 25.0;
            } else if follow_frac > 0.5 {
                score -= 10.0;
            } else {
                score += 8.0 * (1.0 - follow_frac); // leaves a second-generation scrap
            }
            // Harmonic class of the residual left after the hypothetical next item.
            let post2 = post_residual - next_item_size;
            if post2 % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this bin's leftover: leftover is stranded
            // unless some future smaller item arrives; penalize proportionally.
            score += 12.0 * frac;
        }
    } else {
        // Last item in stream: prefer closing bins tightly.
        score -= 10.0 * (1.0 - frac);
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a
    // bad fit unless the fit is actually good.
    if fitting_bins_count == 1 {
        if frac <= 0.25 {
            score -= 30.0; // good fit, definitely use it rather than new bin
        } else {
            score += 10.0 * frac; // mediocre fit; let new-bin candidate win
        }
    }

    // Many open bins: prefer consolidating into bins with small residuals
    // (best-fit bias) to keep the count of half-empty bins down.
    if open_bins_count > 1 {
        score += 0.3 * (mean_residual - post); // prefer below-mean residual bins
    }

    // Early in the stream, keep flexibility: slight preference for new bins
    // so future items have clean containers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, discounted early
        // and when the item is large relative to capacity.
        let item_frac = item_size as f64 / cap;
        score = 35.0 - 20.0 * (1.0 - progress) - 15.0 * item_frac;
        if next_item_size > 0 && (next_item_size as f64) <= cap - item_size as f64 {
            score -= 10.0; // next item can join the fresh bin too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size) are heavily penalized.
    let dead = (10u32).saturating_sub(post_residual);
    score += dead as f64 * 8.0;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from many open bins: discourage spreading when bins are plentiful,
    // but allow new-bin opening when open bins are few.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += open_pressure;

    // New empty bin candidate: penalize unless it absorbs a large item cleanly
    // or current bins are too fragmented (mean residual low relative to item).
    if bin_residual == bin_capacity {
        score += 12.0;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= fill_ratio * 30.0;
        if mean_residual < item_size as f64 * 1.2 && bin_residual >= item_size {
            score -= 20.0;
        }
    }

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would NOT fit the post-residual, the leftover is likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Reward tight fits relative to current residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Mild early-stream tolerance for opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer post_residual close to next item size (small slack).
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize proportionally to how badly it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 20.0 + miss;
        }
    }

    // Penalize dead space that is too small for typical items (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Slight preference for opening new bins early in the stream (more flexibility later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin candidate: attractive when open bins are crowded or fit is loose.
        score -= 30.0 * (1.0 - progress);
        if post_residual > 60 {
            score += 40.0; // discourage wasting a fresh bin on a tiny item late
        }
    }

    // Mild penalty for proliferating bins.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    score += 0.6 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward filling bins nearly completely.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.3 * (post_residual as f64).min(next_item_size as f64 * 2.0);
        }
    } else {
        // Last item: strongly favor minimal final residual.
        score += 2.0 * post_residual as f64;
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: prefer using open bins unless the fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Open new bins more freely early, or when open bins are crowded.
        let crowd = mean_residual / bin_capacity as f64;
        let openness = 6.0 * (1.0 - progress) + 15.0 * crowd;
        // Penalize new bin; overcome only when existing fits are bad (high post_residual elsewhere).
        score += 20.0 + openness;
        if next_item_size > 0 && next_item_size >= item_size {
            // If next item is bigger, a fresh bin may be valuable.
            score -= 6.0;
        }
    } else {
        // Slight penalty for spreading items across too many bins.
        score += 0.15 * open_bins_count as f64;
    }

    // Encourage leaving residuals that are multiples of common small sizes (10..20).
    for s in [10u32, 20, 25, 50].iter() {
        if post_residual == *s {
            score -= 3.0;
        }
    }

    // Mild stochastic-free tie-breaking via bin state diversity.
    score -= 0.05 * (bin_residual as f64 - mean_residual).abs().recip().min(2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: minimize post-residual, with a non-linear penalty on large wasted space.
    let mut score = pr;

    // Smooth polynomial coupling: residual waste penalized more as stream progresses.
    let waste_curve = norm_pr * norm_pr * (norm_pr - 2.0); // in [-1, 0], most negative near pr=cap/2
    score -= 40.0 * (1.0 + progress) * (-waste_curve);

    // Tight fits rewarded, amplified late in the stream.
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Dead-space penalty: residuals too small for typical future items.
    if norm_pr > 0.0 && norm_pr < 0.1 {
        score += 30.0 * (0.1 - norm_pr) * (1.0 + 2.0 * progress);
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score -= 20.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 10.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Last-chance bonus: only bin that fits -> strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Mild preference for bins below mean residual (balancing load early).
    let resid = bin_residual as f64;
    if resid > mean_residual {
        score += 3.0 * (resid - mean_residual) / cap;
    } else {
        score -= 1.5 * (mean_residual - resid) / cap;
    }

    // New-bin candidate: penalize slightly early, more when open bins exist and fit poorly.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).max(0.0);
        score += 8.0 + 6.0 * (1.0 - progress) - 4.0 * scarcity.min(3.0) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: treat residual space in modulo classes of capacity.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction remaining

    // Dead-space penalty: residuals that are hard to fill (small remainders)
    // get a nonlinear penalty. Classify by integer division thresholds.
    let class = post_residual / 10; // harmonic class width 10
    let class_penalty = match class {
        0 => 60.0,                 // 0..9  : nearly dead space
        1 => 25.0,                 // 10..19: poor
        2 => 8.0,                  // 20..29: usable
        3 | 4 => -5.0,             // 30..49: good slots
        5 | 6 => -10.0,            // 50..69: attractive slots
        _ => 0.0,
    };
    score += class_penalty;

    // Modulo coupling: post_residual congruent to 0 mod 20 leaves "harmonic"
    // slots that pair well with mid-size items.
    let m = post_residual % 20;
    if m == 0 && post_residual > 0 {
        score -= 12.0;
    } else if m == 10 {
        score -= 5.0;
    } else {
        score += m as f64 * 0.4;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly-ish.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 20.0;
        } else if gap <= 15 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual -> future dead space risk
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Progress-aware pressure: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Penalize bins far from the mean residual (avoid fragmenting outliers),
    // scaled by how crowded the bin set is.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * (0.05 + 0.05 * open_bins_count as f64 / 10.0);

    // Fractional shaping: quadratic bonus for tight fits (small frac).
    score += frac * frac * 10.0;

    // New-bin candidate: make empty bins moderately attractive only when the
    // fit into open bins would be very poor (large post_residual relative to
    // capacity). Otherwise keep using open bins.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        if waste as u32 > bin_capacity / 2 {
            score -= 15.0; // poor fit anywhere -> fresh bin
        } else {
            score += 25.0; // decent fit -> prefer open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Penalize post_residual that cannot host even the smallest future item (1).
    if post_residual < 1 {
        score += 100.0;
    }

    // Reward bins whose post_residual can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: prefer using existing bins over opening new ones,
    // scaled by how crowded the bin pool already is.
    let pressure = open_bins_count as f64 / 8.0;
    score += pressure * (bin_residual as f64 - item_size as f64).max(0.0) * 0.05;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Make the brand-new empty bin slightly less attractive than a decent fit.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: prefer existing bins unless fit is poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; reduced when few bins can fit
        // (last-chance situations) or when post_residual is a useful chunk.
        let mut new_bin_penalty = 18.0;
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 14.0;
        }
        if post_residual as f64 >= mean_residual {
            new_bin_penalty -= 6.0;
        }
        score += new_bin_penalty;
        return score;
    }

    // Perfect 2-step chain: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Next item fits comfortably with slack left over: mild reward.
    else if next_item_size > 0 && post_residual > next_item_size {
        score -= 6.0;
        // Reward proportionally tighter chains (less slack wasted).
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot follow: penalize dead space relative to next item.
    else if next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Exact fit of the current item: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Penalize small unusable fragments (dead space < 10).
        if post_residual < 10 {
            score += 12.0;
        }
        // Reward leaving residual near mean (balanced packing).
        score -= 0.3 * (post_residual as f64 - mean_residual).abs();
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Early in stream: encourage spreading across bins (keeps residuals flexible).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating small dead space that is hard to reuse (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: make empty bins attractive only when no
    // good fit exists among open bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits -> open a new bin
        } else {
            // Opening a new bin is only good if existing fits are poor.
            let poor_fit = fit_ratio < 0.6;
            score += if poor_fit { 5.0 } else { 25.0 };
        }
    }

    // Global state: when many bins are open with large mean residual,
    // discourage opening more bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    score += 0.15 * bin_pressure * (1.0 - 0.5 * progress);

    // Mild time-horizon term: early in the stream, keep residuals flexible.
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear (quadratic) penalty
    let mut score = pr * (1.0 + 0.8 * x * x);

    // Stream-progress coupling: later in stream, penalize larger dead space more strongly
    score += 30.0 * x * x * (0.5 + progress);

    // Reward tight fits: interaction between item size and residual
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio * (1.0 - progress * 0.5);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - x);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // next item won't fit: penalize wasted residual that can't chain
        score += 10.0 * x * (1.0 - progress);
    }

    // Mean-residual coupling: penalize creating residuals far from the mean (fragmentation)
    score += 8.0 * (x - mean_residual / cap).abs();

    // New-bin candidate handling: make empty bin attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).abs();
        score = 40.0 + 60.0 * fragmentation - 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact division classes of capacity
    let pr = post_residual;
    let harmonic = if pr == 0 { 0.0 }
        else if pr % 50 == 0 { -6.0 }
        else if pr % 25 == 0 { -4.0 }
        else if pr % 10 == 0 { -3.0 }
        else if pr % 5 == 0 { -1.5 }
        else { 2.0 };
    score += harmonic;

    // Fractional fill: reward tight fills
    let fill = item_size as f64 / cap;
    score -= 12.0 * fill * fill;

    // Dead-space penalty: small awkward residuals are bad
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / cap);
            // harmonic class of the pair residual
            if (pr - next_item_size) % 10 == 0 { score -= 2.0; }
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by leftover size
            score += 0.05 * pr as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 25.0 + 10.0 * (1.0 - progress);
        // open new bin if item is large and would leave small awkward residual elsewhere
        if item_size as f64 > 0.6 * cap && (bin_residual - item_size) < 20 && fitting_bins_count > 0 {
            score -= 5.0; // still slightly discourage, keep new bins as fallback
        }
        score += base;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 3.0;
        }
    }

    // Spread-aware tiebreak: prefer bins below mean residual (consolidate)
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item (1..100 stream),
    // but practically we treat gaps below ~20 as near-dead and gaps below 10 as fully dead.
    if post_residual < 10 {
        score += 60.0; // fully dead gap
    } else if post_residual < 20 {
        score += 25.0; // near-dead gap
    } else if post_residual < 35 {
        score += 8.0; // mildly awkward gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward
    }

    // Perfect / near-percent fit bonus scaled by tightness
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Lookahead coupling: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next == 0 {
            score -= 30.0;
        } else if after_next < 10 {
            score += 15.0; // would create dead space next step
        } else {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty for leaving stranded gap
        if post_residual < next_item_size && post_residual > 0 && post_residual < 15 {
            score += 10.0;
        }
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: penalize opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // brand-new bin candidate
        score += 15.0 + 2.5 * open_bins_count as f64;
        // but if item is large, new bin may be fine
        if item_size > 60 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably from mean
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score += 0.15 * (mean_residual - res_f);
    } else {
        score -= 0.05 * (res_f - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // matches the next item's size (perfect chaining), penalize large gaps.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * gap;
        // Perfect lookahead match: strong bonus.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits snugly but not perfectly: mild bonus.
        else if post_residual >= next_item_size {
            score -= 12.0;
        }
        // Post-residual too small for the next item: penalize dead space.
        else {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // No lookahead available (last item): just minimize waste.
        score += 0.2 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable;
    // filling a loose bin is cheap, filling a tight bin wastes potential.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel.max(0.0);

    // Perfect closure bonus: exactly filling the bin is always great.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance rescue: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless it creates huge dead space).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
        if post_residual > 25 {
            score += 0.4 * (post_residual as f64 - 25.0);
        }
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item
    // would leave big dead space in every fitting bin or when no bins fit well.
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins.
        score += 45.0;
        // More attractive late in the stream when many bins are open and loose.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // If the current item is large, a fresh bin gives future flexibility.
        score -= 0.25 * item_size as f64;
        // Penalize opening new bins when the next item could chain into this one.
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64) >= 0 {
            score -= 10.0;
        }
    }

    // Slight penalty for very small unusable remnants (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let residual = bin_residual as f64;
    let fit_ratio = item_size as f64 / residual.max(1.0);
    score -= 45.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing (min item ~1) can use later.
    if post_residual > 0 && post_residual < 12 {
        score += 30.0 * (12 - post_residual) as f64;
    }

    // Lookahead: reward if the next item fits into post_residual (chain packing).
    if next_item_size > 0 {
        if next_item_size as f64 <= post_residual as f64 {
            score -= 18.0 + 0.15 * next_item_size as f64;
        } else {
            // Dead-end for lookahead item: penalize proportionally to wasted capacity.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 12.0 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no good
    // fit exists (few fitting bins, large item relative to mean residual).
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let item_heavy = item_size as f64 / bin_capacity as f64;
        let late = step_index as f64 / total_items.max(1) as f64;
        let attract = 20.0 + 40.0 * scarcity * item_heavy + 15.0 * late * item_heavy;
        score += attract;
        // Opening a bin is cheaper when many bins are already open and mean
        // residual is high (fragmentation already present).
        score -= 0.05 * open_bins_count as f64 + 0.1 * mean_residual;
    } else {
        // Mild penalty for using bins that are already fragmented.
        score += 0.02 * (mean_residual - bin_residual as f64).abs();
    }

    // Time horizon: as the stream nears its end, prefer consolidating into
    // existing bins (avoid leaving many half-empty bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: dead-space penalty grows quadratically with progress
    let norm_pr = pr / cap;
    score += 30.0 * progress * norm_pr * norm_pr;

    // Perfect fit reward, amplified late in the stream
    score -= 15.0 * (1.0 - norm_pr) * (1.0 + 2.0 * progress);

    // Penalize leaving space that matches the next item's size less than needed
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 5.0 * progress * (gap / cap);
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer bins tighter than the mean residual
    score += 3.0 * (pr - mean_residual) / cap;

    // Mild preference for consolidating into few bins early on
    score += 2.0 * (1.0 - progress) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space: bins whose post-residual falls into
    // "usable" residue classes modulo 10 are more likely to host future items.
    let r = post_residual % 10;
    let residue_penalty: f64 = match r {
        0 => -18.0,                 // perfectly aligned residual (10/20/.../100)
        1 | 9 => 14.0,              // nearly aligned -> awkward dead space
        2 | 8 => 6.0,
        3 | 7 => -4.0,
        4 | 6 => 2.0,
        _ => 0.0,                   // r == 5
    };
    score += residue_penalty;

    // Integer-division thresholds: large post-residuals that still form a
    // "half-bin" class are valuable; tiny residuals are near-waste.
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 10.0;
    } else if post_residual < bin_capacity / 10 {
        score += 12.0;              // dead-space class
    }

    // Coupling with lookahead item: reward if next item fits exactly into the
    // harmonic class of the post-residual (same decade or exact match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;          // perfect closure for the next item
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 {
                score -= 12.0;      // next placement keeps alignment
            } else {
                score -= gap as f64 / 20.0;
            }
        } else {
            // next item cannot fit here: penalize proportionally to how much
            // space would remain stranded relative to its size class
            score += (next_item_size - post_residual).min(20) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Empty new-bin candidate: only attractive when current item is large
    // (harmonic class of item itself) or no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let item_class = item_size / 10;
        score += 20.0 - item_class as f64 * 2.0; // small items -> new bin is bad
        if post_residual % 10 == 0 && item_size % 10 == 0 {
            score -= 8.0;           // aligned pair keeps future flexibility
        }
        if mean_residual < item_size as f64 {
            score -= 15.0;          // open bins are too full -> new bin justified
        }
    }

    // Late in the stream, squeeze tighter into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage proliferation, favor filling existing ones.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.5;
    }

    // Slight preference for bins below mean fullness (balance residuals).
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are nearly full.
    if bin_residual == bin_capacity {
        score -= mean_residual * 0.8;
        score += 10.0;
    }

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item fill the bin exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item could still fit here; reward tight chains.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 / (1.0 + slack / 10.0);
        } else {
            // Next item won't fit after this placement: penalize leftover dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.5;
        }
        // Bonus if next item exactly matches the residual BEFORE this placement
        // (bin becomes perfectly consumed by the pair).
        if bin_residual as f64 == (item_size + next_item_size) as f64 {
            score -= 40.0;
        }
    } else {
        // Last item: just minimize post residual.
        score += 0.1 * post_residual as f64;
    }

    // Relative-to-mean residual shaping: prefer bins whose post residual
    // sits close to the mean residual (keeps bins homogeneous).
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mild penalty for wasting space in a nearly-full bin context.
    if pr < 10 {
        score -= 8.0; // excellent compaction
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Cheaper to open a new bin if no open bin offers a tight fit.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can host the next item too
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight stream-position modulation: later in the stream, favor tighter fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (pr / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residual that is too small to hold even the smallest item.
    if post_residual < 10 {
        score -= 8.0; // small but acceptable leftover
    } else if post_residual < 20 {
        score += 4.0; // awkward zone
    } else if post_residual > 60 {
        score += 6.0 * (post_residual as f64 - 60.0) / 40.0; // wasteful leftover
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this bin remains useful; if the post-residual barely misses it, penalize.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual as f64 - next) / bin_capacity as f64);
        } else if post_residual > 0 && next > post_residual && next - post_residual as f64 <= 10.0 {
            score += 8.0; // next item just misses this bin: dead space likely
        }
    }

    // Time horizon: early in the stream, prefer consolidating into few bins
    // (penalize new-bin usage); late in the stream, be more liberal.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, mildly reward late if mean residual is low.
        let early_penalty = 40.0 * (1.0 - progress);
        let mean_bonus = if mean_residual < item_size as f64 { 5.0 } else { 0.0 };
        score += early_penalty - mean_bonus - 10.0 * progress;
    } else {
        // Existing bin: slight preference when many bins are already open
        // (consolidation pressure), scaled by stream progress.
        score -= 0.3 * open_bins_count as f64 * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (rebalance toward tighter bins).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize leftover dead space, quadratically scaled.
    let mut score = pr * (1.0 + 0.02 * pr / cap);

    // Smooth coupling: dead space hurts more as the stream progresses.
    score += 6.0 * progress * (pr / cap) * (pr / cap) * cap * 0.1;

    // Reward tight fits (small post_residual) with a saturating bonus.
    let tight = 1.0 - (pr / cap).min(1.0);
    score -= 18.0 * tight * tight * (1.0 + 0.5 * progress);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 * (1.0 - slack) * (1.0 - 0.5 * progress);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize more late in the stream.
        score += 4.0 * (0.5 + progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.3 * progress);
    }

    // New-bin candidate: penalize mildly early (prefer filling open bins),
    // but relax the penalty late so a fresh bin is viable for good future packing.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 12.0 - 8.0 * progress + 0.05 * open_bins_count as f64;
        score += new_bin_penalty.max(2.0);
    }

    // Slight penalty when this bin deviates from the mean residual
    // (encourages balanced residual distribution across bins).
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).abs() * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on residual space.
    let post = post_residual as f64;
    let class = (post_residual % 10) as f64;

    // Reward small post_residual, but penalize "dead" residuals too small
    // for the smallest possible item (min item = 1 here, but small slivers
    // below ~10 are statistically near-dead on unknown distributions).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver penalty
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Harmonic class bonus: residuals that are multiples of 10 pair well
    // with the typical item-size grid; encourage landing on those classes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else {
        score += class * 0.15;
    }

    // Lookahead coupling: if next item fits exactly into the post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            let fill_ratio = nxt / post.max(1.0);
            // Prefer leaving residuals that the next item fills well.
            score -= 8.0 * fill_ratio;
            // Penalize leaving a residual that next item leaves a sliver in.
            let nxt_post = post - nxt;
            if nxt_post > 0.0 && nxt_post < 10.0 {
                score += 5.0;
            }
        } else {
            // Next item cannot use this residual at all: residual likely dead.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate (residual == capacity): mild penalty so we prefer
    // reusing open bins unless their scores are genuinely bad; the base
    // score of a new bin is `capacity`, which is large, so it only wins
    // when open bins would waste a lot of space.
    if bin_residual == bin_capacity {
        score += 5.0 + (open_bins_count as f64) * 0.05;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "tight" — finishing it off is good (reduces bin count).
    let dev = mean_residual - post;
    if dev < 0.0 {
        score += (-dev) * 0.10;
    } else {
        score -= dev * 0.05;
    }

    // Stream progression: early on, be greedy about tight fits; later,
    // allow slightly looser packing to consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.1 * progress;

    // Integer-division threshold: reward placements leaving residuals in
    // "reusable" bands via floor division classes.
    let band = post_residual / 10;
    match band {
        0 => score += 3.0,   // 0..9 mostly dead
        1 | 2 => score -= 2.0, // 10..29 highly reusable
        3 | 4 => score -= 1.0, // 30..49 decent
        _ => {}               // large residuals: neutral
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Medium gaps (10..20) are risky too, moderate penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0 - (post_residual as f64) * 0.2;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item cannot use the leftover: dead space likely.
            score += (post_residual as f64) * 0.4;
        }
    }

    // Open-bin pressure: discourage scattering across many bins unless fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    // (item leaves a large residual in an open bin) or few alternatives exist.
    if bin_residual == bin_capacity {
        // Neutral base; penalize when many bins fit the item (prefer reusing).
        score += 15.0 + (fitting_bins_count as f64) * 10.0;
        // But discount when item is large relative to capacity (hard to place later).
        if (item_size as f64) / (bin_capacity as f64) > 0.7 {
            score -= 25.0;
        }
    }

    // Mild attraction to bins below mean residual (consolidate loose space).
    score += ((mean_residual - bin_residual as f64) * 0.15).clamp(-10.0, 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Reward bins whose post_residual closely matches the next item size.
    if next_item_size > 0 {
        let match_err = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for near-perfect chain fit (post_residual == next_item_size)
        score -= 60.0 * (-match_err / 12.0).exp();
        // Smoother secondary reward for moderate proximity
        score -= 20.0 * (-match_err / 40.0).exp();
        // Penalize leaving residual that is unusable (too small for min item, too big to ignore)
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 10.0;
    }

    // Compare against mean residual: prefer bins already below-average residual
    // (consolidating space) unless lookahead match says otherwise.
    let res_gap = post_residual as f64 - mean_residual;
    score += 0.15 * res_gap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize near-empty open bins being consumed early unless lookahead matches well
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    if fill_frac > 0.9 {
        score -= 8.0; // reward near-perfect fills
    }

    // New-bin candidate handling: only attractive late in the stream or when
    // open bins would create large dead space; otherwise discourage.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead_space_penalty = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else {
            0.0
        };
        score = 100.0 + progress * 40.0 - dead_space_penalty * 0.3;
        // If existing bins are last-chance, opening a new bin is bad
        if fitting_bins_count == 1 {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small dead space that is hard to reuse (relative to typical item sizes)
    if post_residual > 0 {
        let waste = post_residual as f64;
        if waste < 20.0 {
            score += (20.0 - waste) * 3.0;
        }
    }

    // Lookahead: reward leaving space that fits the next item
    if next_item_size > 0 {
        if post_residual as u64 == next_item_size as u64 {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            score -= 30.0;
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer tighter bins (best-fit flavor)
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keeps residual space flexible); late in stream, consolidate.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        // new-bin candidate
        let new_bin_bonus = 40.0 * (1.0 - progress) - 20.0 * progress;
        score += new_bin_bonus;
        // don't open a new bin if a decent fit exists elsewhere
        if post_residual > 0 && fitting_bins_count > 0 {
            score += 10.0;
        }
    } else {
        // existing bin: mild bonus late in stream
        score -= 10.0 * progress;
    }

    // Penalize bins far below mean residual (fragmented usage) mildly
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    // Many open bins: encourage filling existing ones
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling: dead-space penalty grows quadratically with
    // normalized residual, modulated by stream progress.
    score += 20.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: small post-residual relative to item size gets a bonus.
    score -= 15.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead coupling: penalize residual that can't hold the next item,
    // reward residuals that snugly match it (smooth quadratic mismatch term).
    if next_item_size > 0 {
        let mismatch = (norm_pr - norm_next).abs();
        score += 10.0 * mismatch * mismatch;
    }

    // Last-chance bonus: if this is the only fitting bin, encourage using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr * norm_pr);
    }

    // Smooth global pressure: bins below mean residual are slightly favored.
    score += 5.0 * (pr - mean_residual) / cap;

    // Late-stream conservatism: penalize opening/keeping loose bins as stream ends.
    score += 12.0 * progress * norm_pr * norm_pr * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo 10 quantizes dead space.
    let r = post_residual % 10;
    // Residues 1..9 are "awkward" leftovers; 0 and small residues < 3 are good (dead space).
    if post_residual > 0 {
        if r == 0 {
            score -= 12.0; // perfectly harmonic residual, reusable by multiples of 10
        } else if r <= 2 {
            score -= 8.0; // near-dead residual, effectively filled
        } else if r >= 7 {
            score += 3.0; // awkward large-ish awkward residue
        } else {
            score += 6.0; // mid residues (3..6) are worst for future fits
        }
    } else {
        score -= 20.0; // exact fill: perfect
    }

    // Integer-division threshold classes on post_residual
    let cls = post_residual / 10; // 0..10 harmonic decile
    score += cls as f64 * 1.5; // prefer smaller leftover decile

    // Lookahead coupling: does the next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward if next item leaves another harmonic residue
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 {
                score -= 10.0;
            } else if nr <= 2 {
                score -= 6.0;
            } else {
                score += (nr % 10) as f64 * 0.4;
            }
        } else {
            score += 5.0; // next item won't chain into this bin
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // penalize opening a new bin unless it creates harmonic structure
        score += 25.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress); // early stream: new bins cheaper
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // if item is large relative to capacity, new bin is natural
        if item_size * 2 >= bin_capacity {
            score -= 15.0;
        }
    }

    // Prefer bins with residual close to item (tight fit) via fraction of capacity
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 8.0; // quadratic penalty on wasted fraction

    // Slight penalty when bin residual diverges from mean residual (imbalance)
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty when post_residual falls into
    // the "unusable gap" band (too small for the smallest plausible item).
    if post_residual > 0 && post_residual < 20 {
        score += 60.0;
    } else if post_residual < 35 {
        score += 12.0 * (1.0 - post_residual as f64 / 35.0);
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // If the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 90.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here: dead end for lookahead, mild penalty.
        score += 8.0;
    } else if next_item_size > 0 {
        // Prefer leaving a gap the next item can use without much waste.
        score += 0.15 * (post_residual - next_item_size) as f64;
    }

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bins pressure: discourage opening new bins when load is low,
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow and stream progresses.
        score += 25.0 + 10.0 * pressure + 20.0 * progress;
        // But allow a new bin if all open bins would leave terrible dead space.
        if post_residual >= 20 && post_residual < 35 && bin_residual >= item_size {
            score -= 55.0;
        }
    } else {
        // Slight preference for bins tighter than the mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits and leaves a chainable residual
            score -= 50.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot fit here: dead space risk grows
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Compare post-residual against mean residual of open bins.
    // Leaving a residual well below mean creates hard-to-fill leftovers.
    score += (mean_residual - post_residual as f64).abs() * 0.2;

    // Penalize small unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., item barely fits anywhere) or early in the stream.
    if bin_residual == bin_capacity {
        let tight_fit = (bin_residual - item_size) as f64;
        let poor_alternatives = if fitting_bins_count == 0 { 400.0 } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 100.0 + tight_fit * 0.5 - poor_alternatives - progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize leaving dead space that no future item (min size 1) could use poorly;
    // small residuals (< 10) are nearly dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's remainder: mild penalty if remainder becomes stranded.
            score += 8.0 * (post_residual as f64 / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global pressure: when many open bins, prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score *= 1.0 + 0.05 * pressure;

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, or when item is large and mean residuals are small.
        score -= 55.0 * (1.0 - progress);
        if item_size >= 60 {
            score -= 10.0;
        }
        if mean_residual > 0.0 && (item_size as f64) > mean_residual {
            score -= 12.0;
        }
    } else {
        // Existing bin: better late in the stream.
        score -= 15.0 * progress;
    }

    // Prefer bins whose residual is close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let mut score = post;

    // non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_post * norm_post * (1.0 - progress) * 40.0
                 + norm_post * progress * progress * 25.0;
    score += coupling;

    // reward tight fits, penalize dead space more as stream advances
    score -= (1.0 - norm_post) * (1.0 - norm_post) * 15.0 * (0.5 + progress);

    // last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // lookahead: favor bins whose post-residual fits the next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            score -= 10.0 * (next / cap);
        } else {
            score += 5.0 * (next / cap) * norm_post;
        }
    }

    // new-bin candidate handling: penalize slightly so it's chosen only on poor fits
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress;
    }

    // spread awareness: prefer bins below mean residual (tighter bins)
    score -= (mean_residual - post) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction buckets
    let frac = item_size as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i64; // 0..=6-ish harmonic class

    // Post-residual harmonic class: how "reusable" is the leftover space
    let pr = post_residual;
    let pr_class = pr / 10; // integer division threshold buckets of 10

    // Reward tight fits strongly
    if pr == 0 {
        score -= 1000.0;
    } else if pr <= 10 {
        score -= 200.0;
    } else if pr <= 25 {
        score -= 50.0;
    }

    // Penalize dead space in harmonic bands: leftover that few item classes can use
    let usable = (pr / 10).min(8) as f64; // how many 10-wide classes fit leftover
    score += (post_residual as f64) * (1.0 - usable / 8.0) * 0.5;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        let next_frac = next_item_size as f64 / bin_capacity as f64;
        let next_class = (next_frac * 8.0).floor() as i64;
        if next_class == class {
            // same harmonic class chain -> excellent packing
            score -= 150.0;
        }
        score -= 30.0 + (pr - next_item_size) as f64 * 0.3;
    } else if next_item_size > pr {
        // next item cannot use this bin's leftover -> penalize mildly
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin gets a mild baseline cost so we
    // prefer existing bins unless fit is bad.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 0.5;
        // but if current item is large and no bin fits well, new bin is fine
        if item_size >= 50 && fitting_bins_count <= 1 {
            score -= 60.0;
        }
    }

    // Prefer fuller bins (lower residual) via mean-residual contrast
    score -= (bin_residual as f64 - mean_residual) * 0.4;

    // Stream progression: late in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    // Modulo tie-breaker on post_residual classes to break ties deterministically
    score += ((pr_class % 3) as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=12) are nearly unusable dead space.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0;
    } else if post_residual > 12 && post_residual <= 25 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Favor bins whose residual can still host the lookahead item exactly-ish.
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            // Keeps room for the next item: reward proportional to slack match.
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Post placement can no longer host the next item: penalty.
            score += 10.0;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer tightening existing ones.
    score += (open_bins_count as f64) * 0.4;

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * (post_residual as f64);
    }

    // Mild progression tilt: early on, be slightly more tolerant of imperfect fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual,
    // penalize when post_residual is small but unusable by the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 400.0; // perfect chain
        } else if post_residual >= next_item_size {
            let slack = post_residual as f64 - nxt;
            score -= 150.0 / (1.0 + slack / 20.0); // next item fits well
        } else {
            // dead space relative to next item: penalize more the smaller the waste
            let waste = nxt - post_residual as f64;
            score += 60.0 * (1.0 - (waste / 100.0).min(1.0));
        }
    }

    // Compare against mean residual: bins with residual far below mean are
    // "tight" bins — using them is good (keeps large residuals for large items).
    let dev = mean_residual - post_residual as f64;
    score += 0.5 * dev;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate (residual == capacity): only attractive when item is
    // large relative to capacity or no decent open fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin; the penalty shrinks for large items.
        score += 250.0 * (1.0 - fill_ratio);
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 80.0; // room for the next item too
        }
    }

    // Early in the stream, allow more bins to be opened (flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 100.0 * (1.0 - progress);
    } else {
        score += 50.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize dead space: residuals too small for typical future items (1..=100 unknown).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0;  // hard-to-fill zone
    }

    // Lookahead coupling: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0; // next item won't fit here
        }
    } else {
        // Last item: only post residual matters, prefer any fit over new bin.
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: early in stream, opening bins is cheap; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 15.0 * progress; // penalize new bins more later

    // New-bin candidate handling: attractive early or when item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs();
        let early_urgency = (1.0 - progress) * 20.0;
        let poor_fit_penalty = if item_size as f64 > mean_residual { 10.0 } else { 0.0 };
        score += 8.0 - early_urgency - poor_fit_penalty - 0.05 * spread;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating into fat bins.
    if open_bins_count > 3 {
        let fat = (bin_residual as f64 - mean_residual).max(0.0);
        score -= 0.08 * fat;
        score += 0.5 * (open_bins_count as f64 - 3.0).min(10.0);
    }

    // Mild preference for bins whose residual is close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64);
    score += 0.03 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: post residual, with smooth polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.35 * progress * (1.0 - norm_pr));

    // Quadratic dead-space penalty: small post-residuals are wasted space,
    // penalize smoothly as a function of normalized residual.
    score += 18.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Reward tight fits with a smooth cubic term in normalized residual.
    score -= 12.0 * norm_pr * (1.0 - norm_pr) * (1.0 + 0.5 * progress);

    // Lookahead: reward bins whose post-residual can host the next item,
    // with smooth interaction between fit quality and progress.
    if next > 0.0 && pr >= next {
        let fit_quality = 1.0 - (pr - next) / cap;
        score -= 10.0 * fit_quality * fit_quality * (1.0 - progress);
    } else if next > 0.0 {
        // Smooth penalty when next item cannot fit here.
        score += 8.0 * (next - pr) / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // smoothly rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr) * (0.5 + 0.5 * progress);
    }

    // Mild penalty when this bin's residual is far from the mean residual,
    // encouraging balanced residual distribution (smooth coupling).
    let dev = (pr as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * (1.0 - progress);

    // New-bin candidate handling: empty bin should only win when post-residual
    // is large relative to capacity (good long-term host), scaled by progress.
    if bin_residual == bin_capacity {
        score += 6.0 + 25.0 * norm_pr * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, but non-linearly.
    score = score.powf(1.15);

    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" sizes
    // likely to be fillable by future items (multiples of 10, and small residuals).
    if post_residual == 0 {
        score -= 50.0; // perfect fit is ideal
    } else if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual <= 10 {
        score -= 5.0; // small dead space
    } else if post_residual % 10 <= 2 || post_residual % 10 >= 8 {
        score -= 2.0; // near a harmonic class boundary
    } else {
        score += 3.0; // awkward mid-class residual
    }

    // Integer-division thresholds: how many items of the *next* size fit in post space.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fits = post_residual / next_item_size;
        score -= 6.0 * fits as f64;
        if fits >= 2 {
            score -= 4.0;
        }
        // Exact fill by next item is excellent.
        if post_residual % next_item_size == 0 {
            score -= 7.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize proportional to dead space.
        score += (next_item_size as f64 - post).min(20.0) * 0.4;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only open a new bin if current open bins are fragmented
    // or this is a poor fit elsewhere. Penalize opening new bins mildly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post).abs();
        score += 18.0 + 10.0 * (1.0 - progress) + fragmentation * 0.3;
        // Large items justify fresh bins more.
        if item_size >= bin_capacity / 2 {
            score -= 12.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Mild penalty for spreading across many bins when mean residual is already low.
    if open_bins_count > 4 && mean_residual < 15.0 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

