    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward proportional to leftover fit quality
            score -= 10.0 * (next_item_size as f64 / (post_residual.max(1) as f64));
        } else {
