    // Global pressure: when many bins are open relative to progress, prefer
    // consolidating into existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64) / (1.0 + 10.0 * (1.0 - progress));
    score += 2.0 * pressure;

    // Compare bin residual to mean residual: prefer bins with below-average
    // residual (i.e., fuller bins) to keep a pool of large-residual bins.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: make an empty bin moderately attractive only
    // when the item is large and few bins fit it, otherwise discourage.
    if bin_residual == bin_capacity {
        let big_item = (item_size as f64) / (bin_capacity as f64);
        if fitting_bins_count <= 1 {
