    // post_residual in {0, 10..30} pairs well with small items.
    match post_class {
        0 => score -= 30.0,                       // perfect fill
        1 => score -= 18.0,
        2 => score -= 10.0,
        3 => score -= 4.0,
        4 => score += 6.0,                        // awkward ~40-49 dead space
        5 => score += 10.0,
        6 => score += 14.0,
        7 => score += 18.0,
        8 => score += 22.0,
        _ => score -= 2.0,                        // large residual still reusable
    }

    // Modulo coupling: if post_residual and next_item_size share a residue
    // class mod 10, the next item likely fits tightly.
    if next_item_size > 0 {
        let next_class = next_item_size / 10;
        if next_class <= post_class {
            score -= 8.0 + 2.0 * next_class as f64;
        }
        if next_item_size <= post_residual {
            score -= 6.0;
            if post_residual - next_item_size < 10 {
                score -= 10.0; // chains into near-perfect fill
            }
        } else {
            score += 4.0; // next item can't use this bin anyway
        }
    }

    // Last-chance bin: strongly prefer filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
