        }
        // Late in the stream, opening new bins wastes capacity; penalize more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    } else {
        // Reward using existing bins, especially when they are the last chance.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Reward tightness relative to mean residual of open bins.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Slight bonus for filling large items into bins (reduces fragmentation risk).
        score -= (item_size as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual that matches next_item_size exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item: strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += gap * 0.5;
        }
        // If the next item could still fit here after this placement, mild reward.
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Penalize dead space that can never be used by typical items (post_residual < 10... but sizes 1..100, so penalize very small remnants).
    if post_residual < 5 {
        score += 15.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins), penalize hoarding space in large-residual bins.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins would leave big waste.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; lookahead can offset it if the new bin promises a good chain.
        score = bin_capacity as f64 - 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (bin_capacity - next_item_size) as f64 * 0.3;
        }
        // Late in the stream, discourage opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Slight preference for tighter fills overall.
    score -= item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (low post residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    // (unusable sliver). If post_residual is tiny but nonzero, it's wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: strongly reward if the next item fits exactly or well in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - next_slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty for leaving awkward space.
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Penalize spreading across too many open bins when mean residual is high:
    // prefer filling bins that are already relatively full compared to the mean.
    let rel_fullness = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 20.0 * rel_fullness;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // Cheaper to open a new bin when many bins are already open and crowded.
        score -= 10.0 * (open_bins_count as f64).ln().max(0.0);
        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= 0.2 * item_size as f64;
        // Late in the stream, discourage new bins.
        score += 25.0 * progress;
        // If only this new bin can fit, it must win.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;
    let fill = 1.0 - fit_norm;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * fill);

    // Dead-space penalty: small post-residuals that likely cannot fit future items
    let next_fits = (next_item_size as f64) <= pr;
    if next_item_size > 0 && !next_fits {
        score += 2.0 * (1.0 - fit_norm) * (1.0 - progress);
    }

    // Reward exact-ish fits smoothly
    score -= 4.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (1.0 - progress);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Mild penalty for spreading across many bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;

    // New-bin candidate: penalize mildly so it is chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 1.5 + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Small post_residual (< 1/4 capacity) is nearly dead space: penalize by class.
    if post_residual < bin_capacity / 4 {
        score += 12.0 * (1.0 - frac * 4.0);
    } else if post_residual < bin_capacity / 2 {
        score += 4.0;
    }

    // Harmonic class via integer division thresholds on post_residual.
    let class = post_residual / 10; // decade class 0..10
    score -= 2.0 * (class as f64).sqrt();

    // Lookahead coupling: does next item fit into post_residual? (harmonic pairing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect next-fit: strong reward scaled by how snugly it fits.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 + 8.0 * snug;
        } else {
            // Next item won't fit: penalize, worse if gap is small (near-miss).
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 + 5.0 * (1.0 - gap / bin_capacity as f64);
        }
        // Modulo harmony: next item size residue classes that pair well with small residuals.
        let r = (post_residual % 20) as f64;
        let nr = (next_item_size % 20) as f64;
        if (r - nr).abs() < 2.0 && next_item_size <= post_residual {
            score -= 4.0;
        }
    }

    // Last chance bin: reward strongly to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: neutral baseline, slightly above good fits.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Early stream: opening bins is cheap; late stream: prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // Prefer using bins below mean residual (tighter bins first).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Slight preference for bins with many occupants implied by low residual.
    score -= 0.02 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny post residuals are unusable.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 6.0; // heavy penalty for dead space below min item size
    } else if pr >= 10 && pr <= 25 {
        score += 8.0; // moderate penalty for awkward mid-range gaps
    } else if pr == 0 {
        score -= 15.0; // perfect fit strongly rewarded
    }

    // Reward bins whose residual matches the lookahead item size.
    if next_item_size > 0 && pr >= next_item_size && pr <= next_item_size + 15 {
        score -= 6.0;
    }

    // Penalize leaving large residual if it could hold the next item but we waste it.
    if next_item_size > 0 && pr < next_item_size && pr > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: discourage opening new bins when many are open,
    // encourage consolidation when few are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or stream is late.
        score += 5.0 + open_bins_count as f64 * 1.5 + 10.0 * progress;
        // But if no open bin fits well, opening new bin is fine: handled by others' penalties.
        if fitting_bins_count == 0 {
            score -= 8.0;
        }
    } else {
        // Favor tightest fits among open bins, slightly scaled by mean residual.
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;
        if (bin_residual as f64) < mean_residual {
            score -= 2.0; // tighter than average: good consolidation target
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits but leaves a gap; penalize proportional to gap
            let gap = (post_residual - next_item_size) as f64;
            score -= 200.0 - 0.5 * gap;
        } else {
            // next item cannot fit here; penalize tight residuals
            score += 0.3 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize bins far below mean residual (wasteful dead space)
    score += 0.8 * (mean_residual - post_residual as f64).max(0.0);

    // Slight preference for tighter fits relative to bin residual
    score += 0.2 * (bin_residual as f64 - item_size as f64 - post_residual as f64);

    // New-bin candidate: mild penalty so it's chosen only when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * (1.0 - fit_ratio).powi(6);

    // Penalize dead space that can't plausibly hold future items.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
    }
    // Bonus if the next item fits exactly into the post-residual space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Last-chance bin: strong incentive to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize spreading across many open bins when residuals are already small.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins tighter than average early,
    // but late in the stream prefer balancing residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dev = bin_residual as f64 - mean_residual;
    if progress < 0.5 {
        score -= 0.3 * dev;
    } else {
        score += 0.3 * dev.abs();
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or existing fits are poor (post_residual large for all).
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64 / bin_capacity as f64).powi(2);
        score = bin_capacity as f64 * (0.55 + 0.45 * large_item)
            - 6.0 * (1.0 - progress);
        if fitting_bins_count == 1 && post_residual < 20 {
            score += 25.0; // don't open a new bin when a decent fit exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post residual), scaled non-linearly.
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth coupling: late in the stream, tight fits matter more (less waste tolerance).
    score -= (1.0 - pr_norm) * it * (0.5 + progress);

    // Penalize dead space relative to mean residual across open bins (smooth quadratic).
    score += 0.3 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        score -= fit_next * (nx / cap) * 15.0 * (1.0 + progress);
        // Penalize post-residuals just below next item size (near-miss dead space).
        if pr < nx {
            score += (nx - pr) * 0.4;
        }
    }

    // Mild penalty for many open bins to discourage fragmentation late.
    score += open_bins_count as f64 * 0.05 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: empty bin gets neutral-ish baseline so it only wins
    // when open bins score poorly (poor fits / fragmentation).
    if bin_residual == bin_capacity {
        score = cap * (1.1 - 0.3 * progress) - 0.2 * it;
        if fitting_bins_count == 1 {
            score += 40.0; // don't open a new bin when an existing one is the only fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes mod common item sizes
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Perfect fit bonus
    if post == 0 {
        score -= 1000.0;
    }

    // Penalize residuals that fall into "unusable" classes (small dead space)
    if post > 0 && post < 10 {
        score += 60.0; // tiny sliver is nearly useless
    }

    // Harmonic class rewards: residuals divisible by common item sizes
    // are more likely reusable by future items.
    let mut class_bonus = 0.0f64;
    for m in [10i64, 20, 25, 50] {
        if post % m == 0 && post > 0 {
            class_bonus += 8.0;
        }
    }
    score -= class_bonus;

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if post >= n {
            // next item fits here: reward proportionally
            score -= 15.0 + 0.2 * (post - n) as f64;
            // exact fit for next item: strong reward
            if post == n {
                score -= 40.0;
            }
        } else {
            // next item won't fit: penalize wasted lookahead potential
            score += 12.0;
        }
        // Harmonic class of next item size relative to capacity
        let nclass = n % 10;
        if nclass == 0 {
            // round-sized next item: residuals that are multiples of 10 pair well
            if post % 10 == 0 {
                score -= 6.0;
            }
        }
    } else {
        // Last item: any bin is fine, prefer tightest
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only open a new bin when current bin
    // would leave a poor harmonic class behind.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 90.0;
        // But large items (hard to place later) justify a fresh bin
        if item_size >= 50 {
            score -= 50.0;
        }
        // If no open bin fits at all context-wise (single fitting bin is the new bin)
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
        // Late in stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
    }

    // Mean residual coupling: prefer bins far below mean residual
    // (use the emptiest bins first, keep tight bins tight)
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Slight preference to fill more-open-bin situations efficiently
    if open_bins_count > 5 {
        score -= 0.5 * open_bins_count as f64;
    }

    // Integer division threshold: post_residual in [10,30] band is a
    // "half-usable" zone; mild penalty unless divisible by 10
    if post >= 10 && post <= 30 && post % 10 != 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual gap that cannot fit even the smallest plausible item (<= 20)
    // is pure waste; penalize quadratically as it shrinks.
    if post_residual > 0 && post_residual <= 20 {
        score += (21.0 - post_residual as f64) * 8.0;
    }

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Open-bin pressure: discourage spreading across many bins when a good
    // fit exists; mild per-open-bin penalty scaled by how full the bin is.
    let fill = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score += open_bins_count as f64 * (1.0 - fill) * 0.6;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make the empty bin moderately attractive only when
    // the current item is large or the fit elsewhere is poor (large post_residual).
    if bin_residual == bin_capacity {
        // Base hurdle: opening a bin costs; overcome when fit elsewhere is bad.
        score += 12.0;
        // Large items deserve a fresh bin more than small ones.
        score -= item_size as f64 * 0.1;
        // If the next item is large too, a fresh bin may pair them.
        if next_item_size >= 50 {
            score -= 6.0;
        }
        // Early in the stream, opening bins is cheaper (more future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 4.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 10.0;
        } else {
            score -= 3.0;
        }
    }

    // Penalize placements that leave a residual far below the mean residual
    // (fragmenting relative to the fleet average) unless it's a near-perfect fit.
    if post_residual > 0 {
        let dev = mean_residual - post_residual as f64;
        if dev > 0.0 {
            score += dev * 0.15;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        if post_residual as u64 == next_item_size as u64 {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits after this placement: reward tight coupling.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize leftover dead space scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Reward near-perfect fills (small post residual).
    if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating residuals far below mean (fragmenting useful space),
    // reward keeping residuals near the mean.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Late in the stream, prefer closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * post_residual as f64 * progress;

    // Mildly discourage opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 3.0 + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Penalize dead space: small post_residual is good, but a tiny unusable
    // leftover (< 10, minimum item size) is wasted — reward exact/near-exact fits extra.
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.3 * item_size as f64;
    }

    // Lookahead coupling: if the next item fits the post-residual well,
    // reward placing the current item here (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 20.0 * chain_fit;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize leaving a residual too small for the next item (dead space trap).
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Global state: many open bins with high mean residual -> prefer reusing
    // existing capacity rather than fragmenting.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let openness = open_bins_count as f64;
    score += 0.05 * openness * (1.0 - progress);
    score += 0.2 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate handling: an empty bin gets a baseline that is beaten
    // only when an open bin offers a genuinely good fit; but when no open bin
    // fits tightly, opening fresh capacity is attractive.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.4 * item_size as f64 - 15.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Late-stream consolidation: near the end, push everything into existing bins.
    if progress > 0.8 {
        score += 20.0 * progress * (bin_residual == bin_capacity) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fits), with a non-linear penalty
    // that grows super-linearly for large leftover space (dead space).
    let mut score = post + 0.35 * (post * post) / cap;

    // Smooth interaction: as the stream progresses, dead space becomes costlier
    // (less opportunity to fill it later), so amplify the residual penalty.
    score += progress * (post * post) / (cap * cap) * 12.0;

    // Reward bins whose residual was heavily consumed relative to the mean
    // residual across open bins (compactness pressure).
    score -= (mean_residual - post) / cap * 2.0;

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 && (next_item_size as f64 - post).abs() < 1.0 {
        score -= 15.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: mild penalty scaled by wasted space
        score += 3.0 * (post / cap) * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 10.0 * progress;
    }

    // New-bin candidate handling: an empty bin is attractive only when it would
    // be filled substantially now or when open bins are scarce; otherwise
    // penalize spreading items thin.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score = cap * 0.9 - 40.0 * fill_ratio * (1.0 - progress)
            + 10.0 * (open_bins_count as f64).ln().max(0.0);
        if item_size >= 70 {
            score -= 25.0; // big items start fresh bins naturally
        }
    }

    // Small global smoothing term coupling open bins and progress to break ties.
    score += 0.01 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer-division bands (capacity fractions). Residuals in the lowest
    // band (tiny dead space) are excellent; mid-band leftovers are wasteful.
    let band = post_residual / 10; // 0..10 bands over capacity 100
    let band_penalty: [f64; 11] = [0.0, 2.0, 6.0, 10.0, 14.0, 12.0, 9.0, 6.0, 3.0, 1.0, 0.0];
    score += band_penalty[band.min(10) as usize];

    // Perfect-fit reward: leftover in a "harmonic" residue class that a
    // typical item (multiples of 5/10) could still fill exactly.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    // (chained perfect fit), penalize if next item leaves an awkward class.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 6.0;
            } else if nxt_post > 40 {
                score += 3.0;
            }
        } else {
            // next item won't fit here; a large post_residual is stranded
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin for a small item.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // bins offer poor fits. Penalize the fresh bin mildly, scaled by how
    // "harmonic" the placement would be (item_size relative to capacity).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // penalize opening a bin more when the item is small (wasteful start)
        score += 25.0 * (1.0 - item_frac);
        // but if it's a half-capacity or larger item, a fresh bin is cheap
        if item_size % 10 == 0 && item_size >= 50 {
            score -= 10.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer tighter bins overall: compare against mean residual of open bins.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Mild pressure against proliferating bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // "Unusable small gap" band: quadratic dead-space penalty.
        score += (20.0 - post_residual as f64) * 2.5;
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= (bin_capacity as f64 - post_residual as f64 / 2.0) * 0.15;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening yet another.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += open_bins_count as f64 * 1.2;
        // New bin is only attractive if the current bin leaves a bad gap
        // or cannot host the lookahead item.
        if post_residual >= 10 && (next_item_size == 0 || post_residual >= next_item_size) {
            score += 15.0;
        }
    }

    // Lookahead coupling: reward bins whose post_residual can host next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += post_residual as f64 * 0.3; // stranded space relative to lookahead
    }

    // Mean residual coupling: prefer bins deviating below mean residual
    // (compact the emptiest bins first, keep tight bins tight).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Slight late-stream tightening: as stream progresses, favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly or nearly fits the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack * 0.8;
    } else if next_item_size > post_residual {
        // Next item cannot follow here; penalize proportionally to wasted potential
        score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.5;
    }

    // Penalize dead space (unusable residuals) more aggressively for small residuals
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Prefer tighter bins relative to the mean residual
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Slight preference for keeping open bin count low late in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins, especially early/mid stream
        score += 25.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: strong baseline penalty so it's chosen only when
    // open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // If many bins are open, discourage spreading further.
        score += 0.8 * open_bins_count as f64;
        // If the item barely fits anywhere else, opening a bin is attractive.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
        // Lookahead: if the next item is large, a fresh bin is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        return score;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Penalize leaving dead space that is hard to fill later.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead synergy: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 35.0;
        } else if diff <= 5 {
            score -= 15.0;
        } else {
            // Penalize residuals that neither fit next item nor stay useful.
            if (post_residual as f64) < next_item_size as f64 {
                score += 5.0;
            }
        }
    }

    // Global state coupling: if mean residual is high, prefer bins that
    // reduce fragmentation (i.e., tight fits); if low, mild tightness bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * (mean_residual / bin_capacity as f64).clamp(0.0, 1.5);

    // Time horizon: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * tightness * progress;

    // Slight preference for fuller bins when many bins are open.
    score -= 0.3 * tightness * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, non-linearly penalized
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let prog_sq = progress * progress;
    let prog_mix = progress * norm_pr;
    score += 30.0 * norm_pr * prog_sq;            // dead space hurts more later
    score -= 20.0 * norm_pr * (1.0 - prog_sq);    // slack tolerated early

    // Dead-space cliff: very small post-residuals are unusable
    let small = ((cap * 0.15 - pr) / cap).max(0.0);
    score += 25.0 * small * small * (0.5 + progress);

    // Lookahead: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        score -= 15.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Mild penalty relative to mean residual (avoid wasting full bins)
    score += 0.1 * (mean_residual - pr);

    // New-bin candidate calibration: empty bin should be neutral-to-slightly-worse
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space after placement.
    // Small post-residuals in "good" classes are prime candidates.
    let capacity = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits, penalize waste nonlinearly.
    let frac = pr / capacity;
    score += 12.0 * frac * frac;

    // Harmonic classes via integer division on post_residual:
    // class 0: post_residual == 0 (perfect closure) -> strong reward
    // class 1: 0 < post_residual <= 10 (nearly closed) -> reward
    // class 2: 10 < post_residual <= 25 (usable for small items) -> mild reward
    // class 3: 25 < post_residual <= 50 (medium) -> neutral
    // class 4: post_residual > 50 (large leftover) -> penalize slightly
    let class: u32 = if post_residual == 0 {
        0
    } else if post_residual <= 10 {
        1
    } else if post_residual <= 25 {
        2
    } else if post_residual <= 50 {
        3
    } else {
        4
    };
    score -= match class {
        0 => 25.0,
        1 => 12.0,
        2 => 4.0,
        3 => 0.0,
        _ => 3.0,
    };

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are more reusable.
    let mod_bonus: f64 = if post_residual % 10 == 0 {
        6.0
    } else if post_residual % 5 == 0 {
        3.0
    } else {
        0.0
    };
    score -= mod_bonus;

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score += gap * 0.3;
        } else {
            // Next item cannot fit here; leftover risk grows with how far off.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.1;
        }
    } else {
        // Last item: closure is everything.
        score -= 8.0 * (1.0 - frac);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening fresh bins unless the item is huge
    // relative to mean residual (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / capacity;
        let mean_gap = (mean_residual - item_size as f64).max(0.0) / capacity;
        // Open a new bin when mean residual is small (nothing fits well)
        // or when pressure is high (item dominates).
        score = 40.0 - 30.0 * mean_gap - 10.0 * pressure;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for bins with residuals close to the mean (balance load),
    // keeping some bins tight for future large items.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Stream-phase modulation: early on, allow slack; late, force tightness.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * frac * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // General dead-space curve: small post_residual relative to capacity is bad.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = pr / cap;
    score += (1.0 - frac).powi(6) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits (item fills most of the bin).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 25.0;

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item would be blocked by post_residual, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Prefer bins with lower residual (best-fit style) among open bins.
    score += (bin_residual as f64 - item_size as f64) * 0.3;

    // Slight preference for opening new bins late in the stream is avoided;
    // early stream: allow new bins more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly so it's chosen only when fits are bad.
        score += 18.0 * (1.0 - progress);
    }

    // Mean residual coupling: if bin residual far below mean, it's a good squeeze.
    score -= (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect chain: post_residual == next_item_size -> strong reward.
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item does not fit here: penalize proportional to overshoot.
        let over = (next_item_size - post_residual) as f64;
        score += 0.8 * over;
    }

    // Reward leaving small dead space relative to capacity.
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    score += 0.3 * post; // prefer tight fits generally

    // Penalize creating residuals too small to be useful for typical items (1..100 range).
    if post > 0.0 && post < 10.0 {
        score += 50.0; // dead space zone
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when nothing fits well; penalize opening
    // new bins while open bins can host the item, scaled by stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let can_fit_elsewhere = fitting_bins_count > 0;
        if can_fit_elsewhere {
            score += 80.0 + 40.0 * progress;
        } else {
            score -= 10.0;
        }
        // Early stream: opening bins is cheap-ish; late stream: consolidate.
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty for very full bins that still leave a usable gap but block flexibility.
    if post > 10.0 && post < 25.0 && next_item_size > 0 && next_item_size > post {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 2.5 * tightness * tightness * (bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count == 2 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Dead space that the next item cannot use.
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Penalize bins whose residual deviates far below the mean (fragmented bins),
    // unless it's a fresh bin candidate.
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev.abs();
    } else {
        // New bin: base cost of opening it, modulated by stream progress and load.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 30.0 * progress;

        // If few bins fit the item, opening a new bin is less attractive.
        if fitting_bins_count <= 2 {
            score += 60.0;
        }
        // If mean residual is large (plenty of slack overall), avoid new bins.
        score += 0.4 * mean_residual;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Mild penalty for accumulating many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear penalty growth.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress: early on, waste matters less;
    // late in the stream, compact placements are rewarded more aggressively.
    let progress_coupling = 1.0 + 1.2 * progress * progress + 0.8 * progress * norm_pr;
    score *= progress_coupling;

    // Reward tight fits smoothly: quadratic bonus when post_residual is tiny.
    let tightness = (1.0 - norm_pr).clamp(0.0, 1.0);
    score -= 6.0 * tightness * tightness * tightness;

    // Penalize dead space that can't fit the next item (smooth logistic-like term).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        let unusable = gap / cap;
        score += 4.0 * unusable * unusable / (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Mild penalty when many bins are open relative to stream progress (encourage consolidation).
    let open_norm = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 0.3 * open_norm * (1.0 - progress);

    // Slight preference for bins whose residual is near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.5 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual mod 10 buckets.
    // Small dead space (< 10) is unusable for any item -> penalize heavily.
    let cls = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space class
    }
    score -= (cls as f64) * 0.7; // prefer residuals landing on nice class boundaries

    // Integer-division thresholds: how many "average items" still fit
    let fits_count = post_residual / 10;
    score -= (fits_count as f64) * 2.0;

    // Lookahead coupling: does next item fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chain a perfect fit
        } else if next_item_size <= post_residual {
            score -= 30.0 + (post_residual - next_item_size) as f64 * -0.2;
        } else {
            score += 15.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when existing bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // penalize opening new bins when open bins have usable mean residual
        score += 80.0 + fragmentation * 150.0 - progress * 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Mild preference for filling already-open bins as stream progresses
    score -= (step_index as f64 / total_items.max(1) as f64) * 5.0;
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward very tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage consolidation.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    score += 8.0 * pressure;

    // Prefer bins whose residual is below the mean (tighter bins first).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual as f64);
        } else {
            // Next item can't fit in the leftover gap: penalize proportional dead space.
            score += 0.4 * post_residual as f64;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { fitting_bins_count as f64 };
        score += 15.0 + 12.0 * desperation;
        if item_size >= bin_capacity / 2 {
            score -= 20.0; // large items are fine to start a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.19;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: low post_residual is already good, amplify near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize dead space relative to bin fill fraction (waste shaping).
    let fill = 1.0 - post / cap;
    score -= 12.0 * fill * fill;

    // Lookahead: if next item fits in post_residual, reward this placement strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 20.0 + 0.3 * nxt;
        } else {
            // Penalize leaving a gap just smaller than the next item (unusable sliver).
            let gap = post - nxt;
            if gap < 10.0 && gap >= 0.0 {
                score += 6.0 + gap;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer bins that are already well-filled.
        let rel = bin_residual as f64 / cap;
        score += 10.0 * (1.0 - rel);
    }

    // Global state: many open bins -> consolidate into existing ones.
    let pressure = open_bins_count as f64;
    score += 0.5 * pressure * (post / cap);

    // Mean residual coupling: if mean residual is small, protect remaining space.
    score += 0.15 * (mean_residual - post).abs();

    // Time horizon: late in stream, be conservative; early, allow exploration of new bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * t * (post / cap);

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && item_size <= bin_capacity;
    if is_new_bin {
        let exploration = (1.0 - t) * 25.0;
        score = 40.0 + exploration - 0.2 * pressure;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping of post_residual.
    let mut score = post
        - 12.0 * (1.0 - x) * (1.0 - x)      // reward near-full fills
        + 8.0 * x * x * (2.0 - x);          // penalize large leftover space smoothly

    // Stream-progress coupling: later in the stream, dead space matters more.
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += (1.0 - progress) * 6.0 * x * x;
    score -= progress_coupling * 4.0 * (1.0 - x);

    // Mean-residual interaction: if this bin's post-residual deviates from the
    // fleet mean, penalize imbalance (smooth quadratic deviation).
    let dev = post - mean_residual;
    score += 0.05 * dev * dev / (1.0 + progress);

    // Lookahead: bonus if the next item could use the post-residual.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 5.0 * (1.0 - (next_item_size as f64 - post).abs() / cap);
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - x);
    }

    // New-bin candidate: mild penalty so we only open new bins when it's genuinely better.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    // Slight penalty for too many open bins relative to progress.
    score += (open_bins_count as f64).ln() * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes capture "usable slivers"
    let post = post_residual as i64;
    let cap = bin_capacity as f64;

    // Dead-space penalty: residuals that no typical item (1..=100) can pair with
    // are worse than residuals that remain usable. Classify via integer division.
    let usable = if post == 0 { 1.0 } else if post >= 10 { 1.0 } else { 0.35 };
    score += (1.0 - usable) * 25.0;

    // Harmonic bonus: post_residual exactly matching common item size classes
    // (10,20,...,80) means the leftover is reusable -> reward.
    if post > 0 && post % 10 == 0 {
        score -= 6.0 + (post as f64).min(50.0) * 0.08;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as i64;
        if nx == post {
            score -= 30.0;
        } else if nx < post {
            // partial fit quality: how much of the leftover the next item consumes
            let fill = nx as f64 / post as f64;
            score -= fill * 12.0;
            // harmonic alignment: next item leaves another round residual
            if (post - nx) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item cannot use this leftover at all
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // mild preference to spread load when many bins fit
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in stream: keep bins flexible; late: accept tighter fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post as f64) * 0.15;

    // New-bin candidate handling: only open a new bin if no open bin fits well
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        // penalty grows with number of bins that could fit the item
        score += 15.0 + (fitting_bins_count as f64) * 8.0;
        // if item is large relative to capacity, opening fresh bin is fine
        if item_size as f64 > 0.6 * cap {
            score -= 10.0;
        }
        // if mean residual is already low (bins nearly full), new bin reasonable
        if mean_residual < 15.0 {
            score -= 12.0;
        }
    }

    // Tiny exact-fill reward
    if post == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 {
        let next_s = if next_item_size == 0 { 0 } else { next_item_size };
        // Dead space: residual too small for the next item or too small to matter.
        if next_s > 0 && post_residual < next_s {
            score += 18.0 * (1.0 - post_residual as f64 / next_s.max(1) as f64);
        }
        if post_residual < 10 {
            score += 25.0; // tiny unusable gap
        }
        // Reward residual that exactly fits the next item.
        if next_s > 0 && post_residual == next_s {
            score -= 20.0;
        }
    } else {
        score -= 30.0; // perfect fit
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.6 + 0.8 * progress);
    if bin_residual == bin_capacity {
        score += 10.0 + pressure * 0.5; // penalize new-bin candidate
    } else {
        score -= pressure * 0.15;
    }

    // Prefer bins tighter than the mean residual (best-fit coupling).
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits in post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.05 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (perfect chain placement).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap);
        // Bonus if the next item fits EXACTLY after this placement.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving dead space the next item cannot use.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are preferred,
    // bins looser than the mean get penalized proportionally.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance pressure: if this is the only fitting bin, strongly favor
    // using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // expensive unless the current bin would leave large unusable waste.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Opening a new bin is cheaper when many bins are already open
        // (fragmentation already exists) — mild discount.
        score -= (open_bins_count.min(20) as f64) * 0.5;
        // If next item is huge, an empty bin gives full flexibility.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Early in the stream, be slightly more willing to open fresh bins
    // to build a good structure; later, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    // Penalize very small post-residuals (unusable slivers) unless exact fit.
    if post_residual > 0 && post_residual < 10 && post_residual != next_item_size {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // Penalize leaving dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }
    if post_residual >= 10 && post_residual < 25 {
        score -= 3.0; // usable small pocket
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // exact chain fit is excellent
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            score += 4.0; // next item won't chain here
        }
    }

    // Time horizon: early in stream, be more conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 {
        let fill_pressure = mean_residual / bin_capacity as f64;
        score += fill_pressure * 4.0;
    }

    // New-bin candidate handling: empty bin is a fallback; penalize unless current bin fits poorly.
    if bin_residual == bin_capacity {
        // Opening a new bin is reasonable when item is large and fits nothing well,
        // or when no open bin exists / this is a poor fit overall.
        if item_size > bin_capacity / 2 || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 20.0; // prefer existing bins for small/medium items
        }
        // Late in stream with many bins, avoid proliferation.
        if progress > 0.7 && open_bins_count > 5 {
            score += 10.0;
        }
    }

    // Mild preference for bins with residual close to item (perfect wrapping).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 40.0 * norm_pr * norm_pr * (1.0 + progress);
    score -= 25.0 * norm_pr * (1.0 - progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 15.0 + 0.3 * ((next_item_size as f64) - pr);
    } else if next_item_size > 0 {
        score -= 8.0 * (1.0 - ((next_item_size as f64) - pr).abs() / cap);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer tighter-than-average fits via smooth coupling
    score += 0.5 * (mean_residual - pr);

    // Mild pressure to consolidate as stream progresses
    score += progress * open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic classes: post_residual buckets via integer division on capacity fractions
    let class = post_residual / 10; // 0..10 dead-space class
    score += match class {
        0 => -60.0,          // perfect fit (post 0-9): strongly reward
        1 => -20.0,          // near-perfect
        2 | 3 => 10.0,       // awkward sliver class (20-39)
        4 | 5 => 0.0,        // mid range, still useful
        6 | 7 => 8.0,        // 60-79
        _ => 15.0,           // large leftover, wasteful
    };

    // Modulo arithmetic: residuals that pair with common item sizes are valuable
    let m = post_residual % 10;
    if m == 0 { score -= 12.0; }                 // round residual fits many sizes
    else if post_residual >= 10 && post_residual <= 80 {
        // residual exactly matches typical item magnitudes -> likely reusable
        if next_item_size as u32 == post_residual { score -= 40.0; }
        if next_item_size > 0 && next_item_size <= post_residual { score -= 8.0; }
    }

    // Penalize if next item cannot fit here (will need another bin anyway)
    if next_item_size > post_residual { score += 6.0; }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 { score -= 35.0; }

    // New-bin candidate: only attractive when current bins fit poorly or many bins open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else {
            (post - mean_residual).abs()
        };
        // opening a new bin is fine when few bins are open or fit is bad
        score = 25.0 + open_bins_count as f64 * 4.0 - poor_fit * 0.3 - progress * 10.0;
        if next_item_size > 0 && next_item_size >= 70 { score -= 15.0; }
        if item_size >= 60 { score -= 10.0; }
    }

    // Tie-break toward filling mean_residual gap
    score += (post - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits (perfect fills preferred).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + (post_residual - next_item_size) as f64;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // but for the new-bin candidate (residual == capacity) apply opposite pull.
    let pressure = (open_bins_count as f64).ln().max(1.0) * 5.0;
    if bin_residual == bin_capacity {
        score += pressure + 40.0;
    } else {
        score -= pressure * 0.5;
    }

    // Penalize leaving residual far from mean residual (fragmentation risk).
    score += ((post_residual as f64) - mean_residual).abs() * 0.3;

    // Mild stream-progression weighting: later in stream, conserve bins more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual exactly equals next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Exact match bonus.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize dead space the next item can never use.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: just minimize waste.
        score -= 20.0;
    }

    // Reward tight fits relative to mean residual of open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid proliferation of bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins already fit, unless it's the only option.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 55.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
    }

    // General tightness reward.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post / cap; // normalized post residual
    let pr2 = pr * pr;
    let pr3 = pr2 * pr;
    let pr4 = pr3 * pr;

    // Base: post residual, with smooth non-linear shaping (favor tight fits,
    // penalize mid-range dead space quadratically/cubically).
    let mut score = post as f64
        - 18.0 * pr2
        + 22.0 * pr3
        - 10.0 * pr4;

    // Smooth interaction of post residual with stream progress:
    // early on, tolerate looser fits; late in stream, demand tight fits.
    let prog_coupling = 14.0 * pr * (1.0 - progress) - 20.0 * pr2 * progress;
    score += prog_coupling;

    // Last-chance bonus: smooth polynomial in fitting_bins_count.
    let fbc = fitting_bins_count as f64;
    let last_chance = 1.0 / (fbc * fbc);
    score -= 12.0 * last_chance;

    // Lookahead: reward if next item fits in post residual (smooth bump).
    if next_item_size > 0 {
        let fits = (post_residual as f64 - next_item_size as f64).max(0.0) / cap;
        score -= 10.0 * (1.0 - fits) * (fits > 0.0 || post_residual as f64 >= next_item_size as f64) as i32 as f64;
        let gap = ((post_residual as i64 - next_item_size as i64).unsigned_abs()) as f64;
        score += 0.08 * gap;
    }

    // Slight preference to spread load when many bins open (smooth in open_bins_count).
    let obc = open_bins_count as f64;
    score -= 2.0 * obc / (obc + 4.0);

    // Mean residual coupling: bins far from the mean get a smooth nudge toward balance.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "useful" size classes (divisible into small chunks) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: classify post_residual by its residue modulo 10.
    // Residues near 0 mean the leftover can host small items cleanly.
    let residue = post_residual % 10;
    score -= match residue {
        0 => 40.0,
        1 | 9 => 2.0,
        2 | 8 => 1.0,
        5 => 5.0,
        _ => 0.0,
    };

    // Integer-division threshold: leftover must be >= next item to matter.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward leaving space exactly usable by the lookahead item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
            if post_residual == next_item_size {
                score -= 30.0; // lookahead perfect fit
            }
        } else {
            // Dead space relative to the lookahead item: penalize proportionally.
            score += 15.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Fractional capacity coupling: tightness of the fill.
    let fill = 1.0 - pr / cap;
    score -= 25.0 * fill * fill;

    // Penalize opening new bins when many bins already have room.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if nothing else fits, new bin is the only option anyway.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (pr / cap);

    // Deviation from mean residual: prefer bins close to (or below) the mean,
    // which tends to balance residual classes.
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Moderate residual: mildly prefer smaller leftovers (already in base).
        score -= (post_residual as f64).sqrt() * 2.0;
    }

    // Reward using existing bins vs. opening new ones: pressure proportional to open bins.
    if bin_residual < bin_capacity {
        // Existing bin: reward more when many bins are open.
        score -= 3.0 + open_bins_count as f64 * 1.5;
    } else {
        // Brand-new empty bin candidate: penalize when few bins open, less when many.
        score += 8.0 + (20.0_f64.min(open_bins_count as f64 * 2.0));
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use leftover: dead space likely, penalize.
        score += 10.0;
    }

    // Late in the stream: consolidate more aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 6.0;
    }

    // Prefer bins whose residual is close to what we fill (tight packing signal).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    // Slight preference for bins below mean residual (fill emptier bins less,
    // keep balanced residuals for future items).
    if bin_residual as f64 > mean_residual && bin_residual < bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack = leftover after hypothetically placing the next item too.
            let slack = (post_residual - next_item_size) as f64;
            // Tighter chain (smaller slack) is better; reward tight chains strongly.
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            // Extra reward if the next item fits nearly perfectly.
            if slack <= 5.0 {
                score -= 30.0;
            }
        } else {
            // Post-residual too small for next item: penalize dead space,
            // especially when the leftover is tiny (unusable).
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 25.0 * (1.0 - dead / 10.0);
            } else {
                score += 5.0;
            }
        }
    }

    // Compare against mean residual: prefer bins that are already relatively
    // full (small residual) to consolidate waste into few bins.
    let residual = bin_residual as f64;
    if residual < mean_residual {
        score -= (mean_residual - residual) * 0.3;
    } else {
        score += (residual - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate (empty bin): penalize mildly so we prefer reusing
    // open bins unless their scores are bad; but if many open bins exist
    // and this item is large, opening fresh space may help future items.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 20.0;
        // More open bins -> slightly more willing to open another (spread load).
        let crowding = (open_bins_count as f64).ln().max(0.0) * 4.0;
        score += base + crowding - 15.0 * progress;
        // Large items leave little post_residual anywhere; new bin is fine.
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mild tie-break: prefer bins with tighter current fit.
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: post_residual dominates, add superlinear penalty.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize post residuals that are too small to be useful later
    // (dead space below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this bin heavily (perfect pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits, but wastefully: mild penalty proportional to waste
            score += 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item will not fit here: slight penalty if it leaves awkward residue
            score += 0.3 * (post_residual as f64).min(next_item_size as f64) * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // When many bins are open, prefer consolidation into fullest bins;
    // when few are open, allow more freedom.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += 0.15 * pressure * (post_residual as f64);

    // Compare residual to the mean: prefer bins below-mean residual
    // (i.e., fuller than average) to balance toward closing bins out.
    if bin_residual as f64 > mean_residual {
        score += 0.4 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: early in the stream, be conservative (slight preference for
    // good fits); late in the stream, prioritize closing bins out entirely.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // New-bin candidate: make opening a new bin moderately attractive only when
    // the item is large relative to capacity and fits are poor; otherwise the
    // base score (residual = capacity) keeps it unattractive.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity as f64;
        // encourage new bin for large items when few bins fit the item
        score -= 8.0 * item_ratio * (fitting_bins_count as f64).powi(2);
        // discourage new bins late in the stream
        score += 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + 0.8 * t - 1.2 * t * t + 0.6 * t * t * t;
    score *= poly;

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tight = (1.0 - pr / cap).powi(3);
    score -= 12.0 * tight * (0.5 + t);

    // Penalize dead space relative to mean residual across open bins
    let dead = (pr - mean_residual) / cap;
    score += 6.0 * dead * dead;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for many open bins, encouraging consolidation
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize slightly so it's chosen only when fits are bad
    if (bin_residual as f64 - cap).abs() < 1e-6 {
        score += 20.0 - 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap;

    // Reward placements that land the residual in "usable" harmonic bands.
    // Usable bands: residual >= 25 (fits a small item) get progressively rewarded.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, best possible
    } else if post_residual >= 50 {
        score -= 18.0; // still half-capacity usable
    } else if post_residual >= 25 {
        score -= 8.0;  // quarter-band usable
    } else if post_residual >= 10 {
        score += 6.0;  // narrow band, only tiny items fit
    } else {
        score += 20.0; // dead space < 10 essentially unusable
    }

    // Integer-division thresholds on post_residual (harmonic classes of 12/13).
    let harmonic_class = post_residual / 13;
    score -= harmonic_class as f64 * 2.5;

    // Modulo arithmetic: residuals that are multiples of common item sizes are attractive.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly: strong reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: penalize by the overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += open_bins_count as f64 * 0.4;

    // Penalize creating residual far above the mean (wasted spread) mildly.
    score += 0.15 * (post - mean_residual).max(0.0);

    // Progress factor: late in stream, tighter packing matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A residual is "dead" if it's too small for the smallest plausible item.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0;
    }

    // Non-linear penalty: small but usable residuals are still risky.
    // Penalize residuals below half capacity disproportionately.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < bin_capacity as f64 / 2.0 {
        score += (bin_capacity as f64 / 2.0 - pr) * 0.8;
    }

    // Reward near-perfect fits strongly.
    if pr == 0 {
        score -= 50.0;
    } else if pr <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.1;
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize slightly to prefer bins
        // that keep a chain going.
        score += 5.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // over opening new bins (new bin candidate has residual == capacity).
    let openness = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New bin: penalize more as open bins grow; also penalize when
        // other bins can fit the item.
        score += openness * 2.0 + (fitting_bins_count as f64) * 3.0;
        // But late in the stream with a big item, a fresh bin may be fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    } else {
        // Existing bin: reward filling it, especially if it's the last
        // fitting bin (last chance before opening a new bin).
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Reward bins tighter than the mean residual (well-utilized bins).
        score -= (mean_residual - bin_residual as f64) * 0.05;
    }

    // Progression: slightly prefer tighter packing as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness;

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: waste only what next item leaves behind
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_waste / (bin_capacity as f64));
        } else {
            // Next item won't fit here: penalize proportionally to unusable gap
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0 * (gap / 100.0);
        }
    }

    // Compare post_residual against mean residual: avoid making a bin much
    // tighter/looser than the fleet average unless it's a very tight fit
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when item is large and no open bin
    // offers a good fit; otherwise penalize opening new bins
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let poor_fit_elsewhere = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score += 45.0 - 30.0 * large_item * poor_fit_elsewhere;
        // Later in the stream, slightly prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 && next_item_size <= post_residual {
        let perfect = (post_residual as f64 - next_item_size as f64).abs();
        score -= 18.0 * (1.0 - perfect / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; mild penalty for leaving awkward gap
        score += 5.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: only one bin fits the item, prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Fragmentation pressure: penalize spreading when many bins open
    let pressure = open_bins_count as f64 / (mean_residual + 1.0);
    score += 0.05 * pressure;

    // Time horizon: early in stream, prefer opening new bins (keep flexibility);
    // late in stream, consolidate to avoid opening near-empty bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 20.0 + 40.0 * progress;
        // Opening a new bin early is fine if item is large
        score -= (item_size as f64 / bin_capacity as f64) * 15.0 * (1.0 - progress);
    } else {
        // Using existing bins is favored late
        score -= 10.0 * progress;
    }

    // Prefer bins whose residual is above mean (keep balanced bins available)
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize wasted residual, with non-linear (quadratic) waste penalty.
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth stream-progress coupling: waste matters more as stream progresses.
    score *= 1.0 + 0.8 * progress * norm_pr;

    // Lookahead: reward if next item fits the post-residual (chaining placements).
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 12.0 * fit_quality * (1.0 + progress);
    }

    // Penalize leaving residual that nothing in [1,100] range can exploit well
    // (smooth trough penalty around mid residuals).
    score += 6.0 * (norm_pr * std::f64::consts::PI).sin().abs();

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is costly, but attractive when
    // open bins are all poor fits (item barely fits) or many bins are open.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_residual as f64;
        score += 15.0 - 10.0 * tightness;
        score += 2.0 * open_bins_count as f64;
        // Late in the stream, prefer filling existing bins even imperfectly.
        score += 20.0 * progress;
    } else {
        // Slight preference for bins already below mean residual (balancing).
        score += 3.0 * ((pr - mean_residual) / cap).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction classes (1/4, 1/3, 1/2, >1/2)
    let item_class = if item_size > bin_capacity / 2 { 3 }
        else if item_size > bin_capacity / 3 { 2 }
        else if item_size > bin_capacity / 4 { 1 }
        else { 0 };

    // Class of the residual gap this placement would leave
    let gap_class = if post_residual > bin_capacity / 2 { 3 }
        else if post_residual > bin_capacity / 3 { 2 }
        else if post_residual > bin_capacity / 4 { 1 }
        else { 0 };

    // Penalize gaps that can only host the smallest class of future items
    score += match gap_class {
        3 => 0.0,
        2 => 2.0,
        1 => 5.0,
        _ => {
            if post_residual == 0 { -6.0 }  // perfect fill: reward strongly
            else { 9.0 }                     // tiny dead space: heavily penalize
        }
    };

    // Big items (class 3) should go into bins where they nearly fill: reward tight fits
    if item_class == 3 {
        score -= (item_size - bin_capacity / 2) as f64 * 0.15;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            // Harmonic compatibility: next item leaves a further useful gap
            let next_post = post_residual - next_item_size;
            if next_post <= bin_capacity / 4 {
                score -= 3.0;
            } else {
                score -= 1.0;
            }
        } else {
            // next item cannot use this gap: penalize proportional to wasted potential
            score += (next_item_size - post_residual).min(20) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: prefer existing bins unless residual is huge and mean is low
    if bin_residual == bin_capacity {
        // brand-new bin: baseline penalty so it's only chosen when open bins are bad
        score += 15.0;
        // early stream: opening bins is fine (diversification)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.2 {
            score -= 8.0;
        }
        // if open bins are mostly full (low mean residual), new bin is attractive
        if mean_residual < (bin_capacity as f64) * 0.15 {
            score -= 10.0;
        }
        // large current item: opening fresh bin avoids fragmentation
        if item_class == 3 {
            score -= 6.0;
        }
    } else {
        // favor bins tighter than the current mean residual (best-fit bias)
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    // Modulo arithmetic on post_residual: gaps divisible by small item classes are reusable
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 2.0;
    }
    if post_residual > 0 && post_residual % 3 == 0 {
        score -= 1.0;
    }

    // Slight penalty per open bin to encourage consolidation when roughly equal
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: gaps too small for the minimum item (1..=10)
    // are unusable -> they are pure waste. Penalize quadratically.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }

    // Small-but-usable gaps (11..=20) are risky: only next_item_size <= gap
    // can use them. Reward when the lookahead fits, punish otherwise.
    if post_residual >= 11 && post_residual <= 20 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 25.0;
        }
    }

    // Reward lookahead synergy: post gap exactly usable by next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Perfect fit: close the bin completely.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer
    // filling existing bins and discourage opening new ones.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate handling: empty bin has residual == capacity.
    // Only attractive when the item is huge (poor fit anywhere else)
    // or no open bin fits; otherwise push it above open-bin choices.
    if bin_residual == bin_capacity {
        let huge = item_size >= 80;
        let no_fitters = fitting_bins_count == 0;
        if huge || no_fitters {
            score -= 45.0;
        } else {
            score += 30.0 + 0.3 * open_bins_count as f64;
        }
    }

    // Mean-residual coupling: if open bins are mostly empty on average,
    // prefer consolidating into bins with below-mean residual (tight bins).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Late in the stream, waste matters less than finishing cleanly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item can also fit here afterwards: mild reward proportional to tightness.
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit the leftover: penalize dead space severity.
            score += 80.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate logic: an empty bin is only attractive when the fit is poor
    // (large dead space would be created) or late in the stream with few alternatives.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let poor_fit_penalty = 200.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        score = waste + poor_fit_penalty;
        if fitting_bins_count == 1 {
            score += 150.0; // keep using the last open bin instead
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 100.0; // new bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: small post-residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward bins whose leftover can host the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the next item.
        score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many fitting bins: mild penalty to keep diversity of residual sizes.
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 2.0;
    }

    // Prefer bins with residual far below the mean (consolidate small leftovers elsewhere).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Time horizon: early on, be more willing to open bins (raise new-bin appeal later
    // by penalizing near-full bins less as the stream progresses).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 12.0 + 0.5 * open_bins_count as f64;
        // But allow new bin early in the stream for flexibility.
        score -= (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial coupling to stream progress.
    // Early on, prefer tight fills (small post_residual); later, residual matters less.
    let mut score = pr * (1.0 - 0.35 * progress) + 30.0 * norm_pr * norm_pr * (1.0 - progress);

    // Dead-space penalty: strongly penalize residuals that become unusable
    // (smaller than the smallest plausible item), smoothly scaled.
    let dead = (1.0 - (pr / 10.0).min(1.0)) * (pr / cap);
    score += 45.0 * dead * dead;

    // Perfect-fit reward: near-zero post residual is highly desirable.
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - norm_pr);
    }

    // Lookahead coupling: reward bins whose post-residual can still fit the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 12.0 * (1.0 - (pr - n) / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 8.0 * (n - pr) / cap;
        }
    }

    // Mild dispersion pressure: prefer bins near the mean residual to keep options open.
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: slight default penalty so it is chosen only when it wins outright,
    // with the penalty easing as the stream progresses (late stream tolerates new bins).
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify dead space into residue classes.
    // Residuals that are "harmonic" with typical item sizes (multiples of 5/10/20)
    // are more reusable than awkward ones.
    let pr = post_residual;
    let harmonic = if pr == 0 {
        3.0 // perfect fit - best possible
    } else if pr % 20 == 0 {
        2.0
    } else if pr % 10 == 0 {
        1.5
    } else if pr % 5 == 0 {
        1.0
    } else {
        0.0
    };
    score -= 6.0 * harmonic;

    // Dead-space penalty: small awkward leftovers (< 10) are worthless.
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // next item fits: better if leftover is tight around it
            let slack = (pr - next_item_size) as f64;
            score -= 10.0;
            score += slack * 0.15;
            // exact chaining (post == next) is ideal
            if pr == next_item_size {
                score -= 12.0;
            }
        } else {
            // next item won't fit here: penalize, worse if gap is small (wasted)
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: it is "free" residual-wise; only open a new bin when
    // existing bins would create bad leftovers. Penalize new bins mildly,
    // more when many bins are already open or stream is late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 30.0 * progress + 0.5 * open_bins_count as f64;
        // but if mean residual is large, existing bins are roomy anyway
        score -= 0.1 * mean_residual;
    }

    // Prefer filling bins that are already relatively full (small residual).
    score += 0.05 * bin_residual as f64;

    // Integer-division threshold: bins where item occupies a large fraction
    // of residual get a bonus.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    if fill_frac > 0.75 {
        score -= 8.0;
    } else if fill_frac < 0.25 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // future item are "dead space". Penalize them extra.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 5.0; // up to +55 for residual 1
    }

