    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 12.0; // creates dead space for the known next item
        }
    }

    // Last-chance bin: if only one open bin fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 25.0;
    }

    // Open-bins pressure: mildly discourage spreading across many bins,
    // encouraging consolidation into existing bins.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: only attractive when the item is large relative to
    // any residual or when open bins are very full on average.
    if bin_residual == bin_capacity {
        let mean_tightness = mean_residual / bin_capacity as f64;
        // Penalize opening new bins unless existing bins are nearly full.
        score += 40.0 + mean_tightness * 20.0;
        if item_size >= 60 {
            score -= 20.0; // large items may justify a fresh bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large items sequentially in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
