    // New-bin candidate: keep it attractive only when current fits are bad.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin early in the stream or when many bins are open.
        score += 20.0 + 3.0 * open_bins_count as f64;
        if next_item_size > 0 && item_size >= next_item_size {
            // Large current item with a smaller next item: new bin could host both later — mild discount.
            score -= 10.0;
        }
    }

    // Slight preference for filling bins more completely as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space: tiny residuals unlikely to be usable later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize proportionally to wasted gap.
            score += (next_item_size as f64 - post_residual as f64) * 0.25;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (score new-bin candidate lower); late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 30.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score -= new_bin_bias;
    } else {
        score += new_bin_bias * 0.15;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
        score += pressure * 2.0;
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor),
    // scaled by how many alternatives exist.
    let fit_gap = (bin_residual as f64 - item_size as f64).max(0.0);
    score += fit_gap * (0.1 + 0.05 * fitting_bins_count as f64);

    // Mild penalty for very full bins late in stream to keep flexibility.
    if progress > 0.7 && post_residual < 5 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Core: penalize leftover space quadratically (dead space is bad).
    let mut score = post + 0.9 * (post * post) / cap;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - post / (item_size.max(1) as f64 + post);
    score -= 12.0 * tightness;

    // Stream-progress coupling: later in the stream, waste matters more,
    // so amplify the quadratic penalty smoothly with progress.
    score += 6.0 * progress * (post / cap) * (post / cap) * cap * 0.1;

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit here; slight penalty for stranding space.
            score += 3.0 * (post / cap);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise a new bin gets opened and this residual is stranded.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral baseline with mild early-stream openness,
    // discourage opening new bins when many open bins exist (fragmentation).
    if bin_residual == bin_capacity {
        score = cap * 0.75 + 2.0 * open_bins_count as f64 + 10.0 * progress;
        if fitting_bins_count == 1 {
            // Even a fresh bin shouldn't beat the sole fitting bin unless
            // the fit there is terrible.
            score += 25.0;
        }
    }

    // Mild mean-residual context: prefer bins whose residual deviates
    // favorably (small residual = well-filled bin gets priority).
    score += 0.05 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into residue classes modulo 10
    let pr = post_residual;
    let class = pr % 10;
    // Dead space classes: residuals 1..9 (non-multiples of 10) are harder to fill
    if class != 0 && pr > 0 {
        // penalty grows as residual gets small and awkward
        score += (10 - class) as f64 * 0.7;
    }
    // Perfect-fit classes: post_residual exactly 0 is ideal
    if pr == 0 {
        score -= 60.0;
    }
    // Harmonic thresholds: post_residual in {10,20,25,50} are "fillable" classes
    match pr {
        0 => { score -= 10.0; }
        10 | 20 | 25 | 50 => { score -= 25.0; }
        _ => {}
    }

    // Integer-division threshold: big chunks of residual are valuable
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if pr >= half {
        score -= 20.0; // bin still half full after placement: good density
    } else if pr >= quarter {
        score -= 8.0;
    } else if pr > 0 {
        score += 5.0; // small awkward remainder
    }

    // Lookahead coupling: harmonic class of next item vs post_residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly into a harmonic class of post_residual
            if pr % 10 == 0 && next_item_size % 10 == 0 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
            // exact match of next item to post residual
            if next_item_size == pr {
                score -= 30.0;
            }
        } else {
            // next item won't fit here; penalize more if this bin was our only option
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bin fit is terrible
    if bin_residual == bin_capacity {
        let density_pressure = (mean_residual / cap).max(0.0);
        if post_residual > 0 && post_residual < quarter {
            score += 30.0; // don't open new bin for tiny item remnants logic handled elsewhere
        }
        score -= density_pressure * 15.0;
        // early stream: opening bins is cheap and useful
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // many open bins with high mean residual: prefer filling them
        if open_bins_count > 3 && mean_residual > cap * 0.4 {
            score += 25.0;
        }
    }

    // Mild penalty for spreading across too many bins
    if open_bins_count as f64 > (step_index as f64).max(1.0) * 0.8 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no typical item can use
    // are dead weight. Penalize small gaps super-linearly.
    if post_residual > 0 {
        // gap below minimum plausible item size is pure dead space
        let dead = (post_residual as f64 / 10.0).powi(2) * 12.0;
        score += dead;
        // unusable-for-next-item gap is even worse
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 3.0;
        }
    } else {
        // perfect fill: strong reward
        score -= 40.0;
    }

    // Reward tight fits (small waste relative to item size)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Last-chance bin: using it avoids opening a new bin -> strong reward
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than opening new ones; also mild penalty scaled by count.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin has no dead space yet, but we
    // only want it when existing fits are poor. Penalize the empty bin more
    // when many bins are open and mean residual is large.
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.4 + open_bins_count as f64 * 2.0;
        // but late in the stream, opening a fresh bin is cheap-ish
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 8.0;
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // a bin with less residual than average is closer to being closed out.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.8;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect match => strong bonus; decays quadratically with gap.
            score -= 60.0 * (1.0 - gap / bin_capacity as f64).powi(2);
        } else {
            // Next item doesn't fit: penalize proportionally to the shortfall,
            // worse if this bin was the only fitting option.
            let shortfall = (next_item_size - post_residual) as f64;
            let last_chance = if fitting_bins_count == 1 { 2.0 } else { 1.0 };
            score += 0.5 * shortfall * last_chance;
        }
    } else {
        // Last item: minimize dead space directly.
        score += 0.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably
    // from the mean residual (tighter bins get preference for big items).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize tiny unusable dead space (< 10) unless next item uses it.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Early in stream: be more conservative about filling bins tightly
    // (keep flexibility), later: pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make empty bin slightly unattractive unless residuals
    // are all tight (mean residual low means open bins are nearly full).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 15.0 * (1.0 - pressure);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 {
        let dead = post_residual as f64;
        if next_item_size > 0 && (next_item_size as f64) > dead {
            score += 0.35 * (next_item_size as f64 - dead);
        } else {
            score -= 0.15 * dead;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins with residual below mean (fill fuller bins first)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        let waste = bin_residual as f64 - item_size as f64;
        score += 60.0 - 0.4 * waste;
        // Late in stream, opening new bins is cheaper than fragmenting
        let t = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * t;
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Mild exploration bonus varying with stream position
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (t * std::f64::consts::PI).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear sharpening
    let mut score = pr.powf(1.5) * (1.0 + 0.5 * progress);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly quadratically
    let coupling = norm_pr * norm_pr * (0.5 + progress) * cap;
    score += coupling;

    // Penalize bins whose residual deviates from the mean residual
    // (favor consolidation toward the average slack)
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * (1.0 + progress) * 10.0;

    // Reward using an existing bin when it's the only fitting one (last chance)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits snugly into the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            let snug = 1.0 - ((pr as f64 - nxt) / cap);
            score -= 15.0 * snug * (1.0 + progress);
        } else {
            // next item won't fit here; mildly penalize leaving awkward slack
            score += 5.0 * norm_pr;
        }
    }

    // Mild penalty when many bins are open: encourage consolidation
    score += (open_bins_count as f64).ln1p() * 2.0 * (1.0 + progress);

    // New-bin candidate: make it slightly attractive only when it truly beats
    // poor fits (its post_residual == capacity - item_size is naturally large)
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues in [0,10) are "dead space"
    // classes; reward exact-zero fits strongly.
    let post_class = post_residual % 10;
    if post_residual == 0 {
        score -= 500.0; // perfect closure
    } else if post_class == 0 {
        score -= 60.0; // residue in a "harmonic decade" — very reusable
    } else if post_class <= 3 {
        score += 25.0 * (4.0 - post_class as f64); // near-dead space penalty
    }

    // Integer-division thresholds: does post_residual still admit a
    // quarter/half-sized successor?
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 40.0;
    } else if post_residual >= quarter {
        score -= 15.0;
    } else {
        score += 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward heavily; if it fits at all, mild reward; if not, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 50.0 - 2.0 * gap as f64;
        } else {
            score += 20.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or the
    // stream is early and we want fresh capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0; // base cost of opening a bin
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if progress < 0.3 {
            score -= 40.0 * (0.3 - progress) / 0.3;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Tie-break by tightness: prefer bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;

    // Slight preference for bins below mean residual (consolidating waste).
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps (below minimum item size 1..10
    // range observed in practice) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Mid-range dead space: harder to fill than large gaps.
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open bins pressure: penalize placements that keep many bins alive with scraps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post residual, reward leaving that gap.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    }
    // If next item cannot use the gap and the gap is small, penalize.
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Prefer bins tighter than the mean residual (good consolidation).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild bias against opening a new bin when open bins can still serve.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward exact closure of a bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is an ideal two-item chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves slack — reward proportionally to tightness.
            let slack = post_residual - next_item_size;
            score -= 200.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use the residual — penalize dead space,
            // scaled by how much of the residual is wasted.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(60.0);
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are good targets.
    let tightness = mean_residual - post_residual as f64;
    score += 0.3 * tightness;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize leaving small unusable slivers (dead space below minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }

    // Early stream: be slightly conservative, prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when it enables a large contiguous space
    // for big upcoming items or when open bins are all nearly full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 50.0; // opening a bin for a chained pair is wasteful
        }
        if avg_fill < 0.5 {
            score += 120.0 * (0.5 - avg_fill); // plenty of room left in open bins
        } else {
            score -= 80.0 * (avg_fill - 0.5); // open bins nearly full, new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
