    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr + 12.0 * pr_norm * pr_norm * cap;

    // Stream progress coupling: as stream advances, penalize residual more strongly
    let prog_coupling = 8.0 * progress * pr_norm * cap;
    score += prog_coupling;

    // Smooth interaction: post_residual^2 scaled by mean residual deviation
    let mean_dev = (mean_residual - pr) / cap;
    score += 5.0 * pr_norm * pr_norm * (1.0 + mean_dev.abs());

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * pr_norm;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            // next item won't fit here; mild penalty for wasting space
            score += 3.0 * pr_norm;
        }
    }

    // Penalize opening new bins when open bins exist and fit well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 10.0 * (1.0 - progress);
    }

    // Cubic coupling term for fine-grained non-linearity
    score += 4.0 * pr_norm * pr_norm * pr_norm * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity (0, cap/4, cap/3, cap/2) are reusable; odd dead zones are not.
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let third = cap / 3.0;
    let half = cap / 2.0;

    // Reward landing exactly on harmonic residual classes.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if (pr - half).abs() < 1.0 {
        score -= 30.0;
    } else if (pr - third).abs() < 1.0 {
        score -= 20.0;
    } else if (pr - quarter).abs() < 1.0 {
        score -= 12.0;
    }

    // Integer-division dead-zone penalty: residuals in awkward bands
    // (e.g. 1..10 or just above common item sizes) are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    let class = post_residual / 10; // harmonic decade class
    score += (class % 3) as f64 * 2.0;

    // Lookahead coupling: if the next item fits the post-residual exactly
    // or within its harmonic class, reward this bin strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 0.5 {
            score -= 45.0;
        } else if pr >= nxt && (pr - nxt) < 10.0 {
            score -= 15.0;
        } else if pr < nxt {
            score += 10.0; // next item cannot use this bin's remainder
        }
        // modulo harmony: next item and residual share residue mod 10
        if post_residual % 10 == (next_item_size as u32) % 10 && pr >= nxt {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }
    // Many fitting bins: mild penalty to prefer tighter bins anyway.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate: only attractive when open bins are nearly full
    // or the item fits none of them well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let desperation = (mean_residual / cap).max(0.0).min(1.0);
        let base = 55.0 + 40.0 * desperation + 20.0 * progress;
        // If this is the only fitting option, opening a new bin is cheap.
        if fitting_bins_count == 0 {
            score = score.min(base - 50.0);
        } else {
            score += base;
        }
    }

    // Waste-ratio term: penalize leaving a large fraction of capacity idle.
    score += 8.0 * (pr / cap);

    // Slight preference for fuller bins overall.
    score -= (cap - bin_residual as f64) / cap * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the smallest plausible item) are pure waste.
    if post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Usable gap: mild quadratic penalty to prefer tighter fits.
        let r = post_residual as f64;
        score += 0.02 * r * r * 0.01;
    }

    // Dead-space coupling with lookahead: if the next item cannot use the
    // remaining gap, the gap is likely wasted forever.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward when the leftover gap exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading items; penalize lightly per open bin.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make the empty bin attractive only when
    // the current bin would leave a large unusable gap.
    if bin_residual == bin_capacity {
        let gap_waste = (100.0 - item_size as f64).min(100.0);
        if post_residual < 10 {
            score -= 45.0; // opening fresh bin avoids nothing worse; keep neutral-ish
        }
        score += gap_waste * 0.1; // slight preference to fill existing bins first
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Late-stream consolidation: as the stream progresses, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / 100.0);

    // Mean-residual coupling: if this bin is far below mean residual, it is
    // a "hole" bin; using it consolidates state.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (post_residual close to zero).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else {
        // Penalize dead space relative to capacity, non-linearly.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack after hosting the next item too.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0;
            if slack == 0.0 {
                score -= 20.0; // perfect 2-item chain
            } else if slack <= 5.0 {
                score -= 8.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.5;
        }
    }

    // Compare post_residual against mean residual: keep residual distribution tight.
    let diff = post_residual as f64 - mean_residual;
    score += diff.abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    // Discard option: opening a new bin is only attractive if this bin's fit is terrible
    // and the item is large (fresh-bin residual = capacity - item is valuable).
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its post_residual is large.
        // Give it a mild handicap so it wins only when open bins fit poorly.
        score += 10.0;
        if item_size >= 60 && next_item_size > 0 && post_residual < next_item_size {
            score -= 15.0; // large item with poor chaining prospects -> fresh bin OK
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is best.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize small dead space that is hard to reuse (post_residual in awkward low range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / (bin_capacity as f64));
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use this residual: mild penalty for wasting space
        score += 8.0 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // More competition: prefer bins that keep more alternatives open
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: with many open bins, encourage filling them rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).sqrt() * 2.0 * (1.0 - progress);

    // Compare bin residual to mean residual: prefer bins with less residual than average
    // (concentrate filling on tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate handling: an empty bin is attractive only when the current bin
    // would leave a large residual or no open bin fits well.
    if bin_residual == bin_capacity {
        let threshold = 0.45 * bin_capacity as f64 * (1.0 + 0.5 * (1.0 - progress));
        if (post_residual as f64) > threshold && fitting_bins_count > 0 {
            score -= 10.0; // opening fresh bin beats leaving large dead space
        } else {
            score += 15.0; // prefer existing bins otherwise
        }
    }

    // Late in the stream, be more aggressive at closing bins completely.
    score -= 15.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    // smooth polynomial coupling of residual with stream progress
    score += 8.0 * (pr_norm * pr_norm) * (0.5 + progress);
    score += 3.0 * (1.0 - progress) * (1.0 - progress) * pr_norm;
    // lookahead coupling
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 4.0 * (1.0 - (nxt / cap)) * (1.0 - progress);
        } else {
            score += 2.0 * (nxt / cap) * (0.5 + progress);
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0 * (1.0 - progress);
    }
    // penalize fragmentation relative to mean residual
    score += 1.5 * (pr - mean_residual) / cap * (1.0 + progress);
    // discourage opening new bins when good fits exist
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fractions
    let frac = post_residual as f64 / cap; // 0.0 .. 1.0
    let harmonic = (frac * 8.0).floor() as i32; // 8 capacity classes

    // Dead-space penalty: leftover too small for typical items (1..100 unknown, but
    // small leftovers are likely unusable). Penalize small-but-nonzero post_residual.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Modulo-class coupling: leftover divisible by common item classes is more reusable
    let pr = post_residual as i64;
    let reusable_mod = (pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0) || (pr % 50 == 0);
    if reusable_mod {
        score -= 15.0;
    } else {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            if npr < 10 {
                score += 20.0; // would create new dead space
            } else {
                score -= 10.0 * (npr as f64 / cap);
            }
        } else {
            score += 12.0; // next item cannot follow into this bin
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer tightest bins mildly via mean residual coupling
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it wins
    // only when all open bins would leave bad dead space.
    if bin_residual == bin_capacity {
        score = cap * 0.5 + 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open new bin
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 20.0; // big next item favors a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever host a
    // meaningful future item are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize placements that block the next item while other bins exist.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few,
    // allow opening a new bin for better packing.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins are crowded
        // or this placement would create severe dead space.
        if open_bins_count == 0 {
            score -= 50.0;
        } else {
            score += pressure * 4.0;
            if post_residual < 10 && post_residual > 0 {
                score -= 30.0; // opening a bin beats making dead space
            }
            if mean_residual > item_size as f64 * 2.0 {
                score += 20.0; // plenty of room elsewhere; don't open
            }
        }
    } else {
        // Prefer bins with smaller residuals when many bins are open.
        score += pressure * (bin_residual as f64 / bin_capacity as f64) * 8.0;
    }

    // Late in the stream, tighten packing further (less tolerance for slack).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins below-average residual
    // (fuller bins) to consolidate slack.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 1.5;
        if post_residual == next_item_size {
            score -= 400.0;
        }
        // Penalize residuals too small for the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 60.0;
        }
    } else {
        // Last item: strongly prefer minimal residual.
        score *= 2.0;
    }

    // Prefer bins tighter than the mean residual (good fits).
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin: avoid opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only for poor fits elsewhere.
    if bin_residual == bin_capacity {
        score += 90.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on leftover space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but less when
    // the current fit is bad (large dead space) or the next item is large.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 25.0;
        // If this bin would leave unusable space for the lookahead item, ease opening.
        if next_item_size > 0 && post_residual < next_item_size {
            new_bin_penalty -= 12.0;
        }
        // If many bins are open with scattered small residuals, consolidation is cheap;
        // opening new bins is more attractive then.
        let avg_fit = mean_residual / (open_bins_count.max(1) as f64);
        if avg_fit < item_size as f64 {
            new_bin_penalty -= 10.0;
        }
        // Early in stream: new bins are cheap; late: prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += progress * 20.0;
        score += new_bin_penalty;
    }

    // Lookahead synergy: prefer bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            score += 5.0;
        }
    }

    // Prefer bins tighter than the average residual (best-fit style).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Mild preference for bins with larger residual among equals (spread load),
    // scaled by how many bins compete.
    score -= (bin_residual as f64) * 0.02;
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Core: quadratic penalty on wasted post-residual, weighted by stream progress
    let mut score = pr * (1.0 + 1.5 * progress * norm_pr);

    // Smooth coupling: post-residual vs. next item size compatibility (bell-shaped reward)
    let compat = (norm_pr - nxt).abs();
    score -= 8.0 * (-4.0 * compat * compat).exp() * (1.0 - progress);

    // Reward tight fits (small post_residual relative to item)
    score -= 5.0 * fit * (1.0 - norm_pr).max(0.0);

    // Last-chance bonus: strongly prefer this bin when it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Penalize bins far below mean residual (fragmentation risk), smoothly
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 3.0 * dev * dev;

    // Mild penalty on opening new bins when many are open and progress is late
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * progress + 0.3 * open_bins_count as f64;
        // But allow new bin if next item is large and post-residual would be tiny anyway
        if nxt > norm_pr {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 5 classes.
    let class = post_residual / (bin_capacity / 5);
    score -= match class {
        0 => 60.0, // tiny dead space left -> excellent fit
        1 => 40.0,
        2 => 20.0,
        3 => 8.0,
        _ => 0.0,  // large leftover, weak reward
    };

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does the leftover fit the next item (harmonic pairing)?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // leftover usable by next item: reward proportionally
            score -= 15.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // leftover likely wasted; penalize big leftovers next item can't use
            score += 5.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
        }
        // next item exactly fills post-residual: strong harmonic pairing
        if next_item_size == post_residual {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
        // but allow new bin if mean residual across bins is very fragmented
        score -= 30.0 * (mean_residual / bin_capacity as f64);
    }

    // Progress-based mild bias: early on, prefer tighter packing (lower score for small post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead gap nothing can ever fill
    } else if post_residual < 20 {
        score += 25.0; // near-dead gap (items >=10, so only tiny items fit)
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward
    }

    // Reward tight fits relative to bin capacity (fill fraction).
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits exactly in the post-residual, reward; if it
    // would leave a dead gap, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            score += 8.0; // next item can't use this bin's leftover
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing residuals are fragmented (high mean residual spread) or the
    // current fit is poor.
    if bin_residual == bin_capacity {
        // Baseline cost of a new bin; offset by potential of full capacity.
        score = 55.0 - 0.3 * (mean_residual - post_residual as f64).abs();
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward when the next item exactly fills the post-residual (perfect 2-step chain).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
    }
    // Penalize post-residual that the next item cannot use (dead space ahead).
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 25.0;
    }

    // Reward tight fits relative to mean residual.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 15.0 * tightness;

    // Penalize bins with residual far below mean (fragmented bins).
    if (bin_residual as f64) < mean_residual {
        score += 0.5 * (mean_residual - bin_residual as f64);
    } else {
        score -= 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current residuals are all bad.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Late-stream preference to close out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep its score neutral-high; only attractive when
    // the item fits terribly everywhere else.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        return 100.0 + 0.5 * open_bins_count as f64;
    }

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    // Reward tight fits strongly (perfect fill gets big discount).
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space relative to smallest plausible future item.
    if post_residual > 0 {
        score += 8.0 * (post_residual as f64 / 10.0).powf(1.5);
    }
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    }

    // Last-chance bonus: if this is the only fitting bin, using it avoids a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item would fit in the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 15.0;
        } else if (bin_residual as u64) >= (item_size as u64 + next_item_size as u64) {
            score -= 10.0; // room for both now
        } else {
            score += 6.0; // next item likely stranded
        }
    }

    // Global pressure: many open bins with large mean residual -> prefer consolidation.
    let pressure = mean_residual / bin_capacity as f64;
    score -= 10.0 * pressure * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: late in stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * fit_ratio;

    // Mild penalty for spreading across many bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth non-linear coupling of post_residual with stream progress.
    // Early on, waste is cheap (bins still fillable later); late, dead space is costly.
    let progress_curve = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    let waste_penalty = post * (0.5 + 1.5 * progress_curve);

    // Tightness reward: strongly favor small post_residual, superlinear.
    let tightness = -20.0 * (-post / cap).exp();

    // Fill ratio coupling: prefer bins where the item occupies a large fraction of residual.
    let fill_ratio = if resid > 0.0 { item / resid } else { 1.0 };
    let fill_reward = -10.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    let last_chance = if fitting_bins_count == 1 { -8.0 } else { 0.0 };

    // New-bin candidate handling: an empty bin should only win when the item is large
    // (poor fit elsewhere) or the stream is early with plenty of room to consolidate.
    let is_new_bin = (bin_residual as u32 == bin_capacity) && bin_capacity > 0;
    let new_bin_penalty = if is_new_bin {
        15.0 + 10.0 * (1.0 - item / cap) - 6.0 * (1.0 - progress_curve)
    } else {
        0.0
    };

    // Lookahead coupling: if the next item fits into the post residual, reward this placement.
    let lookahead = if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post { -6.0 * (1.0 - (nxt / post.max(1.0) - 1.0) * (nxt / post.max(1.0) - 1.0)) }
        else { 2.0 * (nxt - post) / cap }
    } else {
        0.0
    };

    // Mean residual context: penalize creating residuals far from the mean (fragmentation).
    let frag = (post - mean_residual).abs() / cap;

    let mut score = post
        + waste_penalty
        + tightness
        + fill_reward
        + last_chance
        + new_bin_penalty
        + lookahead
        + 4.0 * frag * frag;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which quarter of the bin remains
    let quarter = (post_residual * 4) / bin_capacity; // 0..3 integer division class
    match quarter {
        0 => score -= 25.0,                 // near-perfect fit: tiny dead space
        1 => score += 5.0,                  // awkward sliver: hard to reuse
        2 => score -= 8.0,                  // half-ish residual: very reusable
        _ => score += 2.0,                  // large residual: mild penalty
    }

    // Fine harmonic class via modulo 10 on post_residual (residuals divisible
    // by common item sizes are more reusable)
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 6.0;
    } else if mod10 >= 7 {
        score += 4.0; // ragged edge
    }

    // Reward tight fills scaled by stream progress
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - post_residual as f64 / cap) * (20.0 + 15.0 * progress);

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let nres = post_residual - next_item_size;
            if nres <= bin_capacity / 10 {
                score -= 12.0;
            }
            if (nres * 4) / bin_capacity == 0 {
                score -= 6.0;
            }
        } else {
            score += 3.0; // next item can't reuse this bin anyway
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 35.0 - 20.0 * (crowd / (open_bins_count.max(1) as f64)).min(1.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits: must open
        }
    }

    // Mild preference for bins below mean residual (keep spread balanced)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // item (<= ~10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Gaps below half the smallest item range are semi-dead: moderate penalty.
    if post_residual > 0 && post_residual < 20 {
        score += 0.8 * (20 - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins; grows with open count pressure.
        let mut nb = 25.0 + 3.0 * open_bins_count as f64;
        // If no open bin fits well (this is a last-chance situation), opening
        // a new bin becomes attractive when the item is large.
        if fitting_bins_count == 1 {
            nb -= 30.0 + 0.3 * item_size as f64;
        }
        // Large items deserve fresh bins to avoid fragmenting partial bins.
        if item_size >= 50 {
            nb -= 10.0;
        }
        // Lookahead: if next item is large and this bin would be nearly full,
        // opening fresh space helps.
        if next_item_size > 0 && post_residual < next_item_size {
            nb -= 8.0;
        }
        score += nb;
    }

    // Open-bin pressure: prefer consolidating into fewer bins when many are open.
    if bin_residual != bin_capacity {
        score += 0.15 * open_bins_count as f64;
        // Favor bins already below mean residual (they are the "fuller" ones).
        score += 0.05 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit creates dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 10 {
            score += 30.0; // undo bonus if it creates dead space
        }
    }

    // Lookahead: leaving room for the next item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Late-stream tightening: as the stream progresses, be greedier.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: reward when the next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step match
        } else if next_item_size <= post_residual {
            // reward proportionally to how tightly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty for wasted lookahead potential
            score += 8.0;
        }
    }

    // Reward tight fits relative to mean residual across open bins.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing else fits, opening new bin is fine
        } else if fitting_bins_count == 1 {
            score += 30.0; // an open bin is a last chance, keep it alive
        } else {
            score += 15.0; // prefer packing into existing bins
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (open_bins_count as f64).ln().max(0.0);

    // Small tie-break: prefer bins with less residual overall.
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin before placement
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);

    // Reward tight fits strongly: prefer bins where item occupies most of residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no future item (min size 1..100 unknown) could use:
    // small post_residual is good, but exact zero is best.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    } else if post_residual > 50 {
        // large leftover is only acceptable in a fresh bin
        if bin_residual != bin_capacity {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: fresh bin should only win when current fit is poor
    // or lookahead suggests a big item needs a fresh bin.
    if bin_residual == bin_capacity {
        // Baseline penalty: opening new bins is expensive
        score += 45.0;
        // But if the current bin would be left with awkward residual while the
        // next item is large, a fresh bin is attractive.
        if next_item_size > 0 {
            let next_big = next_item_size as f64 / bin_capacity as f64;
            // If next item can't fit into post_residual, fresh bin gains value
            if (post_residual as f64) < next_item_size as f64 && next_big > 0.4 {
                score -= 35.0 * next_big;
            }
        }
        // Late in the stream, prefer consolidating into existing bins
        score += 20.0 * progress;
        // Many open bins: discourage adding more
        score += 0.5 * open_bins_count as f64;
    } else {
        // Reward filling bins that are already substantially full (best-fit flavor)
        score -= 15.0 * fill * fill;
        // Lookahead synergy: if next item exactly fits the post_residual, big bonus
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        } else if next_item_size > 0 {
            // next item won't fit here; mild penalty for stranding space
            score += 4.0;
        }
    }

    // Global balance: prefer bins whose residual is near the mean residual
    // (keeps the pool of usable residuals homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for fewer open bins overall
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = pr / cap;
    let poly = t * t * (1.0 - t) + progress * t * (1.0 - t * t);

    let mut score = pr * (1.0 + 0.5 * progress) - 20.0 * poly;

    // Reward tight fits, more strongly later in the stream
    score -= fill * fill * (10.0 + 30.0 * progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: bonus if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 12.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        // penalize dead space that next item cannot use
        score += 4.0 * (1.0 - pr / cap) * progress;
    }

    // Penalize spreading across many bins early; encourage consolidation late
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins near the mean (balance)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize slightly unless current bin is unusable later
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Dead-space penalty scaled by how "unusable" the leftover is
        // relative to the smallest plausible item (1..100 unknown range).
        // Classify post_residual via modulo-10 harmonic classes.
        let pr = post_residual;
        let class = pr % 10;
        // Residues that are small (1..=9) are near-unusable dead space.
        if pr < 10 {
            score += 30.0; // worst class: nothing can ever fit
        } else if class == 0 {
            score -= 5.0; // round residue: friendly to decile-sized items
        } else if class <= 3 {
            score += 8.0; // awkward small remainder
        } else {
            score += 2.0;
        }
    }

    // Lookahead coupling: reward if next_item_size fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 40.0; // chains a perfect fit
        } else {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty proportional to overshoot.
        let overshoot = (next_item_size - post_residual) as f64;
        score += 0.3 * overshoot.min(50.0);
    }

    // Last-chance bonus: only one bin fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalize when open bins
    // are sparse (early stream) so we reuse bins; allow new bins later or when
    // open bins are heavily fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 25.0 - 20.0 * progress - 15.0 * fragmentation;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: opening is fine
        }
    }

    // Prefer tighter bins among equals: reward small bin_residual (good fill).
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);

    // Small stream-progress term: later in stream, waste tolerance decreases.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1..=10)
    // are pure waste; penalize hard if post_residual falls in a "dead" band.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // only fits tiny items
    } else if post_residual == 0 {
        score -= 30.0; // perfect fill: strongly reward
    }

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 20.0 / (1.0 + fit_ratio);

    // Lookahead coupling: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would NOT fit but could fit a tighter alternative, penalize slightly.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // making the new-bin candidate less attractive.
    let open_pressure = open_bins_count as f64 * 3.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only wins when existing bins
        // would create bad dead space.
        score += 40.0 + open_pressure;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
    } else {
        score -= open_pressure * 0.2;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (small residual = nearly full bin).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item still fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize creating dead space that cannot fit the next item
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        score += 15.0 * (dead / bin_capacity as f64);
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score -= 5.0 * (mean_residual - bin_residual as f64).max(0.0) / bin_capacity as f64;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Mildly discourage opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Encourage consolidation late in the stream
    score -= 8.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual punishes dead space superlinearly.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Small exact fills are gold.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin strongly.
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 30.0;
        } else if gap > 0 && gap < 15 {
            score -= 12.0;
        } else if gap < 0 {
            // next item won't fit here; slight penalty for wasting residual
            score += (gap.unsigned_abs() as f64).min(40.0) * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins are open
    // or the mean residual suggests existing bins have room.
    if bin_residual == bin_capacity {
        score += 20.0;
        score += open_bins_count as f64 * 1.5;
        score += (mean_residual - item_size as f64).max(0.0) * 0.5;
    }

    // Time horizon: late in the stream, avoid opening bins (waste at the end);
    // early on, allow some exploration of new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    } else {
        score -= progress * 5.0;
    }

    // Prefer bins whose residual is close to the mean (keep bin states homogeneous),
    // mildly.
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, waste is penalized more aggressively (quadratic ramp)
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Cubic interaction: tiny residuals are either great fits or dead space;
    // reward near-perfect fits smoothly (subtract a gaussian-like bump)
    let fit_bump = (-8.0 * norm_pr * norm_pr).exp();
    score -= 6.0 * fit_bump * (1.0 + progress);

    // Penalize moderate dead space that is unlikely to be reused
    let dead = norm_pr * (1.0 - norm_pr);
    score += 10.0 * dead * dead * (1.0 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Scarcity pressure: many open bins relative to progress -> tighten
    let scarcity = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 4.0 * scarcity * norm_pr * (0.5 + progress);

    // Mean-residual alignment: prefer bins close to the mean residual (smooth)
    let diff = (pr - mean_residual) / cap;
    score += 2.0 * diff * diff;

    // Lookahead: if next item fits the post-residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = (pr - nxt) / cap;
            score -= 8.0 * (-10.0 * snug).exp();
        } else {
            score += 3.0 * ((nxt - pr) / cap);
        }
    }

    // New-bin candidate: mildly discourage opening a new bin unless residual waste is large
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes mod 10.
    let m = post_residual % 10;
    // Dead-space classes: residuals like 1..9 are nearly unusable (min item 1, but small items rare).
    score += match m {
        0 => -6.0,                    // perfectly divisible residual: excellent
        5 => -3.0,                    // half class: good
        2 | 4 | 6 | 8 => -1.0,        // even class: decent
        1 | 3 | 7 | 9 => 4.0,         // odd non-5: awkward
        _ => 0.0,
    };

    // Integer-division thresholds on post_residual: how many "typical" items still fit.
    let slots = post_residual / 20; // integer division
    score -= slots as f64 * 3.0;

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain
        } else if post_residual >= next_item_size {
            let chain_gap = post_residual - next_item_size;
            score -= 8.0 - (chain_gap as f64).min(8.0); // closer gap = better
            // harmonic match of next item with residual class
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.62;
        // cheaper to open new bin late in stream? no: late stream favors consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // if many open bins already, opening more is costly
        score += open_bins_count as f64 * 1.2;
        // if mean residual is large, prefer reusing open bins
        score += mean_residual * 0.5;
        // but if item is huge relative to mean residual, new bin is attractive
        if (item_size as f64) > mean_residual {
            score -= (item_size as f64 - mean_residual) * 0.4;
        }
    } else {
        // prefer fuller bins: reward tight fits
        let fill = (bin_residual - post_residual) as f64 / cap;
        score -= fill * 12.0;
        // penalize bins whose residual deviates far from mean (keeps diversity)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Harmonic fraction thresholds on residual: quarter classes
    let q = (post_residual * 4) / bin_capacity.max(1);
    score -= q as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual <= 20 {
            score += 35.0;
        } else if post_residual < 10 {
            score += 35.0;
        }
        // Perfect fit reward
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Reward residual that can still host the next item (lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        if post_residual - next_item_size <= 10 {
            score -= 10.0; // leaves a clean, fully-consumable remainder
        }
    } else if next_item_size > 0 {
        score += 12.0; // next item won't fit here -> dead end
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 4.0 + mean_residual / 10.0;
        score += 30.0 - pressure.min(28.0);
    }

    // Open-bin count pressure: discourage proliferating bins.
    score += open_bins_count as f64 * 0.5;

    // Late in the stream, tighten packing (less tolerance for waste).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward leaving zero residual heavily.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space: residual that cannot fit a typical item (1..=100).
        // Small residuals below 10 are almost unusable dead space.
        if post_residual < 10 {
            score += 30.0;
        }
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the
    // post-residual, strongly reward this placement (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item fits, but check chain quality: leftover after next item.
            let second_residual = post_residual - next_item_size;
            score += second_residual as f64 * 0.4;
        } else {
            // Next item cannot use this bin's residual; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Relative to mean residual: bins tighter than average are more valuable
    // to fill; bins looser than average can absorb awkward items.
    let residual_f = bin_residual as f64;
    let mean_gap = residual_f - mean_residual;
    score += mean_gap * 0.3;

    // Last chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make it moderately attractive only when the item is large relative to
    // capacity or when open bins are few, otherwise bias toward existing bins.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Opening a new bin for a large item is reasonable; small items should
        // go into existing bins.
        score += 12.0 - large_item * 20.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // Many open bins already: discourage opening yet another one.
        score += open_bins_count as f64 * 1.5;
    }

    // Slight preference to fill bins with smaller residual first (best-fit core).
    score += residual_f * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus as post_residual approaches zero.
    score -= 1.5 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(2) * 10.0;

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: penalize if the next item cannot use this bin's post residual.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
        } else {
            // Reward leaving space exactly usable by the next item.
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer filling bins with low residual relative to the mean (consolidate).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more selective (favor new bins less);
    // late in the stream, pack tightly and avoid opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Many open bins: discourage opening new ones by penalizing empty-bin candidates.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0 - progress * 8.0;
    }

    // Slight preference for bins with larger residual when item is large.
    if item_size > bin_capacity / 2 {
        score += 0.1 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * (1.0 - pr_norm);
    score += 12.0 * poly;

    // Penalize large dead space more aggressively as stream progresses
    score += 6.0 * pr_norm * pr_norm * progress;

    // Reward tight fits (small post residual) especially when few alternatives exist
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - pr_norm);
    }

    // Lookahead coupling: reward residual that can still host the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 4.0 * (1.0 - (n / cap));
        } else {
            score += 3.0 * (1.0 - pr_norm);
        }
    }

    // Mild penalty for proliferating open bins early in the stream
    score += 0.5 * (open_bins_count as f64).powf(1.5) * (1.0 - progress);

    // Deviation from mean residual: prefer bins near the mean to keep balance
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10 / small remainders) are rewarded.
    let post_mod = post_residual % 10;
    let post_div = post_residual / 10;

    // Reward leftovers that are multiples of 10 (likely to fit future items).
    if post_mod == 0 {
        score -= 12.0;
    } else if post_mod <= 3 {
        // Tight-but-dead space: penalize creating unusable slivers.
        score += 6.0;
    } else {
        score += post_mod as f64 * 0.8;
    }

    // Integer-division thresholds on post_residual: chunked quality ladder.
    match post_div {
        0 => score += 20.0,          // nearly full bin: excellent, pack it tight
        1 => score -= 2.0,           // 10-19 leftover: decent
        2 => score -= 6.0,           // 20-29 leftover: good
        3 => score -= 8.0,           // 30-39 leftover: fine
        _ => score -= 10.0,          // >=40 leftover: bin still very usable
    }

    // Coupling with lookahead: does post_residual fit next_item_size exactly or well?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 25.0;       // perfect chained fit
            } else {
                score -= (slack.min(20) as f64) * 0.9;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to overshoot.
            score += ((next_item_size - post_residual) as f64) * 0.35;
        }
    } else {
        // Last item: strongly prefer filling bins as tightly as possible.
        score += (bin_capacity - bin_residual) as f64 * 0.05;
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin gets a baseline score so it wins
    // only when no open bin offers a genuinely good fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    }

    // Mild pressure toward using many open bins when mean residual is high
    // (spreading load keeps future flexibility), but only mid-stream.
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += mean_gap * 0.15;

    // Slight tie-break noise-free determinism: prefer bins with more residual
    // headroom relative to capacity fraction classes.
    let frac_class = (bin_residual * 4) / bin_capacity; // 0..4 quartile class
    score += frac_class as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to plausibly
    // fit a future item (dead space) are heavily penalized with a quadratic term.
    let dead_threshold = 10.0; // smallest possible item size
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 2.0;
    }

    // Reward near-perfect fits (post_residual very small but nonzero is fine;
    // exact zero fill is best).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward tight relative fit: item fills a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 10.0;

    // Open-bin pressure: with many open bins, discourage opening yet another
    // (the new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But if this bin would be the only fitting option, opening is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Last-chance bonus: if this is the only open bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item would fit exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if post_residual is positive but smaller than the next item,
    // creating stranded space relative to the lookahead.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Mild preference for bins already below mean residual (consolidating
    // space into emptier bins keeps larger residuals available).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Early in the stream, be more willing to open bins (spread items);
    // late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (small post_residual) is better.
    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, decaying quadratically with mismatch.
        score -= 40.0 * (1.0 - (diff / (bin_capacity as f64)).min(1.0)).powi(8);
        // Penalize leaving dead space that is too small for the next item.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64; // unusable sliver penalty
        }
    } else {
        // Last item: just prefer minimal post_residual.
        score += 0.1 * post_residual as f64;
    }

    // Compare bin's residual to mean residual: filling a below-average (tight) bin
    // is good; wasting a fat bin's residual is bad.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the item
    // is large or no good fits exist. The larger the item, the more a fresh bin
    // makes sense.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 30.0 - 0.2 * item_size as f64;
        score += new_bin_penalty * (1.0 - 0.3 * progress);
        // If item is huge, opening a fresh bin is fine.
        if item_size >= 60 {
            score -= 20.0;
        }
        // If other bins fit but poorly (post_residual would be large), opening a
        // new bin is less penalized.
        if next_item_size > 0 && post_residual as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Mild penalty for accumulating too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the bin after placement.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that is hard to reuse (post_residual in awkward range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward for exact-ish follow-up fit.
            let gap = post_residual as f64 - next_item_size as f64;
            if gap <= 5.0 { score -= 8.0; }
        } else {
            // Next item won't fit here; slight penalty proportional to leftover.
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many fitting bins: prefer the tightest among them (post_residual already does this),
    // but add mild pressure when bin count is high to consolidate.
    if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state coupling: if mean residual is large relative to item, encourage
    // filling existing bins rather than spreading.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > item_size as f64 {
        score -= 3.0 * (1.0 - t);
    }

    // New-bin candidate: empty bin should only win when no good existing option exists.
    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let waste_of_new = bin_capacity as f64 - item_size as f64;
        let mut penalty = 30.0;
        // If the item is large, a fresh bin is more attractive.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            penalty -= 22.0;
        }
        // If existing bins are mostly full (small mean residual), new bin is fine.
        if mean_residual < item_size as f64 {
            penalty -= 15.0;
        }
        // Late in stream, prefer consolidation.
        penalty += 10.0 * t;
        // If the next item is small and could pair with this item in a fresh bin,
        // opening a new bin is more attractive.
        if next_item_size > 0 && next_item_size <= waste_of_new {
            penalty -= 6.0;
        }
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap; // normalized post residual in [0,1]

    // Tight fits rewarded, dead space penalized more strongly as stream progresses
    let tightness = 1.0 - prn * prn; // peaks at perfect fill
    score -= 12.0 * tightness * (0.5 + progress);

    // Penalize large residuals super-linearly, modulated by progress
    score += 4.0 * prn * prn * prn * (1.0 + 2.0 * progress);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - prn);
    }

    // Lookahead: reward if next item fits in the resulting residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 5.0 * (1.0 - ni / cap) * (0.3 + 0.7 * progress);
        } else {
            score += 3.0 * (ni - pr) / cap;
        }
    }

    // Interaction with mean residual: prefer bins close to the mean (balance)
    let dev = (pr - mean_residual).abs();
    score += 1.5 * (dev / cap) * (dev / cap);

    // Slight penalty for too many open bins
    score += 0.5 * (open_bins_count as f64).ln();

    // New-bin candidate: keep it neutral-ish but discourage unless residual is large
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic classes of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter; // 0..24
    // Residuals in low harmonic classes are "dead space" -> penalize strongly
    if post_residual > 0 {
        if class <= quarter / 4 {
            score += 25.0; // tiny unusable sliver
        } else if class <= quarter / 2 {
            score += 8.0;
        } else if class <= (3 * quarter) / 4 {
            score -= 4.0; // mid-class residual still usable
        } else {
            score -= 10.0; // near full quarter: very reusable
        }
    } else {
        score -= 40.0; // perfect closure
    }

    // Harmonic class of post_residual via integer division: which "slot band"
    let band = post_residual / quarter;
    score -= band as f64 * 6.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // mod-harmonic match: next item leaves a residual in a good class
            let next_post = post_residual - next_item_size;
            if next_post % quarter <= quarter / 4 && next_post > 0 {
                score += 12.0;
            } else {
                score -= 15.0 * (next_post as f64 / quarter as f64);
            }
        } else {
            score += 10.0; // next item won't fit here at all
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 2.0
            + (mean_residual / bin_capacity as f64) * 20.0
            + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // Empty bin gets a mid-range score; tight fits in existing bins beat it
        score += 30.0 + pressure;
    }

    // Progress-scaled waste penalty: waste matters more later in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 15.0 * progress;

    // Mean residual divergence: prefer bins whose residual deviates from mean
    // (harmonic alignment with the fleet average keeps classes diverse)
    let dev = (post_residual as f64 - mean_residual).abs();
    score -= dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (<10) are nearly unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 3.0 * post_residual as f64; // smaller gap => harsher penalty
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual is close to item size (tight fit coupling).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins => prefer filling existing ones.
    score += 2.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space confirmed unusable for next item too
    }

    // New-bin candidate: only attractive when open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 10.0 * (1.0 - fragmentation.min(1.0)) + 0.5 * open_bins_count as f64;
    }

    // Late-stream bias: consolidate toward the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: reward exact match of post_residual
    // with next_item_size (perfect chain placement).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        // Exact match: strong reward
        if diff == 0 {
            score -= 60.0;
        } else if diff <= 5 {
            score -= 30.0 - diff as f64 * 4.0;
        } else {
            // Penalize large mismatches that strand space the next item can't use
            score += diff as f64 * 0.4;
        }
        // If next item cannot fit anywhere in this bin's post state, penalize
        if next_item_size > post_residual {
            score += 8.0;
        }
    } else {
        // Last item: just minimize waste
        score += 0.0;
    }

    // Relative to mean residual: prefer bins with residual near mean (balanced),
    // avoid extreme outliers creating dead space.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful for small items
    // when open bins exist; penalize unless item is large and fit is tight.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        // Base cost of opening a new bin grows with number of open bins (fragmentation)
        score += 20.0 + open_f * 1.5;
        // If item is large (>= 50), a fresh bin is reasonable: reduce penalty
        if item_size >= 50 {
            score -= 18.0;
        }
        // If no open bin fits well (this is fallback anyway), soften penalty
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
        // Early in stream, opening bins is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Slight preference for tighter fits overall (small post_residual good,
    // but avoid post_residual < 10 dead space unless next item matches)
    if post_residual < 10 && next_item_size != post_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residual too small for the smallest plausible item.
    let small_item_floor = 1.0;
    if post_residual > 0 && (post_residual as f64) < small_item_floor * 10.0 {
        score += 25.0;
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Lookahead: reward leaving space for the next item, penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && (next_item_size as f64) - (post_residual as f64) < 10.0 {
            score += 5.0; // near-miss wastes space
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(2) as f64);
    score -= 6.0 * progress * (mean_residual / bin_capacity as f64);

    // Penalize opening new bins when many bins are already open with slack.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * (open_bins_count as f64).ln().max(0.0);
        // But allow new bin if existing bins are nearly full.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> favor consolidation.
    if open_bins_count > 3 && mean_residual > 40.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Strongly reward tight fits: quadratic coupling of post_residual with progress.
    let mut score = base * (1.0 + 1.5 * progress * (pr / cap));

    // Penalize large dead space that can't fit a typical item, smoothly.
    let dead = (pr / cap).powi(3);
    score += 40.0 * dead * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a bin unless post_residual of the item
    // placed here would be worse than typical (compare against mean residual).
    if bin_residual == bin_capacity {
        let open_penalty = 30.0 + 25.0 * (1.0 - progress);
        let new_bin_post = (cap - item_size as f64) / cap;
        let fit_quality = (pr / cap).powi(2);
        score += open_penalty * (1.0 - fit_quality) * (1.0 - progress);
        // If next item would fit nicely in the fresh bin's residual, soften penalty.
        if next_item_size > 0 {
            let next_post = pr - next_item_size as f64;
            if next_post >= 0.0 {
                score -= 10.0 * (1.0 - (next_post / cap).abs());
            }
        }
    }

    // Slight preference for bins with residuals close to mean (balance avoidance
    // of fragmentation), smooth coupling.
    let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
    score += 5.0 * dev * dev;

    // Encourage packing into nearly-full bins smoothly as stream progresses.
    score -= 10.0 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (modulo arithmetic) ---
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Class A: post_residual divisible by 10 -> "clean" slot, many future items fit exactly.
    if pr % 10 == 0 {
        score -= 6.0;
    }
    // Class B: post_residual divisible by 5 but not 10 -> moderately clean.
    else if pr % 5 == 0 {
        score -= 3.0;
    }
    // Class C: awkward small remainder -> dead-space penalty.
    else {
        score += 4.0;
    }

    // Integer-division thresholds on post_residual (capacity fractions).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr < quarter {
        // Very tight leftover: nearly perfect packing, reward strongly.
        score -= 10.0;
        // But if truly unusable (tiny), penalize as dead space.
        if pr < 10 {
            score += 14.0;
        }
    } else if pr < half {
        score -= 2.0;
    } else {
        // Large leftover: wasteful placement, penalize.
        score += 3.0;
    }

    // --- Coupling with next_item_size (lookahead k=2) ---
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= next_item_size {
            // Next item fits exactly into the post residual -> excellent chain.
            if pr == next_item_size {
                score -= 12.0;
            } else if (pr - next_item_size) % 10 == 0 {
                score -= 7.0;
            } else {
                score -= 2.0;
            }
            // Harmonic class: next item size mod 10 alignment with post residual mod 10.
            if pr % 10 == next_item_size % 10 {
                score -= 3.0;
            }
        } else {
            // Next item cannot use this bin's remainder: mild penalty scaled by waste.
            let waste = nx;
            score += (waste / cap) * 8.0;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 5.0;
    }

    // --- Last-chance logic ---
    if fitting_bins_count == 1 {
        // This is the only bin that fits: strongly favor using it over opening a new bin.
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        // Plenty of alternatives: be pickier about fit quality.
        score += 1.5;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new empty bin: baseline cost of opening it.
        score = cap * 0.75;
        // At stream start, opening bins is natural.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        // If next item is huge, a fresh bin is attractive.
        if next_item_size >= half as u32 {
            score -= 8.0;
        }
        // If few bins fit the item, avoid opening a new bin.
        if fitting_bins_count <= 1 {
            score += 25.0;
        }
    }

    // --- Contextual coupling: mean residual & open bins count ---
    let mr = mean_residual;
    if mr > cap * 0.5 && open_bins_count > 2 {
        // Lots of slack spread across bins: encourage consolidating into tight bins.
        score += (mr / cap) * 4.0;
    }
    if open_bins_count as f64 > (step_index as f64).max(1.0) * 0.6 {
        // Bin proliferation: penalize placements that leave large residuals.
        score += prf / cap * 6.0;
    }

    // Small deterministic tie-breaker based on harmonic class of bin_residual.
    score += ((bin_residual % 7) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 18.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward when the next item exactly fills the post residual.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }
    // Penalize gaps that can never be useful (below minimum item size 1 is trivial,
    // so penalize gaps smaller than a typical small item more when lookahead can't use them).
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., many competing bins but poor fit) or stream is early.
    if bin_residual == bin_capacity {
        let poor_alternatives = (fitting_bins_count == 0) as i32 as f64
            + (fitting_bins_count > 3) as i32 as f64 * 0.5;
        score -= 20.0 * poor_alternatives;
        // Late in the stream, prefer filling existing bins.
        score += 30.0 * progress;
    }

    // Mild alignment with mean residual: prefer bins deviating less from mean
    // to keep residuals balanced.
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // Slack left for next item: mild reward proportional to how close it is.
            let slack_gap = (post_residual - next_item_size) as f64;
            score -= (50.0 / (1.0 + slack_gap)).min(50.0);
        } else {
            // Next item cannot fit in leftover: penalize unusable dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.5;
        }
    }

    // Compare against mean residual: bins with residual below mean are "tighter",
    // placing there consolidates waste; reward picking below-mean bins.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else {
        score += (residual_f - mean_residual) * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the item
    // is large relative to residual capacity of typical open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Large items late in the stream benefit from a fresh bin; small items should pack.
        let new_bin_penalty = 300.0 - 200.0 * item_frac - 100.0 * progress;
        score += new_bin_penalty.max(0.0);
    }

    // Mild penalty for very small post-residuals that are dead space (< smallest item).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Slight preference for bins with larger residual when item is large (avoid fragmentation).
    if item_size > 50 {
        score += (100.0 - bin_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear boost.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual that is too small to hold even a
    // minimal item is wasted — but exact zero is perfect packing.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // strongly reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global state: many open bins with slack -> prefer consolidating into
    // bins with above-average residual.
    if bin_residual as f64 > mean_residual && open_bins_count > 1 {
        score -= 3.0;
    } else if (bin_residual as f64 - mean_residual).abs() < 2.0 && open_bins_count > 2 {
        score += 2.0;
    }

    // New-bin candidate handling: a fresh bin should only win when no open
    // bin offers a decent fit. Penalize it by the fraction of the stream
    // already processed (later in stream, opening bins is more costly).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let decent_fit_exists = fitting_bins_count > 0 && {
            // proxy: item fits in less than half the bin's residual is good
            item_size as f64 / mean_residual.max(1.0) < 0.9
        };
        score += 20.0 + 30.0 * progress;
        if decent_fit_exists {
            score += 15.0;
        }
        // Early stream: allow new bins more freely to build diversity.
        if progress < 0.15 {
            score -= 18.0;
        }
    }

    // Mild preference for filling bins that are already half full or more.
    let used_frac = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 6.0 * used_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fit_ratio = item_size as f64 / cap;

    // Base: penalize wasted residual, with non-linear (quadratic) coupling
    let mut score = pr * (1.0 + 0.9 * (pr / cap).powi(2));

    // Smooth interaction: residual waste matters less late in the stream
    score *= 1.0 - 0.25 * progress * (pr / cap);

    // Reward tight fits (small post_residual) with a smooth bump
    score -= 6.0 * (1.0 - pr / cap).powi(3) * fit_ratio;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Penalize bins that deviate from the mean residual (keep bin pool balanced)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.5 * dev * dev * cap * 0.01;

    // Lookahead: penalize if next item would be stranded by this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            let shortfall = (nxt - pr) / cap;
            score += 4.0 * shortfall.powi(2) * cap * 0.05;
        } else {
            score -= 3.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // New-bin candidate handling: opening a fresh bin wastes the pooled space
    if bin_residual == bin_capacity {
        let waste = pr / cap; // residual left in the brand-new bin
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        // Penalize new bins more when many bins are open and the new-bin residual is large
        score += 10.0 * pressure * (1.0 + waste) * (1.0 - 0.5 * progress);
        // Allow new bins when no open bin fits and the fresh residual could host the next item
        if fitting_bins_count == 0 && next_item_size as f64 <= pr {
            score -= 6.0;
        }
        if fitting_bins_count == 0 {
            score -= 4.0; // must open a bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // usable "slots" via integer division against common item sizes.
    let mut score = post;

    // Reward tight fits strongly (small dead space).
    score -= (1.0 - post / cap) * 30.0;

    // Dead-space penalty: leftovers that cannot hold even the smallest
    // plausible item are nearly worthless. Class thresholds at 0,1..=9,
    // 10..=19, 20..=49, >=50.
    if post_residual == 0 {
        score -= 25.0; // perfect fit, best outcome
    } else if post_residual < 10 {
        score += 20.0; // unusable crumb
    } else if post_residual < 20 {
        score += 8.0; // only tiny items fit
    } else if post_residual < 50 {
        score += 2.0;
    } else {
        score -= 6.0; // roomy leftover, still flexible
    }

    // Harmonic modulo logic: leftover divisible by common sizes (10/20/25/50)
    // composes well with typical streams.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 3.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this bin is ideal; if next item would be blocked, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.15;
        } else {
            score -= 1.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap when many bins are already open or the
        // stream is early, but expensive if this is the only fitting bin.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0
            + 10.0 * (1.0 - progress)
            + if fitting_bins_count == 1 { 40.0 } else { 0.0 }
            - (open_bins_count.min(10) as f64) * 0.5;
        // A fresh bin is attractive if mean residual across open bins is small
        // (nothing useful to pack into anyway).
        score -= (mean_residual / cap).min(1.0) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A small NONZERO leftover is "unusable dead space": it wastes capacity
    // while being too small to host future items. Penalize it hard so that
    // leaving a larger (still usable) gap — or opening a fresh bin — wins instead.
    if post_residual > 0 && post_residual < 15 {
        // The smaller (and thus more useless) the gap, the harsher the penalty.
        score += 25.0 + (15 - post_residual) as f64;
    } else if post_residual >= 15 {
        // A comfortably usable residual: mild reward.
        score -= 2.0;
    }
    // post_residual == 0: perfect closure, no extra penalty (base term = 0).

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // The next item can land exactly here: strongly desirable.
            score -= 6.0;
        } else if post_residual > 0 {
            // This bin will be stranded after the current placement.
            score += (post_residual as f64) * 0.15;
        }
    }

    // --- Last-chance protection ---
    // If this is the ONLY open bin that fits the item, keep it alive
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // --- Open-bins-count pressure ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        // Reward filling existing bins, more urgently as the stream progresses
        // and as the number of open bins grows (consolidation pressure).
        score -= 0.5 * open_bins_count as f64 * (0.5 + progress);
    } else {
        // New-bin candidate: penalize when many bins are already open,
        // plus a small fixed handicap so only genuinely better fits win.
        score += 0.3 * open_bins_count as f64 + 3.0;
    }

    // --- Mean-residual coupling ---
    // Prefer bins tighter than the current average residual (best-fit flavor).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain: item fits now AND next item fits after — ideal.
            score -= 80.0;
            // Bonus if leftover after the next item would also be small (perfect chain).
            let post2 = post_residual - next_item_size;
            if post2 == 0 {
                score -= 300.0;
            } else if post2 <= 10 {
                score -= 100.0;
            }
        } else {
            // Leftover is dead space relative to the next item: penalize proportionally.
            let waste = next_item_size - post_residual;
            score += 0.6 * waste as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter than average (best-fit flavor).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is huge
    // and would leave a very tight fit elsewhere (rarely better than reuse).
    if bin_residual == bin_capacity {
        score += 120.0;
        if item_size >= 70 {
            score -= 100.0; // big items are fine in a fresh bin
        }
        // If next item also needs a fresh large space, opening now is okay.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 60.0;
        }
    }

    // Late in the stream: consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tight * tight;

    // Penalize dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // wasted residual if next item cannot use it
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // slight penalty for many alternatives to encourage diversity of choice
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state coupling: when mean residual is high, prefer filling bins
    // aggressively (avoid fragmenting); when low, be more selective.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev;

    // Time horizon: later in the stream, prefer closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / cap);

    // New-bin candidate: make it unattractive unless all else is bad, but
    // allow it when this bin would leave large unusable space.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 20.0 };
        score = cap * 0.6 + pressure - 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.8 * progress * x + 0.35 * progress * progress * (1.0 - x) * (1.0 - x));

    // Penalize dead space more strongly as stream progresses (fewer chances to fill it)
    score += 2.0 * progress * x * x * cap * 0.1;

    // Reward tight fits via smooth saturating term
    let tightness = 1.0 - x;
    score -= 1.5 * tightness * tightness * tightness * (1.0 + progress);

    // Last-chance bin: smooth bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: penalize if post residual cannot hold next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if post >= nxt { 1.0 } else { 0.0 };
        let gap = (nxt - post).abs() / cap;
        score += (1.0 - fits_next) * gap * 4.0 * (0.5 + progress);
        score -= fits_next * 2.0 * (1.0 - gap);
    }

    // Slight penalty for bin proliferation
    score += open_bins_count as f64 * 0.05 * progress;

    // Mean-residual coupling: prefer bins near the mean residual (smooth quadratic)
    let dev = (post - mean_residual) / cap;
    score += 1.2 * dev * dev * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over small moduli.
    // Residuals that are "harmonically compatible" with common item sizes are less dead.
    let pr = post_residual;
    if pr > 0 {
        // Penalize residuals that no plausible item can use well (dead space classes).
        // Items 1..=100; residuals in {0..=99}. Class residuals mod 10.
        let class = pr % 10;
        // Classes 1,2,3 are hard to fill -> penalize; classes 0,5 are friendly -> soften.
        match class {
            0 => score -= 6.0,
            5 => score -= 3.0,
            1 | 2 | 3 => score += 4.0 + class as f64,
            _ => {}
        }
        // Small residuals are excellent regardless of class.
        if pr <= 3 { score -= 12.0; }
        else if pr <= 8 { score -= 7.0; }
        else if pr <= 15 { score -= 2.0; }
        // Large post-residual with large item => we kept a big chunk open; mild bonus only if next item fits exactly.
    }

    // Perfect lookahead fit: next item exactly fills post_residual.
    if next_item_size > 0 && next_item_size == pr {
        score -= 25.0;
    }
    // Next item fits comfortably in post_residual: reward.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 4.0 + (pr as f64 - next_item_size as f64).sqrt() * 1.5;
    } else if next_item_size > 0 && pr < next_item_size {
        // post_residual too small for the lookahead item: dead space risk.
        score += 5.0;
        // Harmonic: if post_residual divides evenly by 10, it's still reusable later.
        if pr % 10 == 0 && pr >= 10 { score -= 4.0; }
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Competition: mild tie-break toward tighter fit via post_residual (already dominant).
        score += (fitting_bins_count as f64).ln() * 0.5;
    }

    // New-bin candidate: only attractive when item is huge relative to capacity
    // (packing into an open bin would leave heavy fragmentation) or stream is early.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // Penalize new bin; the penalty shrinks for very large items.
        score += 18.0 * (1.0 - fill_frac).max(0.0);
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= 8.0 * (1.0 - progress);
    } else {
        // Reward using existing bins proportionally to how full the stream is.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 3.0 * progress;
    }

    // Coupling with mean residual: if this bin's residual is far below mean, it's a good absorber.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev.max(0.0); // bin tighter than mean -> slightly lower score
    score -= 0.05 * (-dev).max(0.0) * -1.0; // no-op guard, keep sign logic explicit below
    if bin_residual as f64 > mean_residual {
        score += 0.08 * (bin_residual as f64 - mean_residual);
    }

    // Integer-division threshold on post_residual: chunk classes of 20.
    let chunk = pr / 20;
    score += chunk as f64 * 2.5; // bigger chunks (more empty space) penalized

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever host
    // typical items (<= 10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-ish gaps that few future items can use.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is good; mild penalty scaled with open bins.
    score += open_bins_count as f64 * 0.6;

    // Prefer bins whose residual is close to the item (best-fit style),
    // reinforcing tight packing relative to mean residual.
    score += (mean_residual - bin_residual as f64).abs() * 0.3;

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    }
    // If next item would NOT fit here, mildly penalize leaving a gap it almost fits.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.2;
    }

    // New-bin candidate: baseline cost so a new bin is only chosen when all
    // open bins have clearly bad fits. Scales with stream progress (late in
    // the stream, reusing bins matters more) and open bin count.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9
            + open_bins_count as f64 * 1.5
            + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // If this is the only fitting option anyway, opening a bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: next item fits perfectly in post_residual
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 60.0; // perfect chain fill
        } else if post_residual as u32 >= next_item_size {
            // slack after next placement
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportionally to gap
            let gap = next_item_size as f64 - post_residual as f64;
            score += 0.5 * gap;
        }
    } else {
        // last item: reward tightest fit
        score -= 10.0;
    }

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Relative to mean residual: prefer bins below-average residual (tight bins)
    score += 0.3 * (mean_residual - post_residual as f64);

    // Mild pressure to close out bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    // Discard new-bin candidate unless item is large relative to residual alternatives
    if bin_residual == bin_capacity {
        score += 12.0 + 0.1 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to hold typical future items.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dead_threshold = 10.0 + 8.0 * t;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 14.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Global pressure: many open bins with large mean residual -> encourage consolidation.
    if open_bins_count > 2 {
        let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln();
        score += 5.0 * consolidation * (1.0 - fit_ratio);
    }

    // New-bin candidate handling: only attractive early in the stream or when the item
    // is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let early_bonus = (1.0 - t) * 8.0;
        let big_item = if item_size >= 60 { 6.0 } else { 0.0 };
        score -= early_bonus + big_item;
        // Penalize opening new bins late when consolidation is possible.
        if t > 0.6 && fitting_bins_count > 0 {
            score += 15.0 * t;
        }
    }

    // Slight preference for bins with larger residual when fits are comparable.
    score -= 0.02 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let poly = prn * prn * (0.5 + 2.0 * progress) + prn * progress * progress;
    score += poly * bin_capacity as f64 * 0.3;

    // Reward tight fits, more strongly later in the stream
    let tightness = 1.0 - prn;
    score -= tightness * tightness * (1.0 + progress) * 10.0;

    // Penalize dead space that no typical item could use
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 2.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Lookahead: reward leaving space usable by next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0;
    } else if next_item_size > 0 && pr > 0.0 {
        score += (next_item_size as f64 - pr).min(20.0) * 0.5;
    }

    // Mild penalty for spreading across many open bins early
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    // Mean residual coupling: prefer bins near the mean residual
    score += ((pr - mean_residual).abs()) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Harmonic class of the leftover space: leftovers divisible by common
    // size classes (10/20/25/50) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill is ideal
    } else {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 20 == 0 { bonus += 4.0; }
        if pr % 25 == 0 { bonus += 4.0; }
        if pr % 50 == 0 { bonus += 6.0; }
        score -= bonus;

        // Dead zone: tiny unusable leftovers are bad.
        if pr < 10 {
            score += 50.0;
        }
    }

    // Lookahead coupling: does post_residual harmonically match next item?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // next item fills bin exactly
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap < 10 {
                score += 25.0; // leaves dead space for next item
            } else if gap % 10 == 0 {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // competition: mild penalty to spread load
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate: only attractive when existing residuals are poor.
    if bin_residual == bin_capacity {
        let bad_existing = mean_residual / bin_capacity as f64;
        score = 45.0 + 30.0 * bad_existing - 10.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0;
        }
        if step_index + 1 >= total_items {
            score += 100.0; // never open a bin for the last item
        }
    }

    // Late-stream consolidation: prefer filling existing bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1..10)
    // are pure waste; penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Medium gaps can still be filled by small items; mild penalty.
        score += 0.5 * (post_residual as f64 - 10.0);
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Penalize a gap that just barely fails to fit the next item (dead space for k=2).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score += 12.0;
    }

    // Open-bins pressure: prefer bins already open over spawning new ones.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize bins whose residual deviates wildly from the mean (fragmentation).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: make it attractive only when the current fit is bad
    // (large post_residual) or when many bins are already open.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score -= 25.0 - 30.0 * fit_quality + 0.5 * open_bins_count as f64;
    }

    // Early in the stream, allow slightly more freedom to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    // Mild preference for tighter fits overall.
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual matches next_item_size closely.
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 45.0 * (1.0 - match_gap / bin_capacity as f64);
        // Perfect match: next item exactly fills this bin afterwards.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual cannot host the next item; penalize dead space, worse when tiny.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 30.0 * (1.0 - dead / 10.0);
        } else {
            score += 4.0 * (dead / 10.0 - 1.0).min(3.0);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize spreading across many open bins mildly; encourage consolidation early.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late in the stream, tighten packing (avoid new bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current fit is bad and lookahead is poor.
        score += 20.0 + 40.0 * progress;
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) >= item_size as i64 {
            score -= 10.0;
        }
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (wasted-space penalty is superlinear).
    let frac_used = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * frac_used * frac_used;

    // Penalize leaving awkward dead space that few future items can use.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.1 {
            score -= 6.0; // near-perfect fill
        } else if dead < 0.3 {
            score += 3.0 * dead; // moderately awkward gap
        } else {
            score += 8.0 * dead; // large unusable gap
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 3 {
        score += 1.5; // plenty of alternatives, less urgency
    }

    // Lookahead: if next item fits into post_residual, reward; if it barely misses, penalize.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) >= ni {
            score -= 4.0 * (ni / bin_capacity as f64);
        } else if (bin_residual as f64) >= ni && (post_residual as f64) < ni {
            score += 5.0; // blocking the next item is costly
        }
        // Chain packing: post_residual exactly matches next item's complement
        if (post_residual as u32) == next_item_size {
            score -= 7.0;
        }
    }

    // New-bin candidate handling: opening a bin is expensive unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = (bin_residual as f64 - item_size as f64) > 0.5 * bin_capacity as f64;
        if bad_fit && fitting_bins_count <= 2 {
            score -= 9.0 * (0.5 + progress); // open fresh bins more readily later
        } else {
            score += 15.0; // default: strongly prefer existing bins
        }
        // Few open bins and large mean residual -> reuse is cheap
        if open_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
    }

    // Mild preference for fuller bins when many bins are open (consolidation).
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Time-horizon modulation: early stream, be conservative with space; late stream, fill aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = r;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress * progress;
    let tightness = 1.0 - (r / cap); // 0 = perfect fit, 1 = empty
    score += tightness * tightness * (12.0 + 18.0 * p) * (1.0 + (mean_residual / cap).max(0.0));

    // Reward near-perfect fits more strongly as stream progresses
    if r <= 5.0 {
        score -= 25.0 * (1.0 + p);
    }

    // Penalize last-chance waste: if this is the only fitting bin, dead space hurts
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score += 6.0 * tightness * (1.0 + 2.0 * progress);
    }

    // Lookahead: favor bins whose residual can still host the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            score -= 8.0 * (1.0 - (r - n) / cap) * (0.5 + progress);
        } else {
            score += 4.0 * (n - r) / cap;
        }
    }

    // Mild penalty for opening a new bin when many bins are already open
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (open_bins_count as f64).ln().max(0.0) - 8.0 * progress;
    }

    // Reward filling bins with large items (high fill ratio)
    score -= (item_size as f64 / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 0.5 * tightness * (bin_capacity as f64);

    // Dead-space penalty: post_residual too small to ever fit any item (size >= 1).
    if post_residual > 0 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0_f64.max(post_residual as f64).min(10.0) / 10.0);
    }
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // nearly unusable sliver
    }

    // Lookahead: reward bins whose residual can host the next item (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 8.0 * (next_item_size as f64) / 100.0;
        } else {
            // residual cannot host next item: penalize proportional to leftover gap
            score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0)).max(0.0);
        }
        // Perfect chain: post_residual exactly equals next item size
        if post_residual == next_item_size && next_item_size > 0 {
            score -= 15.0;
        }
    } else {
        // Last item: only tightness matters; extra reward for emptying a bin.
        score -= 10.0;
    }

    // Harmonic class logic: modulo classes of post_residual.
    // Residuals in "coarse" classes (multiples of 10) pair well with typical sizes.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    }
    // Odd/hard classes: residuals like 1..9 mod 10 below 10 already penalized;
    // penalize residuals in [11..19], [21..29]... slightly (awkward pairing).
    if pr >= 11 && pr % 10 != 0 {
        score += 3.0 * ((pr % 10) as f64) / 9.0;
    }
    // Integer division thresholds: residuals >= 50 are half-empty bins; keep them flexible.
    if pr >= 50 {
        score -= 6.0 * (pr as f64) / 100.0;
    } else if pr >= 25 {
        score -= 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.1 * (item_size as f64);
    }

    // New-bin candidate handling: neutral-ish score so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; rises as stream progresses.
        let progress = (step_index as f64) / ((total_items as f64).max(1.0));
        score = (bin_capacity as f64) + 30.0 + 40.0 * progress;
        // If current bin would leave huge residual, opening new bin looks better.
        if post_residual > 60 && bin_residual != bin_capacity {
            score -= 15.0;
        }
        // Never open a new bin when this empty-bin call is evaluated and item is large.
        if item_size >= 50 {
            score += 10.0;
        }
    }

    // Congestion: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Small jitter-free deterministic tie-break by residual parity class.
    score += ((pr % 3) as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits (post_residual near 0 but usable).
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Pressure term: penalize opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    } else {
        // Reward using existing bins, more when open bin count is high.
        score -= (open_bins_count as f64).sqrt() * 4.0;
    }

    // Last-chance bin: strongly favor filling the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit in the gap, penalize leaving large dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += (post_residual as f64) * 0.5;
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Stream progression: later in stream, be more conservative about new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).

    if next_item_size > 0 {
        let next = next_item_size as f64;
        // Perfect 2-step match: post_residual exactly equals next item size.
        let exact_match = (post_residual as f64 - next).abs();
        if exact_match < 0.5 {
            score -= 40.0;
        } else if post_residual as u32 >= next_item_size {
            // Next item still fits here: mild reward scaled by snugness.
            let snug = 1.0 - (post_residual as f64 - next) / bin_capacity as f64;
            score -= 10.0 + 20.0 * snug;
        } else {
            // Dead space relative to lookahead item: penalize wasted capacity.
            let waste = next - post_residual as f64;
            score += 0.35 * waste;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.1 * post_residual as f64;
    }

    // Compare against mean residual across open bins: filling below-average
    // residual bins is good (they are already tight); leaving a very full bin
    // even tighter is fine, but avoid making an already-large residual worse.
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 0.05 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize the fresh bin moderately so tight
    // existing fits win, but not so much that a hopeless fit is chosen.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Early in the stream, opening bins is cheaper (more future items to
        // use them); late in the stream, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 12.0 * (1.0 - progress);
    }

    // Slight preference to pack into bins among many open bins to keep the
    // active set from growing.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let fit_ratio = item_size as f64 / bin_residual as f64;

    if is_new_bin {
        // Opening a new bin is only attractive when the item fits poorly
        // everywhere else, or when open bins are nearly full on average.
        let avg_crowding = mean_residual / bin_capacity as f64;
        let pressure = (fitting_bins_count as f64).ln().max(0.0);
        score += 120.0
            - 60.0 * (1.0 - fit_ratio.min(1.0))
            - 40.0 * avg_crowding
            - 25.0 * pressure
            + 30.0 * progress;
    } else {
        // Reward tight fits (small post-residual already in base score).
        score -= 15.0 * fit_ratio;

        // Penalize leaving dead space that is too small for typical items.
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        }

        // Lookahead: bonus if the next item could use this bin's post-residual.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 12.0;
            } else if post_residual > 0 && post_residual < next_item_size {
                score += 6.0;
            }
        }

        // Last-chance bin: strongly favor using it to avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }

        // Mild pressure toward filling crowded bins as the stream progresses.
        score += 4.0 * (mean_residual / bin_capacity as f64) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: early on, keep bins roomy; later, tighten packing.
    score += 12.0 * norm_pr * progress * (1.0 - progress);

    // Reward tight fits (small dead space) more strongly as stream progresses.
    score -= 20.0 * (1.0 - norm_pr).powi(3) * (0.3 + 0.7 * progress);

    // Penalize extreme fragmentation: post_residual too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual as u32 - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / cap);
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let mean_fit = mean_residual / cap;
        score = 40.0 + 60.0 * (1.0 - mean_fit) * (1.0 - progress) + 10.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual buckets of 10 (capacity fractions).
    let post_class = post_residual / 10;
    // Dead-space penalty grows super-linearly for small residuals (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else {
        // Integer-division threshold coupling: reward residuals in "useful" classes.
        // Classes 3..=8 (30..=80 residual) are reusable by typical items.
        match post_class {
            0 => score += 60.0,                 // exact fit, fine, no penalty
            1 | 2 => score += 18.0,             // 10..=29 residual: marginal
            3 | 4 | 5 => score -= 6.0,          // 30..=59: good landing zone
            6 | 7 | 8 => score -= 10.0,         // 60..=89: excellent
            _ => {}                             // near-full bin, neutral
        }
    }

    // Modulo-10 harmony between post_residual and next_item_size:
    // if next item divides the post residual into a clean class, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual % next_item_size.max(1);
        if rem == 0 {
            score -= 12.0; // perfect chained fit for lookahead item
        } else if rem < 10 {
            score += 8.0;  // would leave a sliver after next item
        }
        // Penalize if next item cannot fit here at all and this bin is last chance
        if post_residual < next_item_size && fitting_bins_count == 1 {
            score += 25.0;
        }
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 - 20.0 * progress;
        // If mean residual across open bins is large, opening is wasteful.
        score += mean_residual * 0.4;
        // But if the next item is huge and current fit is tight, opening is fine.
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 15.0;
        }
    }

    // Mild pressure to prefer filling bins when many are open.
    score += (open_bins_count as f64) * 0.5;

    // Small tie-breaker: prefer larger item consumption relative to residual.
    score -= (item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // since future items are >= 1 but small gaps waste capacity. Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - (post_residual as f64) * 3.0; // worst at post_residual == 1
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Reward using bins whose residual is already small (consolidation).
    let res_ratio = bin_residual as f64 / bin_capacity as f64;
    score -= 6.0 * (1.0 - res_ratio);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins count.
        score += 10.0 + (open_bins_count as f64) * 2.5;
        // But if existing residuals are all too small relative to item,
        // a new bin becomes attractive: relax penalty when mean residual is low.
        if (mean_residual as u32 as u32) < item_size {
            score -= 18.0;
        }
        // Early in the stream, allow opening bins more freely.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but not perfectly: mild reward.
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space relative to the known next item: penalize.
        score += 10.0;
    }

    // Mild preference for bins with residual near mean (keep balance).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit is better, but weight dead space more when bins are plentiful.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight_weight = 0.6 + 0.6 * progress;
    score = post_residual as f64 * tight_weight;

    // Lookahead: reward when the next item exactly matches the post-residual (perfect 2-chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits: reward proportionally to how little slack remains after both.
            let after_next = post_residual - next_item_size;
            score -= 25.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving a large unusable gap.
            let waste = post_residual as f64;
            score += 0.35 * waste;
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are "precious" tight bins.
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 8.0 * rel;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when item is large and no open bin is a good home.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let poor_fit = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        let open_pressure = if open_bins_count > 0 { (open_bins_count as f64).ln() } else { 0.0 };
        // Penalize opening a new bin generally; reward it for large items when fits are poor.
        score += 30.0 + open_pressure * 10.0 - 45.0 * big_item * poor_fit;
    }

    // Small absolute nudge toward exact fill.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for near-perfect two-item chaining.
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // Penalize creating dead space the next item cannot use.
            let dead = post_residual as f64;
            score += 0.25 * dead;
        }
    }

    // Penalize bins that deviate from the mean residual (keep fleet balanced),
    // but only mildly so tight fits still dominate.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev.abs();

    // Time horizon: early in the stream, be more willing to open new bins
    // (preserve flexibility); late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, expensive late.
        score = 20.0 + 80.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Late stream: extra consolidation pressure on existing bins.
        score -= 10.0 * progress;
    }

    // Mild penalty for very large open-bin counts (encourage reuse).
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Discard-able slivers: residuals below typical min item size are dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic) coupling
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more (dead space cost grows)
    let tightness = 1.0 - norm_pr;
    score += (progress * 40.0) * (1.0 - tightness * tightness) * (1.0 - tightness * tightness) * pr / cap;

    // Penalize waste relative to mean residual (smooth quadratic divergence)
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // smooth reward proportional to how well next item fills remainder
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 15.0 * fill * fill;
        } else {
            // next item won't fit; mild penalty scaled by leftover dead space
            score += 0.1 * pr * (1.0 - progress);
        }
    }

    // Mild penalty for opening a new bin when many bins are open and residual is large
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64 - 20.0 * progress;
        // new bin is only attractive if current item leaves big unusable gap elsewhere
        score += item_size as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover modulo small divisors
    let pr = post_residual;
    let m4 = (pr % 4) as f64;
    let m5 = (pr % 5) as f64;
    let m10 = (pr % 10) as f64;
    // Penalize leftovers with "ugly" residues (hard to fill later)
    score += 0.8 * m4 + 0.6 * m5 + 1.2 * m10;

    // Integer-division thresholds on post_residual: tiny dead space is good
    if pr <= 2 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 12.0;
    } else if pr <= 30 {
        score -= 4.0;
    } else if pr > 60 {
        score += 6.0;
    }

    // Fraction of capacity wasted
    let waste_frac = post_residual as f64 / cap;
    score += 30.0 * waste_frac * waste_frac;

    // Perfect / near-perfect fit reward
    if pr == 0 {
        score -= 80.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        let diff = pr - next_item_size;
        if diff == 0 {
            score -= 70.0;
        } else if diff <= 10 {
            score -= 30.0;
        } else if diff <= 25 {
            score -= 12.0;
        }
    } else if next_item_size > pr {
        // next item cannot use this leftover: penalize large leftover mildly
        score += 0.15 * (pr as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only
    // when open bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score = 0.55 * cap + 25.0 * crowded - 10.0 * (mean_residual / cap);
        // if next item is large, opening fresh bin is more attractive
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Mild stream-progression regularization
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 2.0 * (progress - 0.5);

    // Tie-break toward bins with residual close to mean (balance)
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: tiny gaps that no item (min size 1) can use are worst,
    // but gaps below the smallest typical item are nearly dead.
    let dead_threshold = 10.0_f64.min(cap * 0.1);
    if post > 0.0 && post < dead_threshold {
        score += (dead_threshold - post) * 6.0; // near-dead gaps heavily penalized
    }
    if post == 0.0 {
        score -= 25.0; // perfect fit strongly rewarded
    }

    // Reward tight fits relative to bin state
    let tightness = 1.0 - (post / cap);
    score -= tightness * 12.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is good
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        let gap = post_residual - next_item_size;
        score -= 10.0 - (gap as f64) * 0.15;
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate large residuals)
    score += (mean_residual - bin_residual as f64) * 0.08;

    // New-bin candidate: only attractive when current fit is poor or no bins fit well
    if bin_residual == bin_capacity {
        let poor_fit = post > cap * 0.5;
        if poor_fit || (fitting_bins_count == 0) {
            score -= 30.0;
        } else {
            score += 20.0; // keep using existing bins when fit is decent
        }
    }

    // Late-stream urgency: close out bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on remaining slack.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use leftover space; penalize large leftovers.
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 10.0;
    }

    // Last chance: if this is the only bin that fits, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize bins that deviate from the mean residual (keep bin states homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Prefer fuller bins relative to mean (best-fit flavor).
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Time horizon: early in the stream, opening new bins is cheaper; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, unattractive late.
        score = bin_capacity as f64 * (1.0 - 0.5 * progress) - 5.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    } else {
        score -= 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post_residual), non-linearly
    let mut score = pr as f64;

    // Smooth polynomial coupling with stream progress:
    // early on, waste matters less (score dampened); later, waste is penalized more.
    let progress_penalty = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0 * progress;
    score *= progress_penalty;

    // Reward very small post residuals super-linearly (good fits)
    score -= (1.0 - x) * (1.0 - x) * item_size as f64 * 0.5;

    // Penalize dead space: residuals too small for typical future items
    let dead = if x > 0.0 { (x - 0.15).abs() } else { 0.0 };
    score += dead * dead * cap * 0.3 * progress;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Prefer bins whose residual is below mean (consolidating waste)
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 10.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty on open bin count pressure early (encourage reuse vs sprawl)
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // integer-division buckets of capacity fractions (1/8 granularity).
    let class = post_residual / (bin_capacity / 8).max(1);
    // Dead-space classes: tiny leftovers (classes 0..=2) are nearly unusable
    // for items >= 10, penalize them strongly.
    if class <= 2 {
        score += 45.0 - 12.0 * class as f64;
    } else if class <= 4 {
        score -= 8.0;
    } else {
        score -= 15.0;
    }

    // Modulo coupling: leftovers that are exact multiples of common item
    // granularities are more likely reusable by future items.
    let pr = post_residual;
    if pr % 10 == 0 {
        score -= 6.0;
    }
    if pr % 5 == 0 {
        score -= 3.0;
    }
    if pr != 0 && (pr % 25 == 0 || pr % 20 == 0) {
        score -= 5.0;
    }

    // Lookahead: reward if the next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect pairing
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / cap_f);
        } else {
            // next item cannot use this leftover: mild penalty scaled by waste
            score += 6.0 * ((next_item_size - pr) as f64 / cap_f);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer tightest fit overall (best-fit core with fraction weighting).
    score -= 20.0 * (1.0 - (item_size as f64 / bin_residual.max(1) as f64));

    // Progress-aware new-bin control: early in the stream, opening a new bin
    // is cheap; late, consolidation matters.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced early, raised late.
        score = cap_f * 0.5 + 40.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size / 2 {
            score -= 5.0;
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean.
        score -= 4.0 * (mean_residual - bin_residual as f64) / cap_f;
        // Crowding: many open bins -> favor filling existing ones.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold anything are heavily penalized.
    // Since item sizes are >= 1 and unknown distribution, treat gaps < 10 as near-dead,
    // with a steep quadratic surcharge as post_residual approaches 0.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 25.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Waste ratio: penalize proportionally to how much of the bin remains unused.
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Open-bin pressure: encourage consolidation when many bins are open.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that fits the item, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // Mean-residual coupling: prefer bins deviating favorably from the mean residual
    // (tighter-than-average bins get priority to close them out).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late-stream tightening: as the stream progresses, be more greedy about space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    // New-bin candidate: make the empty bin mildly unattractive unless current bins
    // are very fragmented (high open_bins_count with small mean residual).
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        // Perfect 2-chain match gets strong bonus
        score -= 30.0 * (1.0 - diff as f64 / bin_capacity as f64);
    }

    // Penalize post_residual too small for any future item (dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when lookahead chain is possible
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 40.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            penalty -= 10.0; // a fresh bin can host a perfect pair
        }
        if fitting_bins_count <= 1 {
            penalty -= 45.0; // opening new bin is fine when no good alternative
        }
        score += penalty * (0.5 + 0.5 * progress);
    }

    // Mild preference for compacting many open bins
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early stream -> be greedy with tight fits; late stream -> consolidate.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: residuals too small to likely host future items are wasted.
    // Penalize post_residual that is "useless" (small but nonzero) more than near-full bins.
    if post_residual > 0 {
        let useless = (post_residual as f64).powf(1.6) / (bin_capacity as f64).powf(0.6);
        score += 0.9 * useless;
    }

    // Perfect fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 25.0 * (1.0 + 0.5 * t);
    }

    // Lookahead: reward if the next item fits into the resulting residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 8.0 + 0.15 * slack_after_next as f64;
        } else {
            // Penalize creating residual that just barely fails to host the next item.
            let miss = next_item_size - post_residual;
            if miss <= 10 {
                score += 6.0 + 0.5 * miss as f64;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.5 {
            score -= 20.0 + 15.0 * fill_ratio;
        } else {
            score -= 6.0;
        }
    }

    // Crowding: when many bins are open, favor tightening existing bins to close them.
    let crowd = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / bin_capacity as f64);
    score -= 0.05 * crowd * (1.0 - t * 0.5);

    // Prefer bins whose residual is close to the item (snug fit) beyond raw post_residual.
    let snug = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score += 10.0 * snug * snug;

    // New-bin candidate handling: an empty bin is a fallback; make it attractive only
    // when the fit into it is proportionally better than what tight bins offer,
    // but discourage spawning bins early in the stream.
    if bin_residual == bin_capacity {
        let usage = item_size as f64 / bin_capacity as f64;
        let base = 0.55 * bin_capacity as f64; // neutral threshold
        score = base + (1.0 - usage) * 40.0 - 12.0 * t - if fitting_bins_count <= 1 { 18.0 } else { 0.0 };
        // If the item is large, opening a fresh bin is often good.
        if usage > 0.7 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: prefer tight fits via non-linear polynomial in normalized post-residual.
    let x = pr / cap; // in [0,1]
    let mut score = 60.0 * x * x * x - 30.0 * x * x + 4.0 * x;

    // Smooth progress coupling: early stream tolerates slack, late stream punishes it.
    score += (0.5 - progress) * 20.0 * x * (1.0 - x);

    // Penalize dead space relative to mean residual of open bins.
    score += (pr - mean_residual).max(0.0) * 0.3 * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + 30.0 * (1.0 - x);
    }

    // Lookahead: reward if next item can fit into post-residual.
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        score -= fits_next * 12.0 * (1.0 - progress);
    } else {
        // Last item: minimize waste aggressively.
        score += 10.0 * x;
    }

    // New-bin candidate: penalize slightly when open bins exist, more so early.
    if is_new_bin {
        score += 8.0 + 15.0 * (1.0 - progress) + (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: capacity fractions (C/4, C/2, 3C/4)
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let three_quarter = quarter * 3;

    // Perfect fit: strongly reward
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Post residual in harmonic sweet spots (fits quarter-class items)
    if post_residual == half {
        score -= 60.0;
    } else if post_residual == quarter || post_residual == three_quarter {
        score -= 30.0;
    }

    // Dead space: residuals that no plausible item (1..100) can use well
    if post_residual > 0 && post_residual < 10 {
        score += 250.0; // tiny unusable sliver
    } else if post_residual < quarter {
        score += 40.0; // small dead zone
    }

    // Lookahead coupling: does next item fit into post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic class match: exact / half / quarter couplings
            if next_item_size == post_residual {
                score -= 400.0;
            } else if post_residual >= next_item_size {
                let slack = post_residual - next_item_size;
                if slack == half || slack == quarter {
                    score -= 120.0;
                }
                score -= (slack as f64).min(80.0) * 0.5;
            }
        } else {
            // next item won't fit here; penalize proportionally
            score += 30.0;
        }
    } else {
        // last item: prefer tightest fit
        score -= 200.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin should score worse than decent fits
    if bin_residual == bin_capacity {
        // base cost of a fresh bin, reduced late in stream or when bins are crowded
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 90.0;
        new_bin_cost -= 40.0 * progress;
        if open_bins_count == 0 {
            new_bin_cost -= 200.0; // must open a bin
        }
        // if mean residual is high, prefer using existing bins
        new_bin_cost += (mean_residual / cap).min(1.0) * 60.0;
        score += new_bin_cost;
    }

    // Prefer bins with residual close to item (tight packing) via integer division class
    let class_fit = (bin_residual - item_size) / 10; // decade class of leftover
    score -= (10 - class_fit.min(10)) as f64 * 2.0;

    // Mild preference to fill fuller bins first
    score -= (bin_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 30.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
    }
    // Penalize if post_residual is small but nonzero and cannot host next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (5.0 + 10.0 * progress);

    // New-bin candidate: penalize so it is chosen only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 250.0 + mean_residual * 2.0;
    }

    // Slight preference for filling tighter (lower residual) bins.
    score += (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference for tight fits relative to mean residual
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect chain: post_residual == next_item_size
            score -= 45.0 * (-gap / 8.0).exp();
            // Penalize leaving a gap that next item cannot use
            if gap > 0.0 {
                score += 0.5 * gap;
            }
        } else {
            // Next item cannot fit in this bin's leftover: mild penalty scaled by overflow
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.25 * overflow;
        }
    }

    // Reward pairing when the leftover after the next item is also small
    if next_item_size > 0 && post_residual >= next_item_size {
        let two_step_left = (post_residual - next_item_size) as f64;
        score -= 12.0 * (-two_step_left / 10.0).exp();
        if two_step_left < 10.0 {
            score -= 8.0; // near-perfect two-item packing, dead space eliminated
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when open bins exist and could still fit the item
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            let progress = step_index as f64 / total_items.max(1) as f64;
            // New bins are more acceptable early (more future items to fill them)
            let new_bin_penalty = 30.0 * (1.0 - 0.5 * progress);
            score += new_bin_penalty;
            // If other bins fit, opening new is wasteful
            if fitting_bins_count > 0 {
                score += 15.0;
            }
        } else {
            score -= 10.0; // first bin is free
        }
    }

    // Discard bins whose residual becomes unusable dead space (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect closure
    }

    // Slight preference for bins tighter than average before placement
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post_residual (tight fit), scaled softly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 25.0;

    // Penalize creating dead space that likely cannot fit future items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_threshold = 10.0 + 8.0 * progress;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 2.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't chain here; slight penalty if post_residual is tiny.
        score += 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins with large mean residual -> prefer filling existing bins.
    if open_bins_count > 2 {
        score -= (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln() * 3.0;
    }

    // New empty bin candidate: penalize unless it's a great fit for large items
    // or current bins are nearly full.
    if bin_residual == bin_capacity {
        let big_item_bonus = if item_size >= 60 { 20.0 } else { 0.0 };
        let scarcity = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        let crowded = if mean_residual < 15.0 { 15.0 } else { 0.0 };
        score += 45.0 - big_item_bonus - scarcity - crowded;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Base: prefer small post-residual, with non-linear polynomial coupling to progress
    let mut score = post;
    score += 30.0 * x * x * (0.5 + progress);
    score -= 12.0 * x * (1.0 - x) * (1.0 - progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - x;
    score -= 8.0 * tightness * tightness * progress;

    // Lookahead: penalize if next item can't use the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        if nx > x {
            score += 10.0 * (nx - x) * (1.0 + progress);
        } else {
            score -= 6.0 * (x - nx) * (0.5 + progress);
        }
    }

    // Last-chance bonus: only fitting bin should be favored
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Slight penalty for opening a new bin when many bins are open and residuals are high
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (mean_residual / cap) * (1.0 - progress);
    }

    // Penalize bins deviating from mean residual (balance preservation)
    score += 2.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small classes are "dead space".
    let class = post_residual / 10; // integer division thresholds 0..9
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Penalize tiny residuals (waste), reward residual sizes that future items can reuse.
    match class {
        0 => score += 40.0,                    // post_residual == 0: perfect fill
        1 => score += 25.0,                    // 1..9: nearly unusable
        2 => score += 12.0,                    // 10..19: only fits smallest items
        3 => score -= 2.0,                     // 20..29: usable
        4 => score -= 6.0,                     // 30..39
        5 => score -= 8.0,                     // 40..49: sweet spot for mid items
        6 => score -= 7.0,                     // 50..59
        7 => score -= 4.0,                     // 60..69
        8 => score -= 1.0,                     // 70..79
        _ => {}                                // 80..99: still roomy
    }

    // Harmonic coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward lookahead fit, scaled by how tightly it packs.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 + 8.0 * tightness;
        } else {
            // Next item won't chain here; mild penalty, worse late in stream.
            score += 4.0 + 6.0 * progress;
        }
        // Modulo harmony: next item leaves a class-0/1 residual after landing here.
        let chained = post_residual - next_item_size;
        if next_item_size <= post_residual && chained % 10 == 0 {
            score -= 5.0;
        }
    } else {
        // Last item: pure waste minimization.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize unless open bins are congested
    // or this bin would be a poor fit (large post_residual).
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / 8.0;
        let waste = post_residual as f64 / bin_capacity as f64;
        score = 30.0 + waste * 60.0 - congestion * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0; // fresh bin gives lookahead room
        }
    }

    // Mild preference toward bins below mean residual (balance load).
    score += (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (items >= 1, but practically small gaps < 10
    // are near-unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits: waste ratio of the bin after placement.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: discourage scattering across many bins unless the
    // fit is good; encourage closing out nearly-full bins.
    score += 2.0 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the current item would leave a large dead gap in every open bin.
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin.
        score = bin_capacity as f64 * 0.45;
        // If the item perfectly or near-perfectly fills a new bin, prefer it.
        let new_post = bin_capacity - item_size;
        if new_post < 10 {
            score -= 30.0;
        }
        // If no existing bin fits well (high mean residual spread), fresh
        // bin becomes more attractive.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward leaving that gap; otherwise small residual is risky.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > post_residual {
            score += 8.0; // gap likely dead relative to lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 400.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits exactly-ish: excellent chaining.
            score -= 250.0 * (1.0 - diff / 100.0);
        } else {
            // Next item won't fit here; penalize leaving a gap it almost fits.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap <= 15.0 {
                score += 60.0 * gap;
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 1.5;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize new empty bins unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        let large = (item_size as f64 / bin_capacity as f64) > 0.6;
        if large {
            score -= 50.0;
        } else {
            score += 150.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally to fill ratio achieved.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fill * fill;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.3 * next_item_size as f64;
        }
        // If next item would exactly fill post residual, big bonus.
        if next_item_size == post_residual {
            score -= 60.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize bins whose residual deviates from the mean residual (keep residuals homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.4 * dev;

    // Early in the stream, prefer consolidating into fewer bins; later, allow spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: neutral-ish baseline, slightly penalized so it's only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in stream, opening new bins is less costly than dead space.
        score -= 25.0 * progress;
    }

    // Many open bins: mild penalty for using existing bins with large residuals (fragmentation risk).
    if open_bins_count > 4 {
        score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress (smooth, in [0,1])
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear polynomial coupling of post_residual with progress.
    // Squared and cubic terms create smooth curvature: early in the stream
    // small residuals are tolerated, late in the stream we strongly prefer
    // bins whose post_residual is small (tight packing).
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (0.5 + 2.0 * progress * progress) * bin_capacity as f64;
    score += coupling;

    // Cubic interaction: penalizes large leftover space more aggressively
    // as the stream matures (smooth in progress, no piecewise branches).
    score += pr_norm * pr_norm * pr_norm * 20.0 * progress;

    // Reward tight fits smoothly: post_residual near zero reduces score.
    let tight = ((bin_capacity as f64 - pr) / bin_capacity as f64).powi(3);
    score -= 8.0 * tight * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // (avoids opening a new bin unnecessarily).
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        // Smooth penalty when many bins compete: prefer bins that are fuller
        // relative to the mean residual.
        let mean_gap = (mean_residual - bin_residual as f64) / bin_capacity as f64;
        score -= 4.0 * mean_gap;
    }

    // Lookahead coupling: if the next item fits smoothly into the post
    // residual, reward this placement (smooth quadratic affinity).
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_frac = next_item_size as f64 / post_residual as f64;
        score -= 5.0 * fit_frac * (1.0 - fit_frac) * 4.0 * (1.0 - progress);
    } else if next_item_size > post_residual {
        // Next item won't fit here: mild penalty growing with progress.
        score += 3.0 * progress;
    }

    // New-bin candidate handling: empty bin gets a mild fixed penalty so it
    // is only chosen when no open bin scores better (e.g. poor fits).
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
    }

    // Slight preference to consolidate across fewer open bins.
    score += 0.15 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residues in "useful" bands.
    // Residues <= 9 are nearly dead space; residues that are exact capacity
    // fractions (25, 50, 75, 100) are reusable by typical items.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit, best outcome
    } else if pr <= 9 {
        score += 12.0; // dead space penalty
    } else {
        // reward residues divisible into common classes
        if pr % 25 == 0 {
            score -= 8.0;
        } else if pr % 10 == 0 {
            score -= 4.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead: strongly prefer bins where the next item also fits here.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0 + (next_item_size as f64) * 0.1;
        // extra reward if next item leaves another clean residue
        let pr2 = pr - next_item_size;
        if pr2 % 10 == 0 || pr2 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residue -> dead space likely
        score += (next_item_size as f64).min(30.0) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, keep the item here
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item fits open bins very poorly (large post_residual waste) or when
    // there are few open bins and the item is large.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin: its full residual
        score = (bin_capacity - item_size) as f64;
        // penalize opening new bins when existing bins fit fine
        if fitting_bins_count > 0 {
            let best_possible = post_residual.min(20) as f64;
            score += 5.0 - best_possible * 0.2;
        }
        // large items early: new bin can be attractive to keep small bins free
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 50 && open_bins_count < 4 {
            score -= 8.0 * (1.0 - progress);
        }
        // if next item is small and current item leaves big residue, new bin ok
        if next_item_size > 0 && next_item_size < 20 && (bin_capacity - item_size) >= 40 {
            score -= 4.0;
        }
    }

    // Slight preference to fill tighter bins among equals: compare to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Harmonic threshold coupling: integer division classes of residual vs item.
    let cls = (post_residual / item_size.max(1)) % 4;
    score += match cls {
        0 => -3.0,
        1 => 1.0,
        2 => -1.0,
        _ => 2.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize unusable dead space: gaps too small for the minimum item (1..=10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Reward exact fits heavily.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space that cannot fit the lookahead item is worse if lookahead is small.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins are open
    // or when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 35.0 + 2.0 * open_bins_count as f64 + 5.0 * fit_pressure;
        // Slightly cheaper to open a new bin late in the stream? No — keep constant pressure.
    }

    // Mild bonus for bins tighter than the mean residual (good consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Prefer filling nearly-full bins.
    score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining: next item fits exactly into this bin's leftover.
            let chain = next_item_size as f64;
            let perfect = if post_residual == next_item_size { 18.0 } else { 0.0 };
            let partial = (chain / (bin_capacity as f64)) * 8.0;
            score -= perfect + partial;
        } else {
            // Dead space relative to the next item: penalize proportionally to waste.
            let waste = (post_residual as f64) - (next_item_size as f64);
            let waste_frac = waste / (bin_capacity as f64);
            score += waste_frac * 12.0;
        }
    } else {
        // Last item: strongly prefer the tightest possible fit.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.05;
    }

    // --- Mean-residual coupling ---
    // If this bin's post-residual is far below the mean, it's a good consolidation.
    let post_f = post_residual as f64;
    let mean_gap = mean_residual - post_f;
    if mean_gap > 0.0 {
        score -= mean_gap * 0.15;
    } else {
        // Creating a residual much larger than the mean leaves an outlier bin.
        score += (-mean_gap) * 0.10;
    }

    // --- Last-chance bonus ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only open bin that fits; avoid opening a new bin unless fit is terrible.
        score -= 10.0;
        if post_residual == 0 {
            score -= 5.0; // perfect fill of the last fitting bin
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin starts with residual = capacity; make it unattractive unless
        // the item is large relative to capacity or no good open option exists.
        let item_frac = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize new bins when many bins are open and item is small.
        score += 25.0 - item_frac * 20.0 - progress * 5.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits, new bin is fine
        }
    }

    // --- Perfect fill reward ---
    if post_residual == 0 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Small tie-breaker favoring bins that were already partially filled.
    score += (bin_residual as f64 / bin_capacity as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual <= 50 {
        score -= 8.0; // usable leftover
    } else {
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
            // extra reward for near-exact chain
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * chain_fit;
        } else {
            score += 6.0;
        }
    } else {
        // Last item: strongly prefer filling as much as possible.
        score -= 40.0 * (item_size as f64 / bin_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: fresh empty bin should only win when it's
    // genuinely useful (early stream or no good fits exist).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = (fitting_bins_count as f64).recip();
        let openness = (1.0 - progress) * 30.0 + desperation * 20.0;
        score += 35.0 - openness; // becomes competitive only when openness is high
        // never open a new bin for a small item late in the stream
        if item_size < 30 && progress > 0.5 {
            score += 40.0;
        }
    }

    // Global state coupling: many open bins with high mean residual ->
    // prefer consolidating into bins with above-average residual.
    if bin_residual as f64 > mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }
    score += 0.05 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Mild time pressure: as stream progresses, prefer fuller packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer small post_residual, with quadratic sharpening of tight fits.
    let mut score = pr + 8.0 * (pr / cap) * (pr / cap) * cap * 0.01;

    // Smooth non-linear coupling of tightness with stream progress:
    // late in the stream, tight fits matter more; early, flexibility matters.
    let tightness = 1.0 - pr / cap; // 0..1, 1 = perfect fit
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize large wasted space quadratically (dead space is unusable).
    score += 0.004 * pr * pr;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    } else {
        // Mild penalty when many bins fit (item is easy to place; save flexible bins).
        score += 1.5 * ((fitting_bins_count as f64 - 1.0).min(6.0));
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            // post_residual too small for next item: penalize proportionally to waste.
            score += 3.0 * (nxt - pr) / cap * (1.0 + progress);
        }
    }

    // Deviation from mean residual: prefer bins that reduce residual dispersion smoothly.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Mild penalty for opening a brand-new bin when open bins exist and fit is possible.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 5.0 + 8.0 * (1.0 - progress);
    }

    // Slight preference to consolidate into fewer bins as the stream matures.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that fall into
    // "friendly" residue classes likely to be filled by small future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 are highly reusable
    let m10 = post_residual % 10;
    score -= match m10 {
        0 => 40.0,
        1 | 9 => 12.0,
        2 | 8 => 5.0,
        _ => 0.0,
    };

    // Modulo-4 sub-harmonic: fine granularity reusability
    if post_residual % 4 == 0 {
        score -= 8.0;
    } else if post_residual % 2 == 0 {
        score -= 3.0;
    }

    // Integer-division thresholds on post_residual: dead-space bands
    let band = post_residual / 10; // 0..10 bands
    score += match band {
        0 => 0.0,                    // near-perfect fit
        1 => 5.0,                    // 10-19: awkward sliver
        2 | 3 => 2.0,                // 20-39: usable
        4 | 5 | 6 => 0.0,            // 40-69: good
        _ => 3.0,                    // 70+: mostly empty bin, wasteful
    };

    // Lookahead coupling: does next item's harmonic class match post_residual?
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            // next item fits exactly or harmonically
            if (pr as u32) % next_item_size == 0 {
                score -= 35.0;
            } else if ni > pr * 0.6 {
                score -= 15.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 6.0 + (ni - pr) / cap * 20.0;
        }
        // Harmonic gcd coupling: shared divisor between residual and next item
        let mut g = post_residual;
        let mut b = next_item_size;
        while b != 0 { let t = g % b; g = b; b = t; }
        if g > 1 {
            score -= (g as f64).min(20.0) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // Many open bins: prefer tightening existing bins over spreading
    score += open_bins_count as f64 * 1.5;

    // Mean residual alignment: prefer bins whose residual is below mean
    // (consolidating waste into fewer bins)
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Progress-adaptive tightness pressure
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * (0.05 + 0.10 * progress);

    // New-bin candidate: only attractive when item is large and no open bin
    // offers a decent fit (residual would leave a fresh, flexible bin)
    if bin_residual == bin_capacity {
        let fresh_penalty = 55.0 - (item_size as f64 / cap) * 40.0;
        score += fresh_penalty;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A gap is "dead" if no future item (min size 1) can plausibly use it well;
    // gaps below ~15 are almost always waste.
    let gap = post_residual as f64;
    if post_residual < 15 {
        score += 120.0 + (15.0 - gap) * 8.0; // dead-space penalty
    } else if post_residual < 30 {
        score += 25.0 + (30.0 - gap) * 2.0; // semi-dead gap penalty
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = post_residual - next_item_size;
        if next_fit < 15 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    }
    // Penalize leaving a gap that blocks the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // New-bin candidate: only attractive when existing bins are mostly full
    // or the item fits nothing well.
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score = 60.0 + mean_fullness * 40.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if post_residual == 0 {
            score = 0.0; // unreachable, keep safe
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight superlinear penalty
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        let lookahead_reward = if diff == 0 {
            40.0 // perfect match: next item fills this bin exactly
        } else if next_item_size <= post_residual {
            25.0 - (diff as f64) * 0.35 // next item fits here: strong reward scaled by closeness
        } else {
            0.0
        };
        score -= lookahead_reward;
    }

    // Compare against mean residual: bins tighter than average are good targets
    score += (post_residual as f64 - mean_residual) * 0.30;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it attractive only when current bin fits are poor.
    // Empty bin baseline: post_residual = capacity - item_size, naturally high score;
    // add a penalty unless lookahead suggests a good chain.
    if bin_residual == bin_capacity {
        let mut newbin_bonus = 0.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
            newbin_bonus = 30.0 - diff as f64 * 0.4;
        }
        // Penalize new bin generally; reward if it enables a perfect 2-step chain
        score += 8.0 - newbin_bonus;
        // Late in the stream, avoid opening new bins with residual space around
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 6.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item (<=10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight preference for bins that will be closed out soon (fewer open bins better)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (small post_residual) more aggressively.
    let tightness = 1.0 - post / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never be used by typical items (post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else if gap < 10 {
            score -= 18.0;
        } else {
            score -= 6.0;
        }
    }
    // If next item cannot fit in the post residual, mild penalty proportional to leftover waste.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 - post) / cap;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is costly unless the item is large
    // and fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score += 8.0;                       // base cost of opening a bin
        score -= 10.0 * fill_ratio;         // large items justify new bins
        if fitting_bins_count > 3 {
            score += 6.0;                   // many alternatives: keep using open bins
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 4.0;                   // room left for the next item
        }
    }

    // Global state coupling: prefer filling bins when mean residual is low (bins nearly full).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (mean_residual / cap) * (1.0 - t);

    // Prefer bins with residual close to item_size (perfect-ish fits) beyond raw post_residual.
    let over = (bin_residual as f64 - item_size as f64) / cap;
    score += 20.0 * over * over * 0.1;

    // Slight preference for bins that are already well-filled (less residual overall).
    score += 0.03 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: reward small post_residual non-linearly,
    // scaled by stream progress (tighten packing later in the stream).
    score -= 30.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Penalize dead space that is too small to be useful (non-linear valley).
    let dead = norm_pr * (1.0 - norm_pr);
    score += 40.0 * dead * dead * (1.0 - progress);

    // Lookahead: reward residual that can still fit the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fit_gap = norm_pr - nxt;
        if fit_gap >= 0.0 {
            score -= 15.0 * (1.0 - fit_gap).powi(2);
        } else {
            score += 20.0 * fit_gap * fit_gap;
        }
    }

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when bin is far below mean residual (fragmentation tendency).
    score += 0.1 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize slightly so it's chosen only for poor fits,
    // with penalty easing late in the stream.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + norm_item * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 5 classes.
    let class = post_residual / (bin_capacity / 5).max(1);
    // Reward low classes (tight fits) with multiplicative discounts.
    match class {
        0 => score -= 40.0,
        1 => score -= 20.0,
        2 => score -= 8.0,
        3 => score += 6.0,
        _ => score += 12.0,
    }

    // Modulo-based dead-space detection: residuals that few item sizes can fill.
    // Items 1..=100, so residual r is "usable" if a plausible item (>= ~10) fits.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // unusable sliver
    }

    // Perfect-fit harmonic: post_residual divisible by common item granularity (5/10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: penalize if next item cannot use the post residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 8.0;
        } else if post_residual - next_item_size < 10 {
            score -= 12.0; // next item would nearly exhaust the bin
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: default is costly; only attractive when current fits are bad.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.35 * mean_residual - (open_bins_count as f64).min(10.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // pairing large items in fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
    }

    // Mild stream-progression regularization: consolidate early, spread late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (post_residual as f64 / cap) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * open_bins_count as f64 * (0.5 + progress);
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins tighter than average (good packing density).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: favor bins whose leftover could host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
