pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good; amplify non-linearly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize large dead space quadratically when residual becomes unusable (< smallest plausible item).
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else {
        score += (post_residual as f64) * (post_residual as f64) * 0.004;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty proportional to leftover mismatch.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: many open bins with high mean residual -> prefer consolidating
    // into fuller bins; penalize spreading into emptier ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let emptiness = (bin_residual as f64 - mean_residual).max(0.0);
    score += emptiness * (0.02 + 0.08 * progress) * (open_bins_count as f64).sqrt();

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream.
        score += 30.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // forced new bin
        } else if post_residual < 15 {
            // Opening a fresh bin keeps a near-perfect residual for future items.
            score -= 5.0;
        }
        // Discourage new bins when many open bins already have slack.
        score += 0.5 * open_bins_count as f64;
    }

    // Slight preference for bins whose residual is a "nice" multiple of common item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    let mut score = post * (1.0 + 0.5 * progress) - 0.6 * progress * x * cap;

    // reward near-perfect fits more strongly as stream progresses
    score -= (1.0 - x).powi(3) * cap * (0.4 + 0.8 * progress);

    // penalize dead space that can't fit typical future items
    if post > 0.0 {
        score += 8.0 * (1.0 - (post / item_size.max(1) as f64).min(1.0)) * (1.0 - progress);
    }

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // lookahead: favor bins whose post-residual fits next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += 3.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // new-bin candidate: only attractive when fits are poor
    if bin_residual == bin_capacity {
        score = cap - (1.0 - x) * cap * (0.5 + 0.5 * progress)
            + if fitting_bins_count <= 1 { 0.0 } else { 12.0 + 10.0 * (1.0 - progress) };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // residue classes (dead space) are penalized; perfectly tight fits rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Tight fit reward: leftover is a small harmonic fraction of capacity.
    for k in [2u32, 3, 4, 5, 8, 10] {
        let frac = cap / k as f64;
        if (pr - frac).abs() < 2.0 {
            score -= 6.0 / k as f64;
        }
    }

    // Penalize awkward leftovers via modulo classes.
    if post_residual > 0 && post_residual % 7 == 0 {
        score += 2.0; // 7-class residues historically hard to fill
    }
    if post_residual >= 1 && post_residual <= 9 {
        score += (10 - post_residual) as f64 * 1.5; // tiny dead space penalty
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            score -= 3.0;
            // harmonic match: post_residual - next is a nice fraction
            let gap = post_residual - next_item_size;
            if gap % 5 == 0 && gap <= 25 {
                score -= 4.0;
            }
        } else {
            score += 2.0; // next item can't use this bin's leftover
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let threshold = 0.28 + 0.15 * progress;
        if crowding < threshold {
            score += 40.0; // keep using open bins
        } else {
            score -= 8.0; // open bins are fragmented; fresh bin is fine
        }
    }

    // Mild preference for filling fuller bins as stream progresses.
    score -= (1.0 - pr / cap) * (3.0 + 3.0 * step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to ever fit a future
    // item (min item size 1, but practically small gaps < 10 are wasted).
    let dead = (post_residual as f64).min(9.0);
    score += 6.0 * dead;

    // Reward tight fits (waste-free placement).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize the alternative implicitly by rewarding this).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins unless
    // the fit is genuinely good.
    score += 0.35 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += ((bin_residual as f64 - item_size as f64) / bin_capacity as f64) * 8.0;

    // Lookahead: if the next item fits exactly into the post-residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if post-residual can't fit the next item but is still smallish.
    if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Make it attractive only when the fit in open bins would leave a bad gap.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progression.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 8.0 * progress;
        // But if the item is large relative to capacity, a fresh bin is natural.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits: heavily reward small post_residual.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post_residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chaining: next item exactly fills leftover space.
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            // Penalize large leftover after the hypothetical next placement (dead space).
            score += 0.15 * slack;
        } else {
            // Next item cannot follow into this bin: penalize proportionally to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.05 * overshoot;
        }
    }

    // Compare against mean residual: bins with residual far below mean are precious tight fits;
    // placing here when it fits tightly is good, but avoid wasting a tight bin on a loose fit.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        // This bin is tighter than average: extra penalty for leaving large post_residual.
        score += 0.25 * dev * (post_residual as f64 / bin_capacity as f64);
    } else {
        // Looser than average bin: mild reward for consuming its slack.
        score += 0.10 * dev;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
        // But if the fit is very loose, reduce the last-chance bonus.
        score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item_size.
    // Penalize opening a new bin unless current bins are nearly all full or fit is bad.
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            1.0
        };
        // Low mean residual => open bins are nearly full => opening a bin is fine.
        score += 15.0 * pressure;
        // Early in the stream, slightly discourage hoarding bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 3.0 * (1.0 - progress);
    }

    // Late-stream consolidation: prefer filling existing bins as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: residuals that are too small to hold anything useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item also fits into the post-residual (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving a residual that blocks the next item but is still wasted.
        score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins would waste badly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when existing residuals are large/wasteful.
        let waste = mean_residual - item_size as f64;
        score = item_size as f64 + 35.0;
        if waste > 20.0 {
            score -= (waste - 20.0).min(30.0);
        }
        // Early in the stream, opening bins is cheaper (build a pool for future pairing).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If many bins already open, discourage further expansion.
        score += 2.0 * (open_bins_count as f64).sqrt();
    } else {
        // Mild preference for filling bins with below-average residual (balance avoidance).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Prefer bins with larger residuals for large items to preserve tight bins.
        if item_size > 60 && bin_residual < item_size + 20 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;                      // normalized post residual
    let norm_item = item_size as f64 / cap;      // normalized item size

    // Base: prefer small post residual, with smooth non-linear (quadratic) penalty
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr);

    // Non-linear coupling with stream progress: later in the stream,
    // tighten bins more aggressively (favor small post_residual even more)
    let progress_coupling = progress * norm_pr * norm_pr * 2.0;
    score += progress_coupling;

    // Reward tight fits (near-perfect fill) with smooth exponential-like term
    score -= 1.5 * (1.0 - norm_pr).powi(3);

    // Penalize creating dead space that cannot fit a typical item:
    // smooth interaction between post_residual and item size
    let dead_space_risk = (norm_pr / (norm_item + 0.1)) * (norm_pr - norm_item).max(0.0);
    score += 0.5 * dead_space_risk;

    // Lookahead: reward if next item fits in the post residual (smooth term)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_next = (norm_pr - nx).max(0.0) / (norm_pr + 0.1);
        score -= 0.8 * fit_next * (1.0 - fit_next) * 4.0; // peaks when next item just fits
        // Penalize post residual that fits neither a plausible future item
        score += 0.3 * (1.0 - (norm_pr / (nx + norm_pr + 0.01)));
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 2.0;
    } else {
        // Mild penalty when many alternatives exist and fit is loose
        score += 0.1 * (fitting_bins_count as f64).ln().max(0.0) * norm_pr;
    }

    // Coupling with mean residual: avoid bins deviating far from the mean
    // when the mean is large (keeps a spread of usable residuals)
    let dev = (mean_residual - pr) / cap;
    score += 0.2 * dev * dev * (1.0 - progress);

    // New-bin candidate: smooth bias so a fresh bin is chosen only when
    // existing fits are poor (post residual too large relative to item)
    if bin_residual == bin_capacity {
        score = 0.9 + 0.5 * norm_item + 0.3 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (dead space in low harmonic classes).
    let perfect = post_residual == 0;
    let tiny = post_residual > 0 && post_residual < 10;
    if perfect {
        score -= 60.0;
    } else if tiny {
        // Residual below the minimum item size is dead space unless it's the only option.
        score += 25.0;
        if fitting_bins_count <= 1 {
            score -= 30.0; // last chance: accept the dead space
        }
    }

    // Harmonic-class reward: residual divisible into likely future item sizes.
    let classes: [u32; 6] = [10, 20, 25, 40, 50, 100];
    let mut class_bonus = 0.0;
    for (i, &c) in classes.iter().enumerate() {
        if post_residual > 0 && post_residual % c == 0 {
            class_bonus += 6.0 * (i as f64 + 1.0);
        }
    }
    score -= class_bonus;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 45.0;
            } else if slack < 10 {
                score += 10.0; // creates dead space for the next item
            } else {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; mildly penalize hogging space it could use elsewhere.
            score += 5.0;
        }
    }

    // Last-chance bin before opening a new one: strong reward to avoid bin proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are nearly full or very fragmented.
    if bin_residual == bin_capacity {
        let avg = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = avg / bin_capacity as f64;
        // Penalize opening a new bin normally; reward it when mean residual is low (bins full).
        score += 15.0 - 40.0 * (1.0 - fragmentation) - 10.0 * progress;
        if item_size > 70 {
            score -= 10.0; // large items prefer fresh bins
        }
    }

    // Mild preference for filling bins with high residual (reduce open-bin count pressure).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Tie-break: favor bins whose residual is an integer-friendly fraction of capacity.
    let half = bin_capacity / 2;
    if post_residual == half || post_residual == bin_capacity / 4 || post_residual == (bin_capacity * 3) / 4 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward filling the bin deeply (waste-aware tightness).
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow and mean residual is high.
        score += 8.0 + 2.5 * open_bins_count as f64 + 0.3 * mean_residual;
        // Early in the stream, opening bins is cheaper; later, expensive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If the next item is large, a fresh bin may be valuable.
        if next_item_size > 50 {
            score -= 15.0;
        }
    } else {
        // Existing bin: mild reward when many bins are open (consolidation).
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the post-residual can host the next item exactly, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Heavy penalty for small unusable dead space (< 10 units, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            // Next item fits here: reward proportional to how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill * fill;
        } else {
            // Next item cannot use the leftover space: penalize proportionally.
            let waste = next_item_size as f64 / post_residual as f64;
            score += 25.0 * waste;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.5 * ((post_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 15.0 + 5.0 * open_f;
        // But if current item is large and nothing tight exists, new bin is fine.
        if item_size > 60 && post_residual < 20 {
            score -= 30.0;
        }
    }

    // Mild stream-progression pressure: later in stream, favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus when post_residual is small.
    let t = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - t) * (1.0 - t) * (item_size as f64 / bin_capacity as f64);

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if next_item_size > bin_residual {
            // Next item won't fit anywhere in this bin anyway; neutral.
            score += 0.0;
        } else {
            score += 10.0; // blocks next item that could have fit
        }
        // Perfect pairing: post_residual == next_item_size exactly.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early
    // in the stream or when the current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score = waste * (1.0 + 2.0 * progress);
        if open_bins_count == 0 {
            score -= 1000.0; // must open first bin
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // nothing fits, must open
        }
        // Late in the stream, prefer filling existing bins.
        if progress > 0.7 && fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 3 && mean_residual > 40.0 {
        score -= 6.0 * (mean_residual - 40.0) / 60.0;
    }

    // Mild time-horizon shaping: as stream progresses, tighten more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), smoothed by progress
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Non-linear coupling: dead space hurts more as stream progresses
    score += 20.0 * norm_pr * norm_pr * (progress * progress);

    // Reward tight fits (small post_residual) with a smooth saturating term
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalty if this bin is much fuller than the mean residual (hoarding tight space)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead: penalize if next item cannot fit the post residual
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 10.0 * (1.0 + gap) * (0.5 + progress);
    } else if next_item_size > 0 {
        // Reward leaving space usable by the next item
        score -= 6.0 * (1.0 - norm_pr);
    }

    // New-bin candidate handling: prefer opening a new bin only when the fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // A fresh bin has post_residual = cap - item_size; large post_residual = large item = good use
        // Penalize new bin when item is small (wasteful), reward when item is large
        let item_frac = item_size as f64 / cap;
        score += 30.0 * (1.0 - item_frac) * (1.0 - item_frac);
        // Early in stream, opening new bins is cheaper
        score -= 10.0 * (1.0 - progress);
    } else {
        // Slight bonus for reusing existing bins, scaled by how many are open
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual (modulo arithmetic) ----
    // Residuals aligned to common item granularities are more reusable.
    let pr = post_residual;
    if pr % 20 == 0 {
        score -= 3.0;
    } else if pr % 10 == 0 {
        score -= 1.5;
    } else if pr % 5 == 0 {
        score -= 0.5;
    }

    // Integer-division thresholds: tiny residuals are dead space.
    if pr < 10 {
        score += 6.0;
    } else if pr < 20 {
        score += 2.0;
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let prf = pr as f64;
        if prf >= n {
            // this bin can also host the next item: reward proportionally
            score -= 2.0 + 3.0 * (n / c);
        } else {
            // leftover too small for next item: penalize the dead gap
            score += (n - prf).min(20.0);
        }
    }

    // ---- Last-chance bin before opening a new one ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // ---- New-bin candidate decision ----
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / c;
        // Opening a new bin is attractive for large items, unattractive
        // when other bins already fit (each alternative adds pressure).
        score += 12.0 * (1.0 - frac) * (fitting_bins_count as f64).min(5.0);
        score -= 6.0 * frac;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * progress;
    } else {
        // mild preference for tighter existing bins relative to mean residual
        score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no plausible item (>=1)
    // can use are pure waste; tiny gaps are worst.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // penalize small gaps super-linearly (dead space)
        if gap <= 10.0 {
            score += 25.0 * (10.0 - gap + 1.0);
        }
        // reward gaps that could still fit a mid/large item
        if gap >= 40.0 {
            score -= 8.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Tightness reward: filling most of the bin is good.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_frac;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage proliferation of bins when mean residual
    // is already large (enough slack exists to consolidate).
    let slack = mean_residual - item_size as f64;
    if slack > 0.0 {
        score += 0.8 * open_bins_count as f64 * (1.0 - fill_frac);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward
    // this placement strongly (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // next item cannot use the gap: penalize proportionally to gap size
            score += 0.5 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (i.e., mean residual is small relative to the item).
    if bin_residual == bin_capacity {
        if mean_residual >= item_size as f64 {
            // an open bin can host it: penalize opening a new bin
            score += 35.0 + 2.0 * open_bins_count as f64;
        } else {
            // nothing fits well: new bin is reasonable, slight discount
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of next item into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect two-item fill
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward tight fits, decay with slack
            score -= 30.0 * (-slack / 25.0).exp();
        } else {
            // next item cannot fit here: post_residual becomes dead space unless small
            let dead = (next_item_size - post_residual) as f64;
            score += 8.0 * (dead / 40.0).min(1.0);
        }
    } else {
        // last item: prefer minimal post residual
        score -= 5.0;
    }

    // Penalize creating unusable dead space relative to smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny sliver is wasted
    }

    // Relative-to-mean coupling: bins tighter than mean are precious, prefer using loose bins
    let diff = bin_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += 0.3 * diff; // loose bin: cheaper to use
    } else {
        score += 0.15 * diff; // tight bin: slight penalty but keep dominance of fit
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 10.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
        if fitting_bins_count == 1 {
            // an open bin fits; discourage opening a new one unless item huge
            score += item_size as f64 * 0.2;
        }
        // late in stream, opening fresh bins is fine for large items
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual, non-linear).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (1.0 - tightness) * 40.0;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that cannot fit even the smallest conceivable item,
    // scaled by how "wasted" it is relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no good fit exists. Penalize new bins mildly, more so when other bins fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0;
        if fitting_bins_count >= 1 {
            score += 20.0 * fitting_bins_count as f64;
        }
        // Opening a new bin is more acceptable early in the stream
        // (more future items to fill it) and when the item is large.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 25.0;
        score -= item_size as f64 * 0.15;
    }

    // Lookahead: if the next item would fit exactly in the post-residual,
    // reward this placement strongly (chaining placements).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Next item fits: mild reward proportional to remaining slack after next item.
            let after_next = post_residual - next_item_size;
            score -= 10.0 * (after_next as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here: slight penalty if we leave a gap just below next size.
            score += 5.0;
        }
    }

    // Prefer bins with below-average residual (consolidate waste in few bins),
    // so fuller bins get priority.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for using already-open bins to limit bin count growth.
    if !is_new_bin {
        score -= 8.0;
    }

    // Late in the stream, avoid creating small unusable gaps more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < item_size {
        score += progress * 12.0;
    }

    // Many open bins with high mean residual: encourage filling existing ones harder.
    if open_bins_count > 3 && mean_residual > 30.0 && !is_new_bin {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        + 12.0 * (pr / cap) * (pr / cap) * (0.5 + progress)
        - 20.0 * (pr / cap) * (1.0 - progress) * (1.0 - progress);

    // Penalize dead space that cannot fit the lookahead item (smooth quadratic)
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 25.0 * gap * gap * cap;
    }

    // Reward placements that leave room for the next item (smooth coupling)
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = pr - next_item_size as f64;
        score -= 10.0 * (slack / cap) * (1.0 - slack / cap);
    }

    // Last-chance bonus: smooth sigmoid-like reward when few fitting bins
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 15.0 * scarcity * (pr / cap) * (1.0 - pr / cap);

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.5 * (open_bins_count as f64).sqrt() * progress * (pr / cap);

    // Tie-break toward bins tighter than the mean residual (smooth quadratic)
    score += 3.0 * ((pr - mean_residual) / cap) * ((pr - mean_residual) / cap);

    // New-bin candidate: prefer it only when residuals are highly fragmented
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress) - 4.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize post residuals that fall into "unusable" harmonic classes.
    // Classes based on integer division thresholds of capacity (C=100 nominal).
    let c = bin_capacity as u32;
    if post_residual > 0 {
        // Class boundaries: (0,10], (10,20], (20,50], (50,80], (80,100)
        if post_residual <= c / 10 {
            score += 25.0; // tiny sliver, nearly dead space
        } else if post_residual <= c / 5 {
            score += 12.0;
        } else if post_residual <= c / 2 {
            score -= 4.0; // mid class, still useful for small items
        } else {
            score -= 10.0; // large residual remains, good
        }
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Modulo arithmetic on post_residual: residues near multiples of 10 are
    // more likely to be filled by future items drawn from a 10-grid-ish stream.
    let r = post_residual % 10;
    if post_residual > 0 && r != 0 {
        score += 3.0 + r as f64 * 0.4; // off-grid residual slightly penalized
    } else if post_residual > 0 {
        score -= 3.0; // on-grid residual: future items may align
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current residuals are fragmented
    // or item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / mean_residual.max(1.0);
        score = (item_size as f64) - 15.0 * (1.0 - pressure.min(2.0) / 2.0);
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing else fits, must open
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild pressure to fill existing bins as open bin count grows.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest future item (<= 10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize residuals that cannot fit the lookahead item (k=2 lookahead):
    // if the next item cannot use this gap, it is likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward perfect or near-perfect fits (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // this bin would leave a large unusable gap; encourage consolidation.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mean-residual coupling: placing into a bin whose residual is far below
    // the mean (tight bin) is good; prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight preference to keep the new-bin option competitive only when
    // this placement leaves a very large residual AND many bins are open.
    if post_residual > 50 && open_bins_count > 4 {
        score += 10.0;
    }

    // Mild stream-progression term: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better (already baseline).

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here afterwards: reward proportionally to how snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 + 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit after placement: penalize wasted potential,
            // worse when post_residual is small (dead space).
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 3.0 + 10.0 * (1.0 - dead);
        }
    }

    // Prefer bins tighter than the mean residual (fill crowded bins first).
    score -= 2.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // relative to capacity and no good fit exists.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score += 8.0 - 12.0 * large;
        // Opening is more attractive late in the stream when open bins are fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 2.0 * progress;
    }

    // Mild preference for keeping the number of open bins bounded early on.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize small dead space more than large (dead-space curvature)
        let dead = post_residual as f64;
        score += 30.0 / dead; // small residuals get extra penalty
        if dead > item_size as f64 {
            score += 5.0; // residual can still host a future item of this size
        } else {
            score += 10.0; // likely unusable dead space
        }
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when item is large
    // relative to typical residuals or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let size_pressure = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 40.0 + 30.0 * (1.0 - size_pressure) + 20.0 * progress;
        if open_bins_count > 3 {
            new_bin_score -= 10.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            new_bin_score -= 10.0;
        }
        score = new_bin_score;
    }

    // Mild tie-break toward fuller bins overall
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual (tight packing)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer moderate residuals; late, strongly prefer tiny residuals.
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr.powi(4) * (0.5 + progress);
    score += poly * cap * 0.35;

    // Dead-space penalty: residuals too small for the smallest plausible item
    if pr > 0 && pr < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits in the post residual
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 8.0 + 12.0 * norm_pr;
        } else {
            score += 5.0 * (1.0 - norm_pr);
        }
    }

    // Prefer bins with residual below mean (tighter bins), smooth coupling
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 15.0;

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * norm_pr * 10.0;

    // New-bin candidate: make it attractive only when current fits are bad
    if bin_residual == bin_capacity {
        let bad_fit = norm_pr_of_item(item_size, cap);
        score = cap - 20.0 * (1.0 - bad_fit) + 40.0 * bad_fit * progress;
    }

    score
}

fn norm_pr_of_item(item_size: u32, cap: f64) -> f64 {
    // fraction of capacity consumed by item, smooth-squashed
    let x = item_size as f64 / cap;
    x * x
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are precious.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residuals that few item sizes (1..=100) can fill are worse.
    // Fraction of item sizes that could still fit into this residual.
    if post_residual > 0 {
        let usable = post_residual.min(100) as f64 / 100.0;
        // Small residuals that are not exactly matchable get penalized.
        let mod10 = post_residual % 10;
        let mod5 = post_residual % 5;
        if mod10 != 0 {
            score += (10 - mod10) as f64 * 0.8; // push toward multiples of 10
        }
        if mod5 == 0 && mod10 != 0 {
            score -= 2.0; // multiples of 5 are decent secondary classes
        }
        // Very small unusable slivers
        if post_residual < 5 {
            score += 15.0 * (1.0 - usable);
        }
    } else {
        score -= 25.0; // perfect fit is best possible
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // harmonic class: does next item land on a good residual after being placed?
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            } else if next_post % 5 == 0 {
                score -= 5.0;
            } else {
                score += (next_post % 10) as f64 * 0.3;
            }
        } else {
            // next item cannot use this bin's remainder; residual likely dead
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer tighter bins when many bins are open (consolidation pressure).
    let tightness = 1.0 - (bin_residual as f64) / cap;
    score -= tightness * (open_bins_count as f64).sqrt() * 2.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // opening a new bin is penalized mildly; but if current fit is terrible,
        // the base score (residual = capacity) is already high, so this acts as fallback.
        let stream_progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 10.0 * stream_progress; // later in stream, prefer reusing bins
        if post_residual == bin_capacity {
            // empty-bin call: post_residual == capacity; keep base high so it loses
            // unless item is huge relative to typical residual.
            score -= item_size as f64 * 0.1;
        }
    }

    // Mean residual anchoring: bins far below mean residual are "tight", favor them.
    score += (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are unusable for any
    // future item (min size 1..100 stream; treat tiny slivers as waste).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Soft penalty zone: gaps of 10..20 are hard to fill later.
    else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins; penalize the empty new-bin candidate.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // placing into a below-average-residual bin tightens the fleet.
    if bin_residual != bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Lookahead: if next item fits the post-residual exactly-ish, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: mild dead-space penalty.
        score += 5.0;
    }

    // Early in the stream, be slightly more willing to keep bins tidy.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // next item fits here too: mild reward proportional to closeness
            let gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot use the post residual: penalize dead space
            let wasted = post_residual as f64;
            let next_rel = next_item_size as f64 / bin_capacity as f64;
            score += 0.5 * wasted * next_rel;
        }
    }

    // Penalize residuals that are too small to ever be useful (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on a bad fit
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - post_residual as f64);

    // Prefer fuller bins early; late in stream, allow opening new bins for large gaps
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress);

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let bad_open = open_bins_count == 0
            || (fitting_bins_count == 0)
            || (post_residual as f64 > mean_residual + 20.0 && fitting_bins_count <= 2);
        if bad_open {
            score -= 200.0;
        } else {
            score += 250.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual), but penalize tiny useless slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // dead space too small for any item
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else if next_item_size > post_residual && post_residual < next_item_size.min(10) {
            score += 4.0; // this bin becomes useless for the lookahead item
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin is only attractive when existing
    // residuals are poor (high mean residual spread) or many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (mean_residual / bin_capacity as f64) - (item_size as f64 / bin_capacity as f64);
        // If mean residual barely exceeds item size, fits are tight -> avoid new bin.
        score += 40.0 - 20.0 * pressure - 10.0 * progress;
        if fitting_bins_count > 2 {
            score += 15.0; // plenty of alternatives; keep new bin as fallback
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: must open new bin
        }
    }

    // Mild preference for filling bins with larger residuals relative to mean.
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate aggressively into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.02 * open_bins_count as f64;

    // Prefer bins whose residual is close to item size (best fit shape).
    score += 0.15 * ((bin_residual - item_size) as f64).powi(2) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: penalize leftover space, but with non-linear (quadratic) shaping
    let mut score = pr * (1.0 + pr_norm * pr_norm);

    // Stream-progress coupling: later in stream, penalize waste more aggressively
    score += 20.0 * progress * pr_norm * (1.0 - pr_norm);

    // Non-linear coupling of item size with progress: large items late are precious fits
    score -= 15.0 * item_norm * item_norm * (0.5 + progress);

    // Lookahead: reward bins whose post-residual can fit the next item (smooth interaction)
    let fits_next = if next_item_size > 0 { (pr - next_norm * cap).max(0.0) / cap } else { 0.0 };
    score -= 12.0 * fits_next * (1.0 + progress);

    // Mean-residual deviation: prefer bins near the mean residual (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bonus: smooth reward when few fitting bins
    let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
    score -= 10.0 * scarcity * (1.0 - pr_norm);

    // Open-bin pressure: many open bins -> favor filling existing ones (non-linear in count)
    let pressure = (open_bins_count as f64).ln() / (1.0 + (open_bins_count as f64).ln());
    score -= 6.0 * pressure * item_norm;

    // New-bin candidate: make empty bin attractive only when post-residual is large
    if bin_residual == bin_capacity {
        score = cap - 30.0 * (1.0 - progress) - 10.0 * item_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    let post_frac = post_residual as f64 / cap;
    let class = (post_frac * 8.0).floor() as i32; // 0..7 harmonic slots

    // Reward residuals that align with reusable size classes (multiples of 10/20/25).
    let reusable = (post_residual % 10 == 0) as f64 * 3.0
        + (post_residual % 20 == 0) as f64 * 2.0
        + (post_residual % 25 == 0) as f64 * 2.0;
    score -= reusable;

    // Penalize tiny dead space (unusable slivers) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 + 4.0 * (1.0 - slack / cap);
        // Harmonic bonus: next item size in a "nice" class matching residual.
        if (next_item_size + post_residual) % 25 == 0 {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize proportionally to wasted class.
        score += 2.0 + post_frac * 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: keep it competitive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = mean_residual / cap;
        score += 5.0 - 4.0 * crowd.min(1.0);
        if post_frac > 0.0 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 2.0; // fresh bin gives lookahead room
        }
    }

    // Stream progression: tighten thresholds late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * reusable;
    score += class as f64 * 0.25 * (1.0 - progress);

    // Prefer bins tighter than the mean residual (good fits first).
    score += ((mean_residual - bin_residual as f64) / cap) * 1.5;

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64).ln() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" zone
    // (too small for the smallest plausible item, 1..=10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Semi-dead zone: only very small items can use it
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (post_residual small but still usable)
    if post_residual >= 10 && post_residual <= 30 {
        score -= 30.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // placement is genuinely good (tight fit already discounted above).
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (new bin would add full capacity).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // reward this placement; if next item would be blocked by dead space, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 35.0; // next item creates a near-perfect fill
            } else {
                score += slack as f64 * 0.3;
            }
        } else {
            score += 10.0; // next item cannot use this bin's remainder
        }
    }

    // Mean-residual coupling: bins far below the mean residual are "loose";
    // prefer concentrating into tight bins (small residual relative to mean).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.4;

    // New-bin candidate handling: an empty bin should only win when every
    // open bin would leave severe dead space or can't fit well.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // room to pair items in a fresh bin
        }
    }

    // Mild stream-progression pressure: late in the stream, consolidate more
    // aggressively to avoid ending with many half-empty bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), with a slight super-linear penalty on waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post_residual as f64 {
            let gap = (post_residual as f64 - next) / bin_capacity as f64;
            score -= 18.0 * (1.0 - gap); // strong reward for chaining next item
            score -= 6.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            // Next item cannot use the leftover: dead space penalty scaled by overshoot.
            let overshoot = (next - post_residual as f64) / bin_capacity as f64;
            score += 10.0 * overshoot.min(1.0);
        }
    } else {
        // Last item: just minimize waste.
        score -= 2.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "precious" tight bins;
    // prefer using loose bins unless the fit is excellent.
    let res = post_residual as f64;
    if res > mean_residual {
        score += 3.0 * (res - mean_residual) / bin_capacity as f64;
    } else {
        // tight bin: only worth it if fit is very tight
        if post_residual <= 5 {
            score -= 8.0;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        if fit_quality > 0.5 {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: make a fresh bin attractive only when no open bin
    // offers a decent fit (post_residual large relative to capacity).
    if bin_residual == bin_capacity {
        // Default penalty so open bins with decent fits win.
        score = 45.0 + post_residual as f64 * 0.2;
        // If the item is large relative to capacity, a fresh bin is naturally good.
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 20.0;
        }
        // If next item is huge and won't fit anywhere else anyway, fresh bin is fine.
        if next_item_size >= 70 {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for too many open bins relative to progress (bin proliferation control).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 4.0 + 10.0 * progress {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual (waste).
    score -= 0.6 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * item_size as f64;

    // Penalize unusable dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: later in the stream, prefer consolidation over opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    // Global state: many open bins -> discourage new bins, encourage filling.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins deviating below mean residual (tighter bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: mild penalty so it is chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host a pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 12.0 * (norm_pr - 0.5) * (norm_pr - 0.5) * (1.0 + 2.0 * p2);
    score -= 18.0 * norm_pr * (1.0 - norm_pr) * (0.5 + p3);
    // Reward tight fits more strongly later in the stream
    score -= (item_size as f64 / cap) * 6.0 * (1.0 + p2);
    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let unusable = (pr - nx).max(0.0);
        score += 0.08 * unusable * (1.0 + p3);
        if nx <= pr {
            score -= 5.0 * (1.0 - p3);
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - 0.5 * progress);
    }
    // Mildly discourage proliferating bins when mean residual is high
    score += 0.02 * (open_bins_count as f64) * (mean_residual / cap - norm_pr).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes modulo small divisors.
    let pr = post_residual;
    // Dead-space penalty: residuals that are unusable for typical small items.
    if pr > 0 {
        let usable = (pr / 10).min(8) as f64; // how many "10-size" units fit
        score -= usable * 0.6;
    }
    // Perfect fit reward
    if pr == 0 {
        score -= 40.0;
    }

    // Modulo-class coupling: residuals divisible by common size classes are
    // more likely reusable; reward them.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 3.0;
    }
    // Penalize awkward classes (prime-ish / odd residuals)
    if pr % 2 == 1 && pr < 20 {
        score += 5.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder: penalize large leftovers
            score += 0.05 * (pr as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new one.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced when many items remain and
        // current bins are fragmented.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 55.0 - 15.0 * fragmentation - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size && next_item_size > bin_capacity - item_size {
            // opening fresh bin lets next item pair with this one
            score -= 8.0;
        }
    }

    // Mild preference for filling fuller bins (small residual before placement).
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose leftover can still host a plausible next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // leftover too small for lookahead -> dead space risk
        }
    }

    // Last chance before opening a new bin: strongly favor using this bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual < bin_capacity {
        score -= pressure * 3.0;
    } else {
        // New-bin candidate: attractive only when item is large and open bins are fragmented.
        score += 20.0 - pressure * 2.0;
        if item_size >= 50 && mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Prefer bins tighter than the mean residual (good fits cluster).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: strong reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.35 * slack;
        } else {
            // Next item won't fit: penalize dead space it creates.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.6 * dead;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (better fits).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Prefer low post-residual (tight packing) nonlinearly.
    score += 0.004 * (post_residual as f64).powi(2);

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when item fits well elsewhere.
        score += 15.0 + 20.0 * progress + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin is great if next item also fits
        }
    }

    score
}
